Object.assign(window.TEM8_DICTIONARY, {"bagpipes":{"oxford":{"phon":"ˈbæɡpaɪps","pos":"noun","senses":[{"en":"a musical instrument played especially in Scotland. The player blows air into a bag held under the arm and then slowly forces the air out through pipes to produce a noise.","cn":"风笛","ex":{"en":"The distant skirl of bagpipes was heard.","cn":"远处传来风笛的声音。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"风笛","en":"Bagpipes are a musical instrument that is traditionally played in Scotland. You play the bagpipes by blowing air through a pipe into a bag, and then squeezing the bag to force the air out through other pipes."}]},"media":{"img":["media/pic/pipe_comp.jpg","media/thumb/bagpipes.jpg"],"uk":"media/uk/bagpipes__gb_1.mp3","us":"media/us/bagpipes__us_1.mp3"},"examples":[{"en":"bagpipe music","cn":"风笛乐"}]},"barbarism":{"media":{"uk":"media/uk/barbarism__gb_1.mp3","us":"media/us/barbarism__us_1.mp3"},"oxford":{"phon":"ˈbɑːbərɪzəm","pos":"noun","senses":[{"en":"a state of not having any education, respect for art, etc.","cn":"野蛮；未开化；不文明","ex":{"en":"the long, slow descent of the Roman Empire into barbarism","cn":"罗马帝国漫长而缓慢地陷入野蛮状态"}},{"en":"cruel or violent behaviour","cn":"残暴的行为；残酷","ex":{"en":"the barbarism of war","cn":"战争的残酷"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"野蛮（行为）；凶残（行为）","en":"If you refer to someone's behaviour as barbarism, you strongly disapprove of it because you think that it is extremely cruel or uncivilized.","ex":{"en":"We do not ask for the death penalty: barbarism must not be met with barbarism.","cn":"我们不赞成死刑：不能以暴制暴。"}}]},"examples":[{"en":"the barbarism of war","cn":"战争的残酷"},{"en":"cultural barbarism","cn":"文化荒漠"}]},"baseball":{"media":{"img":["media/pic/sports_comp.jpg","media/thumb/baseball.jpg"],"uk":"media/uk/baseball__gb_1.mp3","us":"media/us/baseball__us_1.mp3"},"oxford":{"phon":"ˈbeɪsbɔːl","pos":"noun","senses":[{"en":"a game played especially in the US by two teams of nine players, using a bat and ball. Each player tries to hit the ball and then run around four bases before the other team can return the ball.","cn":"棒球运动","g":"[uncountable]","ex":{"en":"a baseball bat/team/cap/fan/player/game","cn":"棒球棒；棒球队；棒球帽；棒球迷；棒球运动员；棒球赛"}},{"en":"the ball used in this game","cn":"棒球","g":"[countable]"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"棒球运动","en":"In America, baseball is a game played by two teams of nine players. Each player from one team hits a ball with a bat and then tries to run around three bases and get to the home base before the other team can get the ball back."},{"pos":"N-COUNT 可数名词","cn":"棒球","en":"A baseball is a small hard ball which is used in the game of baseball."}]},"examples":[{"en":"a baseball bat/team/stadium","cn":"棒球球棒/球队/球场"},{"en":"a pair of baseball boots","cn":"一双棒球靴"}]},"barber":{"oxford":{"phon":"ˈbɑːbə(r)","pos":"noun","senses":[{"en":"a person whose job is to cut men’s hair and sometimes to shave them","cn":"（为男子理发、修面的）理发师"},{"en":"a shop where men can have their hair cut","cn":"（男子）理发店","lab":"both British English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（为男性理发的）男理发师","en":"A barber is a man whose job is cutting men's hair.","ex":{"en":"...a barber's shop in south London.","cn":"伦敦南部的理发店"}},{"pos":"N-SING 单数名词","cn":"理发店","en":"A barber's is a shop where a barber works.","ex":{"en":"My Mum took me to the barber's.","cn":"我妈带我理发去了。"}}]},"media":{"uk":"media/uk/barber__gb_1.mp3","us":"media/us/barber__us_1.mp3"}},"banner":{"media":{"uk":"media/uk/banner__gb_1.mp3","us":"media/us/banner__us_1.mp3"},"oxford":{"phon":"ˈbænə(r)","pos":"noun","senses":[{"en":"a long piece of cloth with a message on it that is carried between two poles or hung in a public place to show support for something","cn":"横幅；旗幡","ex":{"en":"A huge banner over the street said ‘Welcome home’.","cn":"街上挂着巨大的横幅，上面写着“欢迎回家”。"}},{"en":"a title or advertisement across the top or bottom or down the side of a page on the internet","cn":"网页顶部、底部或侧面的标题或广告","ex":{"en":"They put up a website banner advising customers to order early.","cn":"他们在网站上贴出了横幅，建议顾客尽早订购。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（通常指在抗议或集会中用两根竿子撑开的）横幅，标语","en":"A banner is a long strip of cloth with something written on it. Banners are usually attached to two poles and carried during a protest or rally.","ex":{"en":"...a large crowd of students carrying banners denouncing the government","cn":"一大群高举谴责政府的条幅的学生"}},{"pos":"PHRASE 短语","cn":"在…的旗帜下；为了…的事业（或信仰）","en":"If someone does something under the banner of a particular cause, idea, or belief, they do it saying that they support that cause, idea, or belief.","ex":{"en":"All countries march as one nation under the banner of friendship.","cn":"所有国家在友谊的旗帜下团结一致，共同前进。"}}]},"examples":[{"en":"Protesters carried a banner reading ‘Save our Wildlife’.","cn":"抗议者打着“救救我们的野生生物”字样的横幅。"},{"en":"The onlookers were shouting, cheering, and waving banners.","cn":"观众挥动着横幅﹐又是叫喊又是欢呼。"}]},"bach":{"oxford":{"phon":"bætʃ","pos":"noun","senses":[{"en":"a small holiday house","cn":"度假小屋"}]},"media":{"uk":"media/uk/bach__gb_1.mp3","us":"media/us/bach__us_1.mp3"}},"bauxite":{"media":{"uk":"media/uk/bauxite__gb_1.mp3","us":"media/us/bauxite__us_1.mp3"},"oxford":{"phon":"ˈbɔːksaɪt","pos":"noun","senses":[{"en":"a soft mineral from which aluminium is obtained","cn":"铝土矿"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"铝土矿；铝矾土","en":"Bauxite is a clay-like substance from which aluminium is obtained."}]}},"backs":{"oxford":{"phon":"bæk","pos":"noun","senses":[{"en":"the part of the human body that is on the opposite side to the chest, between the neck and the tops of the legs; the part of an animal's body that corresponds to this （","cn":"人体或动物的）背部，背；腰背"},{"en":"the row of bones in the middle of the back","cn":"脊柱；脊梁骨"}]},"media":{"uk":"media/uk/back__gb_1.mp3","us":"media/us/back__us_1.mp3"}},"basket":{"oxford":{"phon":"ˈbɑːskɪt","pos":"noun","senses":[{"en":"a container for holding or carrying things. Baskets are made of long thin pieces of material that bends and twists easily, for example plastic, wire or wicker.","cn":"篮；篓；筐","ex":{"en":"a shopping basket","cn":"购物篮"}},{"en":"the amount contained in a basket","cn":"一篮，一筐，一篓（的量）","ex":{"en":"a basket of fruit","cn":"一筐水果"}},{"en":"a facility on a website that records the items that you select to buy","cn":"（网站上的）购物车，购物篮","lab":"both especially North American English","ex":{"en":"Click to drop items into your shopping basket.","cn":"点击将商品放入购物车。"}},{"en":"the net and the metal ring it hangs from, high up at each end of a basketball court; a point that is scored by throwing the ball through this net","cn":"（篮球运动的）篮；投篮得分","ex":{"en":"to make/shoot a basket","cn":"投球得分／入篮"}},{"en":"a number of different goods or currencies","cn":"一组（不同的物品或货币）","lab":"economics","ex":{"en":"the value of the rupee against a basket of currencies","cn":"卢比对各种货币的比值"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"篮子；篓子；筐子","en":"A basket is a stiff container that is used for carrying or storing objects. Baskets are made from thin strips of materials such as straw, plastic, or wire woven together.","ex":{"en":"...big wicker picnic baskets filled with sandwiches.","cn":"装满三明治的柳编野餐篮"}},{"pos":"N-COUNT 可数名词","cn":"（用于比较不同货币或商品价值的）一篮子，一组（货币或商品）","en":"In economics, a basket of currencies or goods is the average or total value of a number of different currencies or goods.","ex":{"en":"The pound's value against a basket of currencies hit a new low of 76.9.","cn":"英镑对一篮子货币的比价创下76.9的新低。"}},{"pos":"N-COUNT 可数名词","cn":"（篮球运动的）篮","en":"In basketball, the basket is a net hanging from a ring through which players try to throw the ball in order to score points."},{"pos":"See also:","cn":"","en":"→see: ;"}]},"media":{"img":["media/ldoce/img/basket.jpg","media/pic/basket_comp.jpg"],"uk":"media/uk/basket__gb_1.mp3","us":"media/us/basket__us_1.mp3"},"examples":[{"en":"a clothes/laundry basket (= in which dirty clothes are put before being washed) （","cn":"存放待洗衣服的）洗衣筐"},{"en":"the value of the rupee against a basket of currencies","cn":"卢比对各种货币的比值"}]},"ban":{"media":{"uk":"media/uk/ban__gb_1.mp3","us":"media/us/ban__us_1.mp3"},"oxford":{"phon":"bæn","pos":"verb","senses":[{"en":"to decide or say officially that something is not allowed","cn":"明令禁止；取缔","ex":{"en":"The law effectively bans smoking in all public places.","cn":"法律事实上禁止在所有公共场所吸烟。"}},{"en":"to order somebody not to do something, go somewhere, etc., especially officially","cn":"禁止（某人）做某事（或去某处等）","g":"[usually passive]","lab":"British English","ex":{"en":"He was banned from the meeting.","cn":"他被取消了出席会议的资格。"}},{"en":"an official rule that says that something is not allowed","cn":"禁令","ex":{"en":"a smoking ban","cn":"禁烟令"},"pos":"noun"},{"en":"an official decision that means a person is not allowed to do something or go somewhere for a period of time","cn":"禁令","ex":{"en":"a five-year driving ban for various offences","cn":"因多种违法行为招致的五年禁驾"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（明令）禁止；取缔","en":"To ban something means to state officially that it must not be done, shown, or used.","ex":{"en":"Canada will ban smoking in all offices later this year.","cn":"加拿大将从今年晚些时候起在办公场所全面禁烟。"}},{"pos":"N-COUNT 可数名词","cn":"禁令","en":"A ban is an official ruling that something must not be done, shown, or used.","ex":{"en":"The General also lifted a ban on political parties.","cn":"将军同时取消了对政党的禁令。"}},{"pos":"VERB 动词","cn":"禁止（做某事）","en":"If you are banned from doing something, you are officially prevented from doing it.","ex":{"en":"He was banned from driving for three years.","cn":"他被吊扣驾照3年。"}}]},"examples":[{"en":"She's been banned from leaving Greece while the allegations are investigated.","cn":"当局对指控进行调查期间，禁止她离开希腊。"},{"en":"He was banned from the meeting.","cn":"他被取消了出席会议的资格。"}]},"barrels":{"oxford":{"phon":"ˈbærəl","pos":"noun","senses":[{"en":"a large round container, usually made of wood or metal, with flat ends and, usually, curved sides","cn":"桶"},{"en":"the contents of or the amount contained in a barrel; a unit of measurement in the oil industry equal to between 120 and 159 litres","cn":"一桶（的量）；桶（石油计量单位，相当于 120 到 159 升）"}]}},"basketball":{"media":{"img":["media/pic/sports_comp.jpg","media/thumb/basketball.jpg"],"uk":"media/uk/basketball__gb_1.mp3","us":"media/us/basketball__us_1.mp3"},"oxford":{"phon":"ˈbɑːskɪtbɔːl","pos":"noun","senses":[{"en":"a game played by two teams of five players, using a large ball which players try to throw into a high net hanging from a ring","cn":"篮球运动","g":"[uncountable]","ex":{"en":"a basketball game/coach/team/player","cn":"篮球比赛／教练／球队／运动员"}},{"en":"the ball used in this game","cn":"篮球","g":"[countable]","ex":{"en":"to dribble/dunk a basketball","cn":"运球/扣篮"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"篮球运动","en":"Basketball is a game in which two teams of five players each try to score goals by throwing a large ball through a circular net fixed to a metal ring at each end of the court."},{"pos":"N-COUNT 可数名词","cn":"篮球","en":"A basketball is a large ball which is used in the game of basketball."}]},"examples":[{"en":"a basketball game/coach/team","cn":"篮球比赛/教练/球队"}]},"battle":{"oxford":{"phon":"ˈbætl","pos":"noun","senses":[{"en":"a fight between armies, ships or planes, especially during a war; a violent fight between groups of people","cn":"战役；战斗；搏斗","g":"[countable, uncountable]","ex":{"en":"Napoleon was defeated at the Battle of Waterloo.","cn":"拿破仑在滑铁卢战役中战败。"}},{"en":"a competition, an argument or a struggle between people or groups of people trying to win power or control","cn":"较量；争论；斗争","g":"[countable]","ex":{"en":"She finally won her six-year battle for compensation.","cn":"她终于赢得了六年的赔偿斗争。"}},{"en":"a determined effort that somebody makes to solve a difficult problem or succeed in a difficult situation","cn":"奋斗；斗争","g":"[countable, usually singular]","ex":{"en":"She finally lost her long battle against cancer.","cn":"她与癌症的长期斗争最终失败了。"}},{"en":"to try very hard to achieve something difficult or to deal with something unpleasant or dangerous","cn":"搏斗；奋斗；斗争","ex":{"en":"Both teams battled hard.","cn":"两队拼得很厉害。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"战役；战斗","en":"A battle is a violent fight between groups of people, especially one between military forces during a war.","ex":{"en":"...the victory of King William III at the Battle of the Boyne.","cn":"国王威廉三世在博因河战役中的胜利"}},{"pos":"N-COUNT 可数名词","cn":"（为争取成功或控制权的）斗争，冲突","en":"A battle is a conflict in which different people or groups compete in order to achieve success or control.","ex":{"en":"...a renewed political battle over Britain's attitude to Europe.","cn":"围绕英国对欧洲的态度问题展开的新一轮政治斗争"}},{"pos":"N-COUNT 可数名词","cn":"（在艰难环境中的）奋争，斗争","en":"You can use battle to refer to someone's efforts to achieve something in spite of very difficult circumstances.","ex":{"en":"...the battle against crime","cn":"打击犯罪的斗争"}},{"pos":"V-RECIP 相互动词","cn":"与…抗争；与…搏斗；同…作战","en":"To battle with an opposing group means to take part in a fight or contest against them. In American English, you can also say that one group or person is battling another.","ex":{"en":"Thousands of people battled with police and several were reportedly wounded","cn":"数千人与警方发生冲突，据报道有数人在冲突中受伤。"}},{"pos":"VERB 动词","cn":"奋战；（与…）搏斗（在英国英语中用battle against something或with something，在美国英语中用battle something）","en":"To battle means to try hard to do something in spite of very difficult circumstances. In British English, you battle against something or with something. In American English, you battle something.","ex":{"en":"Doctors battled throughout the night to save her life.","cn":"医生们彻夜奋战来挽救她的生命。"}},{"pos":"PHR-RECIP 相互短语","cn":"作战；交战；竞争","en":"If one person or group does battle with another, they take part in a battle or contest against them. You can also say that two people or groups do battle .","ex":{"en":"...the notorious Montonero guerrilla group who did battle with the army during the dirty war","cn":"曾在那场肮脏的战争中与这支部队交战的臭名昭著的蒙特内罗游击队"}},{"pos":"PHRASE 短语","cn":"成功的一半；成功的重要条件","en":"If you say that something is half the battle, you mean that it is the most important step towards achieving something.","ex":{"en":"Choosing the right type of paint for the job is half the battle.","cn":"选对了涂料，这项工作就成功了一半。"}},{"pos":"PHRASE 短语","cn":"战线已划定；对垒之势已成","en":"If you say that the battle lines are drawn between opposing groups or people, you mean that they are ready to start fighting or arguing, and that it has become clear what the main points of conflict or disagreement will be.","ex":{"en":"The battle lines were drawn after the government refused to budge from its final offer.","cn":"政府拒绝改变其最后条件之后，双方对立态势趋向明朗。"}},{"pos":"PHRASE 短语","cn":"作无望成功的尝试","en":"If you are fighting a losing battle, you are trying to achieve something but are not going to be successful.","ex":{"en":"The crew fought a losing battle to try to restart the engines.","cn":"全体船员努力尝试重新启动发动机，但结果徒劳无功。"}},{"pos":"PHR-RECIP 相互短语","cn":"一决胜负；一决高低","en":"If one group or person battles it out with another, they take part in a fight or contest against each other until one of them wins or a definite result is reached. You can also say that two groups or two people battle it out .","ex":{"en":"In the Cup Final, Leeds battled it out with the old enemy, Manchester United","cn":"在足总杯决赛中，利兹联队和宿敌曼彻斯特联队一决胜负。"}},{"pos":"PHRASE 短语","cn":"虽败犹胜/ 虽胜犹败","en":"If you say that someone has lost the battle ,but won the war, you mean that although they have been defeated in a small conflict they have won a larger, more important one of which it was a part. If you say that someone has won the battle but lost the war, you mean that they have won the small conflict but lost the larger one.","ex":{"en":"The strikers may have won the battle, but they lost the war.","cn":"罢工者们虽胜犹败。"}},{"pos":"PHRASE短语","cn":"考验意志的持久战","en":"A battle of wills is a situation that involves people who try to defeat each other by refusing to change their own aims or demands and hoping that their opponents will weaken first.","ex":{"en":"The President offered compromises to parliament to defuse the battle of wills over who should wield power.","cn":"总统对国会作出让步，以求结束这场旷日持久的权力争斗。"}},{"pos":"PHRASE 短语","cn":"智慧的较量；斗智","en":"If you refer to a situation as a battle of wits, you mean that it involves people with opposing aims who compete with each other using their intelligence, rather than force.","ex":{"en":"With chess you're involved in a battle of wits from start to finish.","cn":"下国际象棋从头到尾都是在比拼智慧。"}}]},"media":{"uk":"media/uk/battle__gb_1.mp3","us":"media/us/battle__us_1.mp3"},"examples":[{"en":"The two leaders are battling for control of the government.","cn":"两位领导人在为控制政府而斗争。"},{"en":"The two sides will battle it out in the final next week.","cn":"双方将于下周决赛中决一胜负。"}]},"bandit":{"media":{"uk":"media/uk/bandit__gb_1.mp3","us":"media/us/bandit__us_1.mp3"},"oxford":{"phon":"ˈbændɪt","pos":"noun","senses":[{"en":"a member of an armed group of thieves who attack travellers","cn":"土匪","ex":{"en":"Buses driving through the mountains have been attacked by bandits.","cn":"驶经山区的公共汽车遭到匪徒袭击。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指没有法纪的地区的）强盗，土匪，歹徒","en":"Robbers are sometimes called bandits, especially if they are found in areas where the law has broken down.","ex":{"en":"This is real bandit country.","cn":"这是一个不折不扣的强盗横行的国家。"}}]},"examples":[{"en":"They travelled 30 miles through bandit country.","cn":"他们走了30英里﹐穿过强盗横行的乡间。"}]},"ba":{"oxford":{"phon":"ˌbiː ˈeɪ","pos":"noun","senses":[{"en":"a first university degree in an arts subject (the abbreviation for ‘Bachelor of Arts’)","cn":"文学士（全写为 Bachelor of Arts，大学文科的初级学位）","lab":"British English","ex":{"en":"to be/have/do a BA","cn":"是文学士；有文学士学位；攻读文学士"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"文学士学位","en":"A BA is a first degree in an arts or social science subject. BA is an abbreviation for (缩略=) 'Bachelor of Arts'.","ex":{"en":"I did a BA in film making.","cn":"我获得了电影摄制的文学士学位。"}},{"pos":"","cn":"（置于人名后）文学士","en":"BA is written after someone's name to indicate that they have a BA.","ex":{"en":"...Helen Rich, BA (Hons).","cn":"…海伦·里奇（荣誉）文学士"}}]},"media":{"uk":"media/uk/ba__gb_1.mp3","us":"media/us/ba__us_1.mp3"},"examples":[{"en":"( BrE ) Darren Green BA","cn":"文学士达伦 · 格林"},{"en":"to be/have/do a BA","cn":"是文学士；有文学士学位；攻读文学士"}]},"backwards":{"media":{"uk":"media/uk/backwards__gb_1.mp3","us":"media/us/backwards__us_1.mp3"},"oxford":{"phon":"ˈbækwədz","pos":"adverb","senses":[{"en":"towards a place or position that is behind","cn":"向后","ex":{"en":"I lost my balance and fell backwards.","cn":"我没有站稳，仰面摔倒。"}},{"en":"in the opposite direction to the usual one","cn":"朝反方向；倒着","ex":{"en":"‘Ambulance’ is written backwards so you can read it in the mirror.","cn":"ambulance 是倒着写的，以便在镜中认读。"}},{"en":"towards a worse state","cn":"每况愈下地","ex":{"en":"I felt that going to live with my parents would be a step backwards.","cn":"我觉得回去和我父母一同生活会更糟。"}},{"en":"if you put on a piece of clothing backwards, you make a mistake and put the back where the front should be","cn":"（衣服）前后颠倒（或前后穿反）","lab":"North American English"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"向后；朝后","en":"If you move or look backwards, you move or look in the direction that your back is facing.","ex":{"en":"The diver flipped over backwards into the water","cn":"潜水员向后翻身入水。"}},{"pos":"ADV 副词","cn":"倒转地；逆向地；相反地","en":"If you do something backwards, you do it in the opposite way to the usual way.","ex":{"en":"He works backwards, building a house from the top downwards.","cn":"他把工序倒过来了，从上往下建房子。"}},{"pos":"ADV 副词","cn":"倒退地；后退地；退步地","en":"You use backwards to indicate that something changes or develops in a way that is not an improvement, but is a return to old ideas or methods.","ex":{"en":"Greater government intervention in businesses would represent a step backwards.","cn":"政府加强对企业的干涉将是一种倒退。"}},{"pos":"PHRASE 短语","cn":"来来回回；往复","en":"If someone or something moves backwards and forwards, they move repeatedly first in one direction and then in the opposite direction.","ex":{"en":"Draw the floss backwards and forwards between the teeth.","cn":"将牙线在齿间来回拉动。"}},{"pos":"PHRASE 短语","cn":"熟知，对…了如指掌（美国英语中作know something backward and forward）","en":"In British English, if you say that someone knows something backwards, you are emphasizing that they know it very well. In American English, you say that someone knows something backward and forward .","ex":{"en":"I asked about one or two things that interest me and she really did know it all backwards.","cn":"我问了一两样我感兴趣的东西，她的确都了如指掌。"}},{"pos":"","cn":"","en":"to bend over backwards→see: ;"}]},"examples":[{"en":"I felt that going to live with my parents would be a step backwards.","cn":"我觉得回去和我父母一同生活会更糟。"},{"en":"‘Ambulance’ is written backwards so you can read it in the mirror. * ambulance","cn":"是倒着写的，以便在镜中认读。"}]},"basin":{"oxford":{"phon":"ˈbeɪsn","pos":"noun","senses":[{"en":"a large bowl that has taps and is fixed to the wall in a bathroom, used for washing your hands and face in","cn":"（卫生间里的）洗手盆，洗脸盆","lab":"both especially British English","ex":{"en":"He washed his hands in the basin.","cn":"他在脸盆里洗手。"}},{"en":"a large round bowl for holding liquids or (in British English) for preparing foods in; the amount of liquid, etc. in a basin","cn":"盆；（英式英语）调菜盆；一盆（的量）","ex":{"en":"a pudding basin","cn":"布丁盆"}},{"en":"an area of land around a large river with streams running down into it","cn":"流域","ex":{"en":"the Amazon Basin","cn":"亚马孙河流域"}},{"en":"a place where the earth’s surface is lower than in other areas of the world","cn":"盆地；凹地；海盆","lab":"specialist","ex":{"en":"the Pacific Basin","cn":"太平洋海盆"}},{"en":"a sheltered area of water providing a safe harbour for boats","cn":"港池；内港；内湾；船坞","ex":{"en":"a yacht basin","cn":"停放游艇的内港"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"盆；大碗","en":"A basin is a large or deep bowl that you use for holding liquids, or for mixing or storing food.","ex":{"en":"Place the eggs and sugar in a large basin.","cn":"把鸡蛋和糖放在一个大碗里。"}},{"pos":"N-COUNT 可数名词","cn":"同 washbasin","en":"A basin is the same as a washbasin .","ex":{"en":"...a cast-iron bath with a matching basin and wc.","cn":"铸铁浴缸及配套的洗涤槽和马桶"}},{"pos":"N-COUNT 可数名词","cn":"流域","en":"The basin of a large river is the area of land around it from which streams run down into it.","ex":{"en":"...the Amazon basin.","cn":"亚马孙河流域"}},{"pos":"N-COUNT 可数名词","cn":"盆地；洼地","en":"In geography, a basin is a particular region of the world where the earth's surface is lower than in other places.","ex":{"en":"...countries around the Pacific Basin.","cn":"太平洋盆地的周边国家"}},{"pos":"N-COUNT 可数名词","cn":"泊船处","en":"A basin is a partially enclosed area of deep water where boats or ships are kept."}]},"media":{"uk":"media/uk/basin__gb_1.mp3","us":"media/us/basin__us_1.mp3"},"examples":[{"en":"a yacht basin","cn":"停放游艇的内港"},{"en":"the Amazon Basin","cn":"亚马逊河流域"}]},"barely":{"media":{"uk":"media/uk/barely__gb_1.mp3","us":"media/us/barely__us_1.mp3"},"oxford":{"phon":"ˈbeəli","pos":"adverb","senses":[{"en":"in a way that is just possible but only with difficulty","cn":"仅仅；刚刚；勉强可能","ex":{"en":"He could barely read and write.","cn":"他几乎无法读写。"}},{"en":"in a way that almost does not happen or exist","cn":"几乎不；几乎没有","ex":{"en":"She barely acknowledged his presence.","cn":"她只略微向他打了个招呼。"}},{"en":"just; certainly not more than (a particular amount, age, time, etc.)","cn":"刚好；不超过（某个数量、年龄、时间等）","ex":{"en":"Barely 50% of the population voted.","cn":"仅有 50% 的人口投票。"}},{"en":"only a very short time before","cn":"刚才；刚刚","ex":{"en":"I had barely started speaking when he interrupted me.","cn":"我刚刚开始讲话，他便打断了我。"}}]},"collins":{"senses":[{"pos":"ADV-BRD-NEG 广义否定结构副词","cn":"刚刚；勉强；仅仅","en":"You use barely to say that something is only just true or only just the case.","ex":{"en":"Anastasia could barely remember the ride to the hospital","cn":"阿纳斯塔西娅几乎记不起来怎么去的医院。"}},{"pos":"ADV-BRD-NEG 广义否定结构副词","cn":"刚刚…（就）","en":"If you say that one thing had barely happened when something else happened, you mean that the first event was followed immediately by the second.","ex":{"en":"The Boeing 767 had barely taxied to a halt before its doors were flung open","cn":"这架波音767刚刚停住，它的舱门就弹开了。"}}]},"examples":[{"en":"He was barely 20 years old and already running his own company.","cn":"他只有 20 岁，却已经营起自己的公司了。"},{"en":"I had barely started speaking when he interrupted me.","cn":"我刚刚开始讲话，他便打断了我。"}]},"baby":{"media":{"uk":"media/uk/baby__gb_1.mp3","us":"media/us/baby__us_1.mp3","img":["media/ldoce/img/baby.jpg"]},"oxford":{"phon":"ˈbeɪbi","pos":"noun","senses":[{"en":"a very young child or animal","cn":"婴儿；幼崽","lab":"especially US English","ex":{"en":"The baby's crying!","cn":"婴儿在哭！"}},{"en":"the youngest member of a family or group","cn":"（家庭或团体中）最年幼的成员","lab":"informal","ex":{"en":"He's the baby of the team.","cn":"他在队里年纪最小。"}},{"en":"a person who behaves like a young child and is easily upset","cn":"幼稚的人；孩子气的人","lab":"disapproving","ex":{"en":"Stop crying and don't be such a baby.","cn":"别哭了，别这么孩子气。"}},{"en":"a word used to address somebody, especially your wife, husband or partner, in a way that expresses love but that can be offensive if used by a man to a woman he does not know","cn":"宝贝儿，心肝儿（尤用于对爱人的昵称。男子用以称呼不相识的女子则有冒犯之嫌）","lab":"especially North American English, informal，，"},{"en":"baby vegetables are a very small version of particular vegetables, or are vegetables that are picked when they are very small","cn":"（蔬菜）小型的，幼嫩的","ex":{"en":"baby carrots","cn":"小胡萝卜"},"pos":"adjective"},{"en":"to treat somebody with too much care, as if they were a baby","cn":"婴儿般对待；百般呵护","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"婴儿；婴孩","en":"A baby is a very young child, especially one that cannot yet walk or talk.","ex":{"en":"She used to take care of me when I was a baby","cn":"我还在襁褓中时，她曾经照顾过我。"}},{"pos":"N-COUNT 可数名词","cn":"（动物）幼崽；幼兽；幼鸟","en":"A baby animal is a very young animal.","ex":{"en":"...a baby elephant.","cn":"幼象"}},{"pos":"ADJ 形容词","cn":"（蔬菜）幼嫩的","en":"Baby vegetables are vegetables picked when they are very small.","ex":{"en":"Serve with baby new potatoes.","cn":"配上小个的新土豆。"}},{"pos":"N-VOC; N-COUNT 称呼名词；可数名词","cn":"宝贝儿（昵称，尤用于年轻女性）","en":"Some people use baby as an affectionate way of addressing someone, especially a young woman, or referring to them.","ex":{"en":"You have to wake up now, baby","cn":"该起床了，宝贝儿。"}},{"pos":"PHRASE 短语","cn":"把婴儿和洗澡水一起倒掉；将精华连同糟粕一起丢弃；不分好坏地全盘抛弃","en":"If you throw the baby out with the bath water, you lose the good parts of something as well as the bad parts, because you reject it as a whole instead of just removing what is bad."},{"pos":"PHRASE 短语","cn":"替他人擦屁股；替别人干苦差事","en":"If you are left holding the baby, you are put in a situation where you are responsible for something, often in an unfair way because other people fail or refuse to take responsibility for it.","ex":{"en":"You go off round the world, and leave me to hold the baby.","cn":"你满世界地跑，把苦差事都扔给我。"}}]},"examples":[{"en":"He changed to another job and we were left holding the baby.","cn":"他换了工作，把活儿甩给我们。"},{"en":"Stop crying and don't be such a baby.","cn":"别哭了，别这么孩子气。"}]},"balaclava":{"media":{"uk":"media/uk/balaclava__gb_1.mp3","us":"media/us/balaclava__us_1.mp3"},"oxford":{"phon":"ˌbæləˈklɑːvə","pos":"noun","senses":[{"en":"a type of hat made of wool that covers most of the head, neck and face","cn":"巴拉克拉瓦盔式帽，巴拉克拉瓦羊毛头罩（裹住头、颈和脸的大部分）","ex":{"en":"The two attackers were wearing balaclavas.","cn":"两名袭击者戴着巴拉克拉法帽。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"盔式大绒帽","en":"A balaclava is a tight woollen hood that covers every part of your head except your face."}]}},"bargain":{"media":{"uk":"media/uk/bargain__gb_1.mp3","us":"media/us/bargain__us_1.mp3"},"oxford":{"phon":"ˈbɑːɡən","pos":"noun","senses":[{"en":"a thing bought for less than the usual price","cn":"减价品；便宜货","lab":"especially British English","ex":{"en":"I picked up a few good bargains in the sale.","cn":"我在减价期间买了几样挺不错的便宜货。"}},{"en":"an agreement between two or more people or groups, to do something for each other","cn":"协议；交易","ex":{"en":"He and his partner had made a bargain to tell each other everything.","cn":"他和他的合伙人约定，要互通信息，毫无保留。"}},{"en":"to discuss prices, conditions, etc. with somebody in order to reach an agreement that is acceptable","cn":"（与某人就某事）讨价还价，商讨条件","ex":{"en":"In the market dealers were bargaining with growers over the price of coffee.","cn":"在市场上商人正和种植者就咖啡的价格进行商谈。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"便宜货；廉价货","en":"Something that is a bargain is good value for money, usually because it has been sold at a lower price than normal.","ex":{"en":"At this price the wine is a bargain","cn":"这种葡萄酒卖这个价真是很便宜。"}},{"pos":"N-COUNT 可数名词","cn":"交易；协议","en":"A bargain is an agreement, especially a formal business agreement, in which two people or groups agree what each of them will do, pay, or receive.","ex":{"en":"I'll make a bargain with you. I'll play hostess if you'll include Matthew in your guest-list","cn":"我们说定了，如果你能把马修也邀请来的话我就做东。"}},{"pos":"VERB 动词","cn":"商谈；交涉；谈判；讨价还价","en":"When people bargain with each other, they discuss what each of them will do, pay, or receive.","ex":{"en":"They prefer to bargain with individual clients, for cash","cn":"在现款方面，他们更愿意同散户打交道。"}},{"pos":"PHRASE 短语","cn":"极力讨价还价；提出苛刻的交易条件","en":"If people drive a hard bargain, they argue with determination in order to achieve a deal which is favourable to themselves.","ex":{"en":"...a law firm with a reputation for driving a hard bargain.","cn":"在讲价方面颇有名气的律师事务所"}},{"pos":"PHRASE 短语","cn":"此外；而且；另外","en":"You use into the bargain when mentioning an additional quantity, feature, fact, or action, to emphasize the fact that it is also involved. You can also say in the bargain in American English.","ex":{"en":"This machine is designed to save you effort, and keep your work surfaces tidy into the bargain","cn":"这种机器既省力，又能保持工作台面的整洁。"}},{"pos":"PHRASE 短语","cn":"履行协议","en":"If you keep your side of the bargain, you do what you have promised or arranged to do.","ex":{"en":"Dealing with this dictator wasn't an option. He wouldn't have kept his side of the bargain.","cn":"别跟这个独裁者打交道，他不会信守诺言的。"}},{"pos":"","cn":"","en":"相关词组：bargain for"}]},"examples":[{"en":"When he agreed to answer a few questions, he got more than he bargained for (= he got more questions, or more difficult ones, than he had expected).","cn":"他同意回答几个问题，不料却招来了一堆难以回答的问题。"},{"en":"They felt that their leaders had bargained away their freedom.","cn":"他们认为他们的领导人以牺牲他们的自由做了交易。"}]},"badge":{"oxford":{"phon":"bædʒ","pos":"noun","senses":[{"en":"a small piece of metal or plastic, with a design or words on it, that a person wears or carries to show that they belong to an organization, support something, have achieved something, have a particular rank, etc.","cn":"徽章；奖章","ex":{"en":"She wore a badge saying ‘Vote for Coates’.","cn":"她戴着一枚徽章，上面写着“投科茨一票”。"}},{"en":"a piece of material that you sew onto clothes as part of a uniform","cn":"（制服上的）标记，标识","lab":"British English","ex":{"en":"the school badge","cn":"校徽"}},{"en":"a symbol of a particular quality or status","cn":"标志；象征","ex":{"en":"His gun was a badge of power for him.","cn":"他的枪对他而言是权力的标志。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"徽章，证章（美国英语通常用button指金属小圆徽章）","en":"A badge is a piece of metal or cloth which you wear to show that you belong to an organization or support a cause. American English usually uses button to refer to a small round metal badge."},{"pos":"N-SING 单数名词","cn":"标志；标记；象征","en":"Any feature which is regarded as a sign of a particular quality can be referred to as a badge .","ex":{"en":"Being a Communist was a badge of honour for thousands of trade union activists.","cn":"对数千工会积极分子来说，成为共产党员是荣誉的象征。"}}]},"media":{"img":["media/pic/jewellery_comp.jpg","media/thumb/badge.jpg"],"uk":"media/uk/badge__gb_1.mp3","us":"media/us/badge__us_1.mp3"},"examples":[{"en":"She wore a badge saying ‘Vote for Coates’.","cn":"她戴着一枚徽章，上面写着“投科茨一票”。"},{"en":"His gun was a badge of power for him.","cn":"他的枪对他而言是权力的标志。"}]},"baking":{"oxford":{"phon":"ˈbeɪkɪŋ","pos":"noun","senses":[{"en":"the process of cooking using dry heat in an oven","cn":"烤制；烘焙","ex":{"en":"I've always enjoyed baking.","cn":"我一直喜欢做烘焙。"}},{"en":"bread, cakes, etc. that somebody has made","cn":"烘焙食品","ex":{"en":"Try some of Ellie's delicious home baking.","cn":"尝尝埃莉自己做的美味烘焙。"}},{"en":"extremely hot","cn":"灼热的；炽热的","ex":{"en":"We waited for hours in the baking sun.","cn":"我们在烈日下等了几个小时。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"炎热的；灼热的","en":"You can use baking to describe weather or a place that is very hot indeed.","ex":{"en":"...a baking July day","cn":"7月酷热的一天"}}]},"media":{"uk":"media/uk/baking__gb_1.mp3","us":"media/us/baking__us_1.mp3"},"examples":[{"en":"a baking dish/tin","cn":"烤盘；烤模"},{"en":"I’m baking!","cn":"我快热死了！"}]},"based":{"media":{"uk":"media/uk/based__gb_1.mp3","us":"media/us/based__us_1.mp3"},"oxford":{"phon":"beɪst","pos":"adjective","senses":[{"en":"if one thing is based on another, it uses it or is developed from it","cn":"（以某事）为基础（或根据）","ex":{"en":"The movie is based on a real-life incident.","cn":"这部电影以真实事件为蓝本。"}},{"en":"if a person or business is based in a particular place, that is where they live or work, or where the work of the business is done","cn":"在…居住（或工作）；基地（或总部）在…","ex":{"en":"We're based in Chicago.","cn":"我们住在芝加哥。"}},{"en":"containing something as an important part or feature","cn":"以…为重要部分（或特征）；以…为主","ex":{"en":"lead-based paints","cn":"铅基涂料"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"以…为生活（或工作）中心的；以…为基地的；总部设在…的","en":"If you are based in a particular place, that is the place where you live or do most of your work. See also base .","ex":{"en":"Both firms are based in Kent","cn":"两个公司的总部都设在肯特市。"}}]},"examples":[{"en":"The report is based on figures from six different European cities.","cn":"报告的依据是欧洲六个不同城市的数据。"},{"en":"The movie is based on a real-life incident.","cn":"这部电影以真实事件为蓝本。"}]},"badminton":{"oxford":{"phon":"ˈbædmɪntən","pos":"noun","senses":[{"en":"a game like tennis played by two or four people, usually indoors. Players hit a small light kind of ball, originally with feathers around it (= a shuttlecock) across a high net using a racket.","cn":"羽毛球运动"},{"en":"a three-day eventing competition (= type of horse riding competition) held every year on land around Badminton House, a large house near Bath, England.","cn":"羽毛球：每年三天的比赛比赛，在英格兰巴斯附近的一栋大房子羽毛球馆周围的土地上举行。","pos":""}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"羽毛球运动","en":"Badminton is a game played by two or four players on a rectangular court with a high net across the middle. The players try to score points by hitting a small object called a shuttlecock across the net using a racket."}]},"media":{"img":["media/ldoce/img/badminton.jpg","media/pic/racketsports_comp.jpg"],"uk":"media/uk/badminton__gb_1.mp3","us":"media/us/badminton__us_1.mp3"}},"barrel":{"oxford":{"phon":"ˈbærəl","pos":"noun","senses":[{"en":"a large round container, usually made of wood or metal, with flat ends and, usually, curved sides","cn":"桶","ex":{"en":"a beer/wine barrel","cn":"啤酒桶；葡萄酒桶"}},{"en":"the contents of or the amount contained in a barrel; a unit of measurement in the oil industry equal to between 120 and 159 litres","cn":"一桶（的量）；桶（石油计量单位，相当于 120 到 159 升）","ex":{"en":"They got through two barrels of beer.","cn":"他们喝了两桶啤酒。"}},{"en":"the part of a gun like a tube through which the bullets are fired","cn":"枪管","ex":{"en":"Tom found himself looking down the barrel of a gun.","cn":"汤姆发现自己正低头看着枪管。"}},{"en":"to move very fast in a particular direction, especially in a way that you cannot control","cn":"（无法控制地）高速行进，飞驰","ex":{"en":"He came barreling down the hill and smashed into a parked car.","cn":"他从山坡上飞驰而下，撞上了一辆停着的车。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"桶","en":"A barrel is a large, round container for liquids or food.","ex":{"en":"The wine is aged for almost a year in oak barrels.","cn":"这葡萄酒已经在橡木桶里存放近一年了。"}},{"pos":"N-COUNT 可数名词","cn":"（石油工业中）一桶的量（相当于159升）","en":"In the oil industry, a barrel is a unit of measurement equal to 159 litres.","ex":{"en":"In 1989, Kuwait was exporting 1.5 million barrels of oil a day","cn":"1989年，科威特每天出口150万桶石油。"}},{"pos":"N-COUNT 可数名词","cn":"枪管","en":"The barrel of a gun is the tube through which the bullet moves when the gun is fired.","ex":{"en":"He pushed the barrel of the gun into the other man's open mouth.","cn":"他把枪管塞进了另一个人的嘴里。"}},{"pos":"VERB 动词","cn":"飞奔；疾驶；高速行驶","en":"If a vehicle or person is barreling in a particular direction, they are moving very quickly in that direction.","ex":{"en":"The car was barreling down the street at a crazy speed.","cn":"这辆车疯了一般沿街疾驶。"}},{"pos":"PHRASE 短语","cn":"全部；完全","en":"If you say, for example, that someone moves or buys something lock, stock, and barrel, you are emphasizing that they move or buy every part or item of it.","ex":{"en":"They dug up their New Jersey garden and moved it lock, stock, and barrel back home.","cn":"他们把在新泽西的花园刨了个遍，然后将里面的东西一样不落地搬回了家。"}},{"pos":"PHRASE 短语","cn":"使…受制于人；使…处于不利地位；迫使…做…","en":"If someone has you over a barrel, they have put you in a difficult situation where you have little choice but to do what they want you to do."},{"pos":"PHRASE 短语","cn":"凑合用劣质的东西；将就行事","en":"If you say that someone is scraping the barrel, or scraping the bottom of the barrel, you disapprove of the fact that they are using or doing something of extremely poor quality."},{"pos":"PHRASE 短语","cn":"非常有趣的事；笑料不断的开心果","en":"If an experience is a barrel of laughs, it is very enjoyable. If someone is a barrel of laughs, they are fun to be with.","ex":{"en":"Weddington is the first to admit she's not exactly a barrel of laughs","cn":"韦丁顿第一个承认自己其实并不爱搞笑。"}}]},"media":{"uk":"media/uk/barrel__gb_1.mp3","us":"media/us/barrel__us_1.mp3","img":["media/ldoce/img/barrel.jpg"]},"examples":[{"en":"They've got us over a barrel. Either we agree to their terms or we lose the money.","cn":"他们让我们别无选择。我们要么答应他们的条件，要么损失这笔钱。"},{"en":"He came barreling down the hill and smashed into a phone booth.","cn":"他沿山坡飞驰下来，撞进了一个电话亭。"}]},"bat":{"oxford":{"phon":"bæt","pos":"noun","senses":[{"en":"a piece of wood with a handle, made in various shapes and sizes, and used for hitting the ball in games such as baseball, cricket and table tennis","cn":"球棒；球拍；球板","ex":{"en":"a baseball/cricket bat","cn":"棒球球棒；板球球板"}},{"en":"an animal like a mouse with wings that flies and feeds at night (= it is nocturnal). There are many types of bat.","cn":"蝙蝠"},{"en":"to hit a ball with a bat, especially in a game of baseball or cricket","cn":"用球板击球，用球棒击球（尤指板球或棒球运动）","g":"[intransitive, transitive]","ex":{"en":"He bats very well.","cn":"他擅长击球。"},"pos":"verb"},{"en":"to hit something small that is flying through the air","cn":"挥打，拍打（空中飞舞的小东西）","g":"[transitive]","ex":{"en":"He batted the wasp away.","cn":"他把那只黄蜂赶跑了。"},"pos":"verb"},{"en":"a very large company that makes cigarettes","cn":"英美烟草公司","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"球棒；球拍","en":"A bat is a specially shaped piece of wood that is used for hitting the ball in baseball, softball, cricket, rounders, or table tennis.","ex":{"en":"...a baseball bat.","cn":"棒球球棒"}},{"pos":"VERB 动词","cn":"轮到击球","en":"When you bat, you have a turn at hitting the ball with a bat in baseball, softball, cricket, or rounders.","ex":{"en":"Australia, put in to bat, made a cautious start.","cn":"轮到澳大利亚队出场击球，他们开始打得很谨慎。"}},{"pos":"N-COUNT 可数名词","cn":"蝙蝠","en":"A bat is a small flying animal that looks like a mouse with wings made of skin. Bats are active at night."},{"pos":"PHRASE 短语","cn":"连眼睛也不眨一下；镇定自若；泰然处之","en":"When something surprising or shocking happens, if someone doesn't bat an eyelid in British English, or doesn't bat an eye in American English, they remain calm and do not show any reaction."},{"pos":"PHRASE 短语","cn":"支持；为…出力","en":"If you go to bat for someone or go in to bat for them, you give them your support.","ex":{"en":"The old judge doesn't like the thought of no one going in to bat for the accused.","cn":"老法官不希望没有人为被告辩护。"}},{"pos":"PHRASE 短语","cn":"（开车）飞一般地，风驰电掣地，飞快地","en":"If you drive like a bat out of hell, you drive extremely fast.","ex":{"en":"He took off for Helsinki like a bat out of hell.","cn":"他飞快赶往赫尔辛基。"}},{"pos":"PHRASE 短语","cn":"独立地；自主地；主动地","en":"If someone does something off their own bat, they do it without anyone else suggesting it.","ex":{"en":"Whatever she did she did off her own bat. Whatever she did was nothing to do with me.","cn":"她所做的一切都是她自己主动要做的。她做的任何事都与我无关。"}},{"pos":"PHRASE 短语","cn":"马上；立刻","en":"If something happens right off the bat, it happens immediately.","ex":{"en":"He learned right off the bat that you can't count on anything in this business.","cn":"他立刻明白在这一行业中不能依靠任何东西。"}}]},"media":{"img":["media/pic/mammals_comp.jpg","media/thumb/bat.jpg"],"uk":"media/uk/bat__gb_1.mp3","us":"media/us/bat__us_1.mp3"},"examples":[{"en":"She didn't bat an eyelid when I told her my news.","cn":"我把我最近的事告诉她时，她一点也不为所动。"},{"en":"It's just an idea we've been batting around.","cn":"这只不过是我们一直在讨论的一种想法。"}]},"bandages":{"oxford":{"phon":"ˈbændɪdʒ","pos":"noun","senses":[{"en":"a strip of cloth used for tying around a part of the body that has been hurt in order to protect or support it","cn":"绷带"},{"en":"to wrap a bandage around a part of the body in order to protect it because it is injured","cn":"用绷带包扎"}]}},"bacteria":{"oxford":{"phon":"bækˈtɪəriə","pos":"noun","senses":[{"en":"the simplest and smallest forms of life. Bacteria exist in large numbers in air, water and soil, and also in living and dead creatures and plants, and are often a cause of disease.","cn":"细菌","ex":{"en":"Neither chilling nor freezing kills all bacteria.","cn":"冷藏和冷冻都不能消灭所有细菌。"}}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"细菌","en":"Bacteria are very small organisms. Some bacteria can cause disease.","ex":{"en":"Chlorine is added to kill bacteria.","cn":"加氯是为了杀死细菌。"}}]},"media":{"uk":"media/uk/bacteria__gb_1.mp3","us":"media/us/bacteria__us_1.mp3"},"examples":[{"en":"bacterial infections/growth","cn":"细菌传染/生长"}]},"bag":{"media":{"img":["media/pic/bags_comp.jpg","media/thumb/shoulderbag.jpg","media/ldoce/img/ldoce_015.png"],"uk":"media/uk/bag__gb_1.mp3","us":"media/us/bag__us_1.mp3"},"oxford":{"phon":"bæɡ","pos":"noun","senses":[{"en":"a container made of cloth, leather, plastic or paper, used to carry things in, especially when shopping or travelling","cn":"手提袋；旅行袋；购物袋","g":"[countable]","sc":"container","ex":{"en":"He was carrying a heavy bag of groceries.","cn":"他提了重重的一袋食品杂货。"}},{"en":"a bag or case that you take when you are travelling; a piece of luggage","cn":"旅行箱；提包；一件行李","g":"[countable]","sc":"container","ex":{"en":"I packed my bags and left for the airport.","cn":"我收拾好行李就动身去了机场。"}},{"en":"the amount contained in a bag","cn":"一袋（的量）","g":"[countable]","sc":"amount","ex":{"en":"She ate a bag of chips.","cn":"她吃了一袋炸土豆条。"}},{"en":"a large amount or a large number of something","cn":"大量；很多","g":"[uncountable, plural]","lab":"British English, informal，，","sc":"amount","ex":{"en":"Get in! There's bags of room.","cn":"进来吧！地方很空。"}},{"en":"dark circles or loose folds of skin under the eyes, as a result of getting old or lack of sleep","cn":"黑眼圈；眼袋","g":"[plural]","sc":"under eyes"},{"en":"an offensive word for an older woman who you think is unpleasant or angry","cn":"丑妇，泼妇（指讨厌或坏脾气的年长女人）","g":"[countable]","lab":"especially British English, informal，，","sc":"unpleasant woman"},{"en":"all the birds, animals, etc. shot or caught on one occasion","cn":"（一次）猎获物","g":"[countable, usually singular]","sc":"birds/animals","ex":{"en":"We got a good bag today.","cn":"我们今天猎获甚丰。"}},{"en":"to put something into bags","cn":"把…装进袋子","sc":"put into bags","ex":{"en":"The fruit is washed, sorted and bagged at the farm.","cn":"水果在农场洗净、分拣并装袋。"},"pos":"verb"},{"en":"to catch or kill an animal","cn":"捕获，猎杀（动物）","lab":"informal","sc":"catch animal","ex":{"en":"We bagged ten fish in two hours.","cn":"我们在两个小时内捕获了十条鱼。"},"pos":"verb"},{"en":"to score a goal, point, etc.","cn":"得分","lab":"informal","sc":"in sport","ex":{"en":"Harkin bagged two goals in last night's win.","cn":"在昨晚获胜的那场比赛中哈金射进两球。"},"pos":"verb"},{"en":"to claim something as yours before somebody else claims it; to take something before somebody else can get it","cn":"抢占；占有","lab":"informal","sc":"claim something","ex":{"en":"Sally had managed to bag the two best seats.","cn":"萨莉抢到了那两个最好的位子。"},"pos":"verb"},{"en":"to criticize somebody/something","cn":"批评；挑剔；指责","lab":"Australian English, New Zealand English, informal，，，，","sc":"criticize somebody/something","pos":"verb"},{"en":"to decide not to do something because you think it will not be successful or because you think it will be better to do it later","cn":"（认为不会成功或以后做会更好而）放弃，取消","lab":"North American English, informal，，","sc":"decide not to do something","ex":{"en":"They decided to bag the trip because they were short of cash.","cn":"因为缺钱，他们决定取消这次旅行。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（纸质或塑料）袋","en":"A bag is a container made of thin paper or plastic, for example one that is used in shops to put things in that a customer has bought."},{"pos":"N-COUNT 可数名词","cn":"拎袋；旅行袋","en":"A bag is a strong container with one or two handles, used to carry things in.","ex":{"en":"She left the hotel carrying a shopping bag.","cn":"她提着一个购物袋离开了酒店。"}},{"pos":"N-COUNT 可数名词","cn":"同handbag","en":"A bag is the same as a handbag . →see usage note at:"},{"pos":"N-PLURAL 复数名词","cn":"眼袋","en":"If you have bags under your eyes, you have folds of skin there, usually because you have not had enough sleep."},{"pos":"QUANT 数量词","cn":"大量；很多","en":"If you say there is bags of something, you mean that there is a large amount of it. If you say that there are bags of things, you mean that there are a large number of them.","ex":{"en":"...a hotel with bags of character.","cn":"很有特色的酒店"}},{"pos":"N-COUNT 可数名词","cn":"老娘们；丑老太婆；蠢妇","en":"If someone calls a woman an old bag or a stupid bag, they are insulting her."},{"pos":"VERB 动词","cn":"抢先占有","en":"If you bag something that a lot of people want, you get it for yourself before anyone else can get it.","ex":{"en":"The smart ones will have already bagged their seats by placing cards on them.","cn":"聪明人早已在座位上放一张卡片占住了位子。"}},{"pos":"PHRASE 短语","cn":"囊中之物；稳操胜券；十拿九稳","en":"If you say that something is in the bag, you mean that you are certain that you will get it or achieve it.","ex":{"en":"'I'll get the Republican nomination,' he assured me. 'It's in the bag.'","cn":"“我会得到共和党提名的，”他向我保证，“这是十拿九稳的事。”"}},{"pos":"PHRASE 短语","cn":"背别人甩掉的包袱；背黑锅","en":"If you are left holding the bag, you are put in a situation where you are responsible for something, often in an unfair way because other people fail or refuse to take responsibility for it.","ex":{"en":"I don't want to be left holding the bag if something goes wrong.","cn":"如果出了什么问题，我可不想替人背黑锅。"}},{"pos":"PHRASE 短语","cn":"收拾行李；打点行装","en":"If you pack your bags, you leave a place where you have been staying or living.","ex":{"en":"Police arrived at his hotel and ordered him to pack his bags.","cn":"警察来到他的酒店，命令他收拾行李走人。"}},{"pos":"","cn":"","en":"to let the cat out of the bag→see: ;"},{"pos":"","cn":"","en":"相关词组：bag up"}]},"examples":[{"en":"Dublin bagged two goals in last night's win.","cn":"在昨晚获胜的那场比赛中都柏林队射进了两球。"},{"en":"He threw her out onto the street, bag and baggage.","cn":"他突然把她连人带东西一股脑儿扔到大街上。"}]},"basically":{"media":{"uk":"media/uk/basically__gb_1.mp3","us":"media/us/basically__us_1.mp3"},"oxford":{"phon":"ˈbeɪsɪkli","pos":"adverb","senses":[{"en":"in the most important ways, without considering things that are less important","cn":"大体上；基本上","ex":{"en":"I think we are basically saying the same thing.","cn":"我认为我们说的大体上是一回事。"}},{"en":"used when you are giving your opinion or stating what is important about a situation","cn":"总的说来；从根本上说","ex":{"en":"Basically, there's not a lot we can do about it.","cn":"总的说来，我们能做的有限。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"主要地；基本上","en":"You use basically for emphasis when you are stating an opinion, or when you are making an important statement about something.","ex":{"en":"This gun is designed for one purpose—it's basically to kill people","cn":"这种枪只有一个用途——就是用来杀人。"}},{"pos":"ADV 副词","cn":"大致说来；从根本上来讲","en":"You use basically to show that you are describing a situation in a simple, general way, and that you are not concerned with less important details.","ex":{"en":"Basically you've got two choices","cn":"大致说来，你有两个选择。"}}]},"examples":[{"en":"There have been some problems but basically it's a good system.","cn":"虽然出现过一些问题，但这基本上仍不失为一个好系统。"},{"en":"He basically just sits there and does nothing all day.","cn":"他根本就是一天到晚坐在那儿无所事事。"}]},"bamboo":{"media":{"img":["media/pic/plantlabels_plants_comp.jpg","media/thumb/bamboo.jpg"],"uk":"media/uk/bamboo__gb_1.mp3","us":"media/us/bamboo__us_1.mp3"},"oxford":{"phon":"ˌbæmˈbuː","pos":"noun","senses":[{"en":"a tall plant that is a member of the grass family and has hard hollow stems that are used for making furniture, poles, etc.","cn":"竹；竹子","ex":{"en":"a bamboo grove","cn":"竹林"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"竹；竹子","en":"Bamboo is a tall tropical plant with hard, hollow stems. The young shoots of the plant can be eaten and the stems are used to make furniture.","ex":{"en":"...huts with walls of bamboo.","cn":"竹墙小屋"}}]},"examples":[{"en":"bamboo shoots (= young bamboo plants that can be eaten)","cn":"竹笋"},{"en":"a bamboo grove","cn":"竹林"}]},"balance":{"media":{"uk":"media/uk/balance__gb_1.mp3","us":"media/us/balance__us_1.mp3"},"oxford":{"phon":"ˈbæləns","pos":"noun","senses":[{"en":"a situation in which different things exist in equal, correct or good amounts","cn":"均衡；平衡；均势","g":"[uncountable, singular]","sc":"equal amounts","ex":{"en":"This newspaper maintains a good balance in its presentation of different opinions.","cn":"这份报纸不偏不倚地报道不同的意见。"}},{"en":"the ability to keep steady with an equal amount of weight on each side of the body","cn":"平衡能力","g":"[uncountable]","sc":"of body","ex":{"en":"Athletes need a good sense of balance.","cn":"运动员要有良好的平衡感。"}},{"en":"the amount that is left after taking numbers or money away from a total","cn":"余额","g":"[countable, usually singular]","sc":"money","ex":{"en":"to check your bank balance (= to find out how much money there is in your account)","cn":"核对银行结存"}},{"en":"an amount of money still owed after some payment has been made","cn":"结欠","g":"[countable, usually singular]","sc":"money","ex":{"en":"The balance of $500 must be paid within 90 days.","cn":"500 美元结欠款必须于 90 天之内付清。"}},{"en":"the largest part of a group or an amount; the position of advantage or attention","cn":"大多数；优势地位","sc":"largest part","ex":{"en":"The balance of opinion was that work was more important than leisure.","cn":"大多数人的观点是工作比休闲更重要。"}},{"en":"an instrument for weighing things, with a bar that is supported in the middle and has dishes hanging from each end","cn":"天平；秤","g":"[countable]","sc":"instrument for weighing"},{"en":"to put your body or something else into a position where it is steady and does not fall","cn":"使（在某物上）保持平衡；立稳","g":"[intransitive, transitive]","sc":"keep steady","ex":{"en":"How long can you balance on one leg?","cn":"你单腿能站多久？"},"pos":"verb"},{"en":"to give equal importance to two things or parts of something which are very different","cn":"同等重视（相对的两个事物或方面）","g":"[transitive]","sc":"be/keep equal","ex":{"en":"She tries to balance the needs of her children with those of her employer.","cn":"她努力兼顾孩子和老板的需要。"},"pos":"verb"},{"en":"to be equal in value, amount, etc. to something else that has the opposite effect","cn":"相抵；抵消","g":"[intransitive, transitive]","sc":"be/keep equal","ex":{"en":"The good and bad effects of any decision will usually balance out.","cn":"任何决策的效果往往利弊互见。"},"pos":"verb"},{"en":"to compare the relative importance of two things which are different","cn":"比较（两个不同的事物）；权衡重要性","g":"[transitive]","sc":"compare","ex":{"en":"The cost of obtaining legal advice needs to be balanced against its benefits.","cn":"法律咨询的费用与其效益需权衡一下。"},"pos":"verb"},{"en":"to manage finances so that the money spent is equal to the money received; to show this in the accounts","cn":"使收支平衡；结平（账目）","g":"[transitive]","sc":"money","ex":{"en":"In order to balance the budget severe spending cuts had to be made.","cn":"为了平衡预算，不得不大幅削减了开支。"},"pos":"verb"},{"en":"(of an account) to have an equal amount of money spent and money received","cn":"（账目）收支平衡","g":"[intransitive]","sc":"money","ex":{"en":"I tried to work out why the books wouldn't balance.","cn":"我想要弄清这些账目收支为什么不平衡。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）保持平衡；（使）平稳","en":"If you balance something somewhere, or if it balances there, it remains steady and does not fall.","ex":{"en":"I balanced on the ledge","cn":"我在窗台上站稳。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"平衡能力","en":"Balance is the ability to remain steady when you are standing up.","ex":{"en":"The medicines you are currently taking could be affecting your balance.","cn":"你现在服用的药物可能会影响身体的平衡能力。"}},{"pos":"V-RECIP-ERG","cn":"使（力量、重要性等）相等；使均衡；使持平","en":"If you balance one thing with something different, each of the things has the same strength or importance.","ex":{"en":"Balance spicy dishes with mild ones","cn":"做到辛辣菜和清淡菜比重相当。"}},{"pos":"N-SING 单数名词","cn":"（力量、重要性等的）均衡，均势","en":"A balance is a situation in which all the different parts are equal in strength or importance.","ex":{"en":"Their marriage is a delicate balance between traditional and contemporary values","cn":"他们的婚姻在传统和现代价值观之间保持着微妙平衡。"}},{"pos":"N-SING 单数名词","cn":"（尤指冲突或比赛中的）局面，胜利天平","en":"If you say that the balance tips in your favour, you start winning or succeeding, especially in a conflict or contest.","ex":{"en":"...a powerful new gun which could tip the balance of the war in their favour","cn":"将使他们在战争中占据优势的威力巨大的新型火炮"}},{"pos":"VERB 动词","cn":"权衡；对比；斟酌","en":"If you balance one thing against another, you consider its importance in relation to the other one.","ex":{"en":"She carefully tried to balance religious sensitivities against democratic freedom.","cn":"她谨慎地试图对宗教情感和民主自由两者作出权衡。"}},{"pos":"VERB 动词","cn":"使（预算、经济等）平衡","en":"If someone balances their budget or if a government balances the economy of a country, they make sure that the amount of money that is spent is not greater than the amount that is received.","ex":{"en":"He balanced his budgets by rigid control over public expenditure.","cn":"他通过严格控制公共开支保持预算平衡。"}},{"pos":"V-ERG 及物/不及物动词","cn":"结算（账目）；（使）收支相等","en":"If you balance your books or make them balance, you prove by calculation that the amount of money you have received is equal to the amount that you have spent.","ex":{"en":"...teaching them to balance the books","cn":"教他们结平账目"}},{"pos":"N-COUNT 可数名词","cn":"（银行账户的）余额，余数，结存","en":"The balance in your bank account is the amount of money you have in it.","ex":{"en":"I'd like to check the balance in my account please.","cn":"请查一下我的账户余额。"}},{"pos":"N-SING 单数名词","cn":"（钱款的）剩余部分","en":"The balance of an amount of money is what remains to be paid for something or what remains when part of the amount has been spent.","ex":{"en":"They were due to pay the balance on delivery.","cn":"他们应该在货到时支付余额。"}},{"pos":"PHRASE 短语","cn":"悬而未决；待定","en":"If something hangs in the balance, it is uncertain whether it will happen or continue.","ex":{"en":"The fate of a project which could revolutionise the use of computers in hospitals hangs in the balance.","cn":"可能给医院的计算机使用带来革命的项目仍然前途未明。"}},{"pos":"PHRASE 短语","cn":"保持/失去平衡","en":"If you keep your balance, for example when standing in a moving vehicle, you remain steady and do not fall over. If you lose your balance, you become unsteady and fall over.","ex":{"en":"She was holding onto the rail to keep her balance","cn":"她抓住扶手以保持平衡。"}},{"pos":"PHRASE 短语","cn":"（身体）失去平衡，几近跌倒","en":"If you are off balance, you are in an unsteady position and about to fall.","ex":{"en":"A gust of wind knocked him off balance and he fell face down in the mud.","cn":"一阵大风刮得他失去平衡，脸朝下摔在泥里。"}},{"pos":"PHRASE 短语","cn":"惊慌失措；迷惑不解","en":"If you are thrown off balance by something, you are surprised or confused by it.","ex":{"en":"She was trying to behave as if his visit hadn't thrown her off balance.","cn":"她尽力装作对他的造访并不吃惊。"}},{"pos":"PHRASE 短语","cn":"权衡之后；全面考虑之后；总的来说","en":"You can say on balance to indicate that you are stating an opinion after considering all the relevant facts or arguments.","ex":{"en":"On balance he agreed with Christine.","cn":"总的来说，他同意克里斯蒂娜的意见。"}},{"pos":"","cn":"","en":"相关词组：balance out"}]},"examples":[{"en":"The senator was clearly caught off balance by the unexpected question.","cn":"参议员显然因这意想不到的问题而不知所措。"},{"en":"Tourists often disturb the delicate balance of nature on the island.","cn":"观光客常常干扰岛上脆弱的自然生态平衡。"}]},"bachelors":{"oxford":{"phon":"ˈbætʃələ(r)","pos":"noun","senses":[{"en":"a man who has never been married","cn":"未婚男子；单身汉"},{"en":"a person who has a Bachelor's degree (= a first university degree)","cn":"学士"}]}},"background":{"media":{"uk":"media/uk/background__gb_1.mp3","us":"media/us/background__us_1.mp3"},"oxford":{"phon":"ˈbækɡraʊnd","pos":"noun","senses":[{"en":"the details of a person’s family, education, experience, etc.","cn":"出身背景；学历；经历","g":"[countable]","sc":"family/education, etc.","ex":{"en":"somebody's ethnic/genetic/cultural background","cn":"某人的种族／遗传／文化背景"}},{"en":"the circumstances or past events that help explain why something is how it is; information about these","cn":"（事态发展等的）背景","g":"[countable, usually singular, uncountable]","sc":"past","ex":{"en":"I'm including a little background information on the situation.","cn":"我提供了一些有关情况的背景信息。"}},{"en":"the part of a picture, photograph or view behind the main objects, people, etc.","cn":"后景；背景","g":"[countable, usually singular]","sc":"of picture/photo","ex":{"en":"a photograph with trees in the background","cn":"以树木为远景的照片"}},{"en":"a position in which people are not paying attention to somebody/something or not as much attention as they are paying to somebody/something else","cn":"不显眼的位置；幕后","g":"[singular]","sc":"less important position","ex":{"en":"The camerawork, the background music and the locations all contribute to the mood of the film.","cn":"摄影、背景音乐和地点都有助于影片的气氛。"}},{"en":"a colour or design on which something is painted, drawn, etc.","cn":"底色；底花；底子","g":"[countable, usually singular]","sc":"colour under something","ex":{"en":"The name of the company is written in red on a white background.","cn":"公司的名称是用白底红字写的。"}},{"en":"used to refer to tasks or processes that the user is not actively working on at the present time","cn":"后台运行的","g":"[singular]","sc":"computing","ex":{"en":"Programs can be left running in the background.","cn":"程序可以留在后台运行。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"出身背景；学历；经历","en":"Your background is the kind of family you come from and the kind of education you have had. It can also refer to such things as your social and racial origins, your financial status, or the type of work experience that you have.","ex":{"en":"Moulded by his background, he could not escape the traditional role of strict father","cn":"受成长环境的影响，他摆脱不了严父的传统角色。"}},{"pos":"N-COUNT 可数名词","cn":"（事件或情况的）背景","en":"The background to an event or situation consists of the facts that explain what caused it.","ex":{"en":"The background to the current troubles is provided by the dire state of the country's economy","cn":"目前的问题是在国家经济岌岌可危的背景下出现的。"}},{"pos":"N-SING 单数名词","cn":"背景声音；背景音乐","en":"The background is sounds, such as music, which you can hear but which you are not listening to with your full attention.","ex":{"en":"I kept hearing the sound of applause in the background","cn":"我不断听到隐约的鼓掌声。"}},{"pos":"N-COUNT 可数名词","cn":"（画等的）后景","en":"You can use background to refer to the things in a picture or scene that are less noticeable or important than the main things or people in it.","ex":{"en":"...roses patterned on a blue background","cn":"蓝底上的玫瑰花样"}}]},"examples":[{"en":"He prefers to remain in the background and let his assistant talk to the press.","cn":"他喜欢待在幕后，让他的助理向新闻界发布消息。"},{"en":"Can you give me more background on the company?","cn":"你能多提供一些这家公司的背景资料吗？"}]},"barbiturate":{"oxford":{"phon":"bɑːˈbɪtʃərət","pos":"noun","senses":[{"en":"a powerful drug that makes you feel calm and relaxed or puts you to sleep. There are several types of barbiturate.","cn":"巴比妥酸盐，巴比土酸盐（用于镇静、催眠等）","ex":{"en":"He died from an overdose of barbiturates.","cn":"他因服用过量巴比土而死亡。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"巴比妥酸盐（用于镇定或催眠的药物）","en":"A barbiturate is a drug which people take to make them calm or to help them to sleep.","ex":{"en":"She was addicted to barbiturates.","cn":"她对巴比妥酸盐产生了依赖性。"}}]},"media":{"uk":"media/uk/barbiturate__gb_1.mp3","us":"media/us/barbiturate__us_1.mp3"}},"bandwagon":{"media":{"uk":"media/uk/bandwagon__gb_1.mp3","us":"media/us/bandwagon__us_1.mp3"},"oxford":{"phon":"ˈbændwæɡən","pos":"noun","senses":[{"en":"an activity that more and more people are becoming involved in","cn":"风靡的活动；时尚","ex":{"en":"The World Cup bandwagon is starting to roll.","cn":"世界杯足球赛热潮即将涌起。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"时尚；浪潮","en":"You can refer to an activity or movement that has suddenly become fashionable or popular as a bandwagon .","ex":{"en":"So what is really happening as the information bandwagon starts to roll?","cn":"当信息大潮滚滚而来的时候究竟发生了些什么呢？"}},{"pos":"N-COUNT 可数名词","cn":"（尤指政客顺应的）时髦，潮流","en":"If someone, especially a politician, jumps or climbs on the bandwagon, they become involved in an activity or movement because it is fashionable or likely to succeed and not because they are really interested in it.","ex":{"en":"In recent months many conservative politicians have jumped on the anti-immigrant bandwagon","cn":"最近几个月，很多保守政客都搭上了“反移民”这班车。"}}]},"examples":[{"en":"politicians eager to jump on the environmental bandwagon","cn":"急于随大溜加入环保行列的政客们"},{"en":"The World Cup bandwagon is starting to roll.","cn":"世界杯足球赛热潮即将涌起。"}]},"bar":{"media":{"img":["media/pic/bar_comp.jpg","media/thumb/bar.jpg"],"uk":"media/uk/bar__gb_1.mp3","us":"media/us/bar__us_1.mp3"},"oxford":{"phon":"bɑː(r)","pos":"noun","senses":[{"en":"a place where you can buy and drink alcoholic and other drinks","cn":"酒吧","g":"[countable]","lab":"British English","sc":"for drinks/food","ex":{"en":"We arranged to meet in a bar called the Flamingo.","cn":"我们约定在一家名为“火烈鸟”的酒吧见面。"}},{"en":"a place in which a particular kind of food or drink is the main thing that is served","cn":"（专售某类饮食的）小吃店，小馆子","g":"[countable]","sc":"for drinks/food","ex":{"en":"a sushi bar","cn":"寿司店"}},{"en":"a long wide wooden surface where drinks, etc. are served","cn":"（出售饮料等的）柜台；吧台","g":"[countable]","lab":"humorous","sc":"for drinks/food","ex":{"en":"She was sitting at the bar.","cn":"她坐在吧台那里。"}},{"en":"a piece of something with straight sides","cn":"（长方形）条，块","g":"[countable]","lab":"North American English","sc":"of chocolate/soap","ex":{"en":"a bar of chocolate/soap","cn":"一条巧克力／肥皂"}},{"en":"a long straight piece of metal or wood. Bars are often used to stop somebody from getting through a space.","cn":"长条，棒，栏杆（常用作护栏）","g":"[countable]","sc":"of metal/wood","ex":{"en":"He smashed the window with an iron bar.","cn":"他用铁棒敲碎了窗户。"}},{"en":"a long narrow area at the edge of a computer screen that contains links or pull-down menus or displays information about the website or program that you are using","cn":"计算机屏幕边缘的狭长区域，其中包含链接或下拉菜单或显示有关您正在使用的网站或程序的信息","sc":"in computing"},{"en":"the crossbar of a goal","cn":"（球门的）横梁","g":"[singular]","sc":"in sports","ex":{"en":"His shot hit the bar.","cn":"他射门击中球门的横梁。"}},{"en":"a band of colour or light","cn":"条；带","g":"[countable]","sc":"of colour/light","ex":{"en":"Bars of sunlight slanted down from the tall narrow windows.","cn":"一道道阳光从高高的狭窄窗口斜射下来。"}},{"en":"a thing that stops somebody from doing something","cn":"障碍；羁绊","g":"[countable, usually singular]","sc":"that prevents something","ex":{"en":"At that time being a woman was a bar to promotion in most professions.","cn":"那时在大多数职业中，身为女性就是晋升的障碍。"}},{"en":"one of the short sections of equal length that a piece of music is divided into, and the notes that are in it","cn":"（乐谱的）小节（音乐节拍单位）","g":"[countable]","lab":"British English","sc":"in music","ex":{"en":"four beats to the bar","cn":"每小节四拍"}},{"en":"the profession of barrister (= a lawyer in a higher court)","cn":"大律师职业（可出席高等法庭）","g":"[singular]","lab":"British English","sc":"law","ex":{"en":"to be called to the Bar (= allowed to work as a qualified barrister)","cn":"获得大律师资格"}},{"en":"the profession of any kind of lawyer","cn":"律师职业","g":"[singular]","lab":"North American English","sc":"law"},{"en":"a unit for measuring the pressure of the atmosphere, equal to a hundred thousand newtons per square metre","cn":"巴（气压单位，等于 100 000 牛顿／平方米）","sc":"measurement"},{"en":"a piece of metal with wire wrapped around it that becomes red and hot when electricity is passed through it","cn":"电热棒","g":"[countable]","sc":"in electric fire","ex":{"en":"Switch another bar on if you’re cold.","cn":"如果你觉得冷，请打开另一个酒吧。"}},{"en":"to ban or prevent somebody from doing something","cn":"禁止，阻止（某人做某事）","sc":"prevent","ex":{"en":"Prisoners are barred by law from voting in general elections.","cn":"法律禁止囚犯在大选中投票。"},"pos":"verb"},{"en":"to close something with a bar or bars","cn":"（用铁条或木条）封，堵","g":"[usually passive]","sc":"close with bars","ex":{"en":"All the doors and windows were barred.","cn":"所有的门、窗都加上了铁条。"},"pos":"verb"},{"en":"to block a road, path, etc. so that nobody can pass","cn":"阻挡；拦住","sc":"block","ex":{"en":"Two police officers were barring her exit.","cn":"两名警察挡着她的出路。"},"pos":"verb"},{"en":"except for somebody/something","cn":"除…外","ex":{"en":"The students all attended, bar two who were ill.","cn":"除了两人生病，所有的学生都到了。"},"pos":"preposition"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"酒吧","en":"A bar is a place where you can buy and drink alcoholic drinks.","ex":{"en":"...Devil's Herd, the city's most popular country-western bar.","cn":"“魔鬼之群”——这个城市最火的西部乡村酒吧"}},{"pos":"N-COUNT 可数名词","cn":"酒吧间","en":"A bar is a room in a pub or hotel where alcoholic drinks are served.","ex":{"en":"I'll see you in the bar later","cn":"一会儿酒吧见。"}},{"pos":"N-COUNT 可数名词","cn":"吧台；售酒柜台","en":"A bar is a counter on which alcoholic drinks are served.","ex":{"en":"Michael was standing alone by the bar when Brian rejoined him","cn":"布赖恩回到迈克尔身边时，他正一个人站在吧台旁边。"}},{"pos":"N-COUNT 可数名词","cn":"金属条；金属棒","en":"A bar is a long, straight, stiff piece of metal.","ex":{"en":"...a brick building with bars across the ground floor windows.","cn":"一楼窗户装有铁栅的砖砌建筑"}},{"pos":"PHRASE 短语","cn":"在狱中；被囚禁","en":"If you say that someone is behind bars, you mean that they are in prison.","ex":{"en":"Fisher was behind bars last night, charged with attempted murder","cn":"费希尔被控谋杀未遂，昨晚入狱。"}},{"pos":"N-COUNT 可数名词","cn":"条；棒；长块","en":"A bar of something is a piece of it which is roughly rectangular.","ex":{"en":"What is your favourite chocolate bar?","cn":"你最喜欢哪种巧克力？"}},{"pos":"N-COUNT 可数名词","cn":"（电热炉的）电热棒，电热片","en":"A bar of an electric fire is a piece of metal with wire wound round it that glows and provides heat when the fire is switched on.","ex":{"en":"...a two-bar electric fire with a frayed flex.","cn":"电线已经磨损的双片电热炉"}},{"pos":"VERB 动词","cn":"（用木条，铁条等）闩（门等）","en":"If you bar a door, you place something in front of it or a piece of wood or metal across it in order to prevent it from being opened.","ex":{"en":"For added safety, bar the door to the kitchen.","cn":"为了确保安全，把厨房的门闩上。"}},{"pos":"VERB 动词","cn":"阻拦；阻挡","en":"If you bar someone's way, you prevent them from going somewhere or entering a place, by blocking their path.","ex":{"en":"Harry moved to bar his way","cn":"哈里走过去挡住了他的路。"}},{"pos":"VERB 动词","cn":"禁止；不准","en":"If someone is barred from a place or from doing something, they are officially forbidden to go there or to do it.","ex":{"en":"Amnesty workers have been barred from Sri Lanka since 1982","cn":"从1982年起，大赦国际的工作人员就被禁止进入斯里兰卡。"}},{"pos":"N-COUNT 可数名词","cn":"障碍；阻碍；妨碍","en":"If something is a bar to doing a particular thing, it prevents someone from doing it.","ex":{"en":"One of the fundamental bars to communication is the lack of a universally spoken, common language","cn":"交流的一个基本障碍就是缺少一种大家都说的通用语。"}},{"pos":"PHRASE 短语","cn":"不受任何规则约束；不限任何方式方法；不择手段","en":"If you say that there are no holds barred when people are fighting or competing for something, you mean that they are no longer following any rules in their efforts to win.","ex":{"en":"It is a war with no holds barred and we must prepare to resist","cn":"这是一场没有规则的战争，我们必须作好抵抗的准备。"}},{"pos":"PREP 介词","cn":"除了…以外","en":"You can use bar when you mean 'except'. For example, all the work bar the washing means all the work except the washing.","ex":{"en":"Bar a plateau in 1989, there has been a rise in inflation ever since the mid-1980's","cn":"除1989年物价稳定之外，从20世纪80年代中期开始，通货膨胀就一直在上升。"}},{"pos":"N-PROPER 专有名词","cn":"（英格兰有资格在任何法庭作辩护的）出庭律师职业；（美国的）律师职业，律师界","en":"The Bar is used to refer to the profession of a barrister in England, or of any kind of lawyer in the United States.","ex":{"en":"Robert was planning to read for the Bar.","cn":"罗伯特打算学法律。"}},{"pos":"N-COUNT 可数名词","cn":"（乐曲中的）小节","en":"In music, a bar is one of the several short parts of the same length into which a piece of music is divided."}]},"examples":[{"en":"At that time being a woman was a bar to promotion in most professions.","cn":"那时在大多数职业中，身为女性就是晋升的障碍。"},{"en":"The murderer is now safely behind bars.","cn":"杀人犯现在被关在监狱里，不会再造成危险了。"}]},"barrier":{"media":{"uk":"media/uk/barrier__gb_1.mp3","us":"media/us/barrier__us_1.mp3","img":["media/ldoce/img/barrier.jpg"]},"oxford":{"phon":"ˈbæriə(r)","pos":"noun","senses":[{"en":"an object like a fence that prevents people from moving forward from one place to another","cn":"屏障；障碍物","ex":{"en":"The crowd had to stand behind barriers.","cn":"人群只好站在障碍物后面。"}},{"en":"a gate at a car park or railway station that controls when you may go through by being raised or lowered","cn":"（停车场或火车站等处的）道闸；道闸口","lab":"British English","ex":{"en":"Scan your ticket at the barrier and it will automatically lift.","cn":"在道闸口扫描您的票，道闸杆会自动抬起。"}},{"en":"a problem, rule or situation that prevents somebody from doing something, or that makes something impossible","cn":"障碍；阻力；关卡","lab":"US English","ex":{"en":"the removal of trade barriers","cn":"贸易壁垒的消除"}},{"en":"something that exists between one thing or person and another and keeps them separate","cn":"分界线；隔阂；障碍","ex":{"en":"The Yangtze River is a natural barrier to the north-east.","cn":"长江是东北面的一道天然屏障。"}},{"en":"a particular amount, level or number that it is difficult to get past","cn":"难以逾越的数量（或水平、数目）；关口","ex":{"en":"the first player whose earnings passed the $10 million barrier","cn":"第一位收入超过 1 000 万美元大关的运动员"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"障碍；壁垒；阻碍","en":"A barrier is something such as a rule, law, or policy that makes it difficult or impossible for something to happen or be achieved.","ex":{"en":"Duties and taxes are the most obvious barrier to free trade.","cn":"关税和税收是自由贸易的最大壁垒。"}},{"pos":"N-COUNT 可数名词","cn":"隔阂；阻碍","en":"A barrier is a problem that prevents two people or groups from agreeing, communicating, or working with each other.","ex":{"en":"There is no reason why love shouldn't cross the age barrier","cn":"爱没有理由不能跨越年龄的阻碍。"}},{"pos":"N-COUNT 可数名词","cn":"关卡；栅栏","en":"A barrier is something such as a fence or wall that is put in place to prevent people from moving easily from one area to another.","ex":{"en":"The demonstrators broke through heavy police barriers","cn":"示威者们冲破了警察的重重设防。"}},{"pos":"N-COUNT 可数名词","cn":"障碍物；挡板；屏障","en":"A barrier is an object or layer that physically prevents something from moving from one place to another.","ex":{"en":"...a severe storm, which destroyed a natural barrier between the house and the lake","cn":"猛烈的暴风雨摧毁了房子和湖之间的一道天然屏障"}},{"pos":"N-SING 单数名词","cn":"大关；界限","en":"You can refer to a particular number or amount as a barrier when you think it is significant, because it is difficult or unusual to go above it.","ex":{"en":"They are fearful that unemployment will soon break the barrier of three million","cn":"他们担心失业人数很快将突破300万大关。"}}]},"examples":[{"en":"There was no real barrier between reality and fantasy in his mind.","cn":"在他的头脑中，现实与幻想之间没有真正的界线。"},{"en":"the first player whose earnings passed the $10 million barrier","cn":"第一位收入超过 1 000 万元大关的运动员"}]},"battery":{"media":{"uk":"media/uk/battery__gb_1.mp3","us":"media/us/battery__us_1.mp3","img":["media/ldoce/img/batteries.jpg"]},"oxford":{"phon":"ˈbætri","pos":"noun","senses":[{"en":"a device that is placed inside a car engine, clock, radio, etc. and that produces the electricity that makes it work","cn":"电池","g":"[countable]","ex":{"en":"to replace the batteries","cn":"更换电池"}},{"en":"electrical power that comes from a battery","cn":"电池的电能","g":"[uncountable]","ex":{"en":"My phone ran out of battery, so I plugged it in to charge.","cn":"我的手机没电了，于是我插上了电源充电。"}},{"en":"a large number of things or people of the same type","cn":"一系列；一批；一群","g":"[countable]","ex":{"en":"He faced a battery of questions.","cn":"他面临一连串的问题。"}},{"en":"a number of large guns that are used together","cn":"排炮","g":"[countable]","lab":"specialist"},{"en":"a large number of small cages that are joined together and are used for keeping chickens, etc. in on a farm","cn":"层架式鸡笼；层架式饲养笼","g":"[countable]","lab":"British English","ex":{"en":"a battery hen","cn":"层架式养鸡笼养的母鸡"}},{"en":"the crime of attacking somebody physically","cn":"殴打罪","g":"[uncountable]","lab":"law","ex":{"en":"He was charged with battery after a fight at a night club.","cn":"他在夜总会打架后被控殴打罪。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"电池","en":"Batteries are small devices that provide the power for electrical items such as radios and children's toys.","ex":{"en":"The shavers come complete with batteries.","cn":"这些剃须刀都已经配好了电池。"}},{"pos":"N-COUNT 可数名词","cn":"（汽车）电瓶，蓄电池","en":"A car battery is a rectangular box containing acid that is found in a car engine. It provides the electricity needed to start the car.","ex":{"en":"...a car with a flat battery.","cn":"电瓶没电了的汽车"}},{"pos":"N-COUNT 可数名词","cn":"（设备的）一排，一套","en":"A battery of equipment such as guns, lights, or computers is a large set of it kept together in one place.","ex":{"en":"They stopped beside a battery of abandoned guns.","cn":"他们在一排废弃火炮旁停了下来。"}},{"pos":"N-COUNT 可数名词","cn":"（物品的）一组，一系列；（人的）一群","en":"A battery of people or things is a very large number of them.","ex":{"en":"...a battery of journalists and television cameras","cn":"一大群记者和众多电视摄像机"}},{"pos":"N-COUNT 可数名词","cn":"一系列（测试、检查等）","en":"A battery of tests is a set of tests that is used to assess a number of different aspects of something, such as your health.","ex":{"en":"We give a battery of tests to each patient.","cn":"我们给每个病人都做了一系列的检查。"}},{"pos":"ADJ 形容词","cn":"（养鸡场）层架式的","en":"Battery farming is a system of breeding chickens and hens in which large numbers of them are kept in small cages, and used for their meat and eggs.","ex":{"en":"...battery hens being raised in dark, cramped conditions.","cn":"在黑暗、拥挤的层架式鸡舍里饲养的母鸡"}},{"pos":"See also:","cn":"","en":"to recharge your batteries→see: ;"}]},"examples":[{"en":"He faced a battery of questions.","cn":"他面临一连串的问题。"},{"en":"The battery is flat (= it is no longer producing electricity).","cn":"电池没电了。"}]},"badly":{"media":{"uk":"media/uk/badly__gb_1.mp3","us":"media/us/badly__us_1.mp3"},"oxford":{"phon":"ˈbædli","pos":"adverb","senses":[{"en":"without skill or care","cn":"糟糕地；拙劣地","ex":{"en":"to play/sing badly","cn":"表演／唱得不好"}},{"en":"not successfully","cn":"不成功地；受挫","ex":{"en":"Things have been going badly.","cn":"事情进展得不顺利。"}},{"en":"not in an acceptable way","cn":"未能令人满意","ex":{"en":"to behave/sleep badly","cn":"表现差；睡得不好"}},{"en":"used to emphasize how serious a situation or an event is","cn":"严重地；厉害地","ex":{"en":"badly damaged/injured/hurt","cn":"损坏／伤势／伤害严重"}},{"en":"used to emphasize how much you want, need, etc. somebody/something","cn":"很；非常","ex":{"en":"The building is badly in need of repair.","cn":"这栋楼急需维修。"}},{"en":"in a way that makes people get a bad opinion about something","cn":"给人坏的印象；负面地","ex":{"en":"The economic crisis reflects badly on the government's policies.","cn":"经济危机反映出政府政策不如人意的一面。"}},{"en":"to feel sorry or ashamed about something","cn":"歉疚的；羞愧的","ex":{"en":"She felt badly about what she had done.","cn":"她为自己所做的事感到羞愧。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"坏；差；拙劣地；不成功地","en":"If something is done badly or goes badly, it is not very successful or effective.","ex":{"en":"I was angry because I played so badly","cn":"我很生气，因为自己的表现实在是太差了。"}},{"pos":"ADV-GRADED 副词","cn":"严重地；厉害地；剧烈地","en":"If someone or something is badly hurt or badly affected, they are severely hurt or affected.","ex":{"en":"The bomb destroyed a police station and badly damaged a church","cn":"炸弹摧毁了一处警察局，并使一座教堂严重受损。"}},{"pos":"ADV-GRADED 副词","cn":"非常；极度","en":"If you want or need something badly, you want or need it very much.","ex":{"en":"Why do you want to go so badly?","cn":"为什么你这么想走？"}},{"pos":"ADV-GRADED 副词","cn":"不友好地；令人不快地；恶劣地","en":"If someone behaves badly or treats other people badly, they act in an unkind, unpleasant, or unacceptable way.","ex":{"en":"They have both behaved very badly and I am very hurt","cn":"他们俩都很不友善，让我非常难过。"}},{"pos":"ADV-GRADED 副词","cn":"不利地；负面地；有损名声地","en":"If something reflects badly on someone or makes others think badly of them, it harms their reputation.","ex":{"en":"Teachers know that low exam results will reflect badly on them","cn":"老师知道考试成绩不好将对他们不利。"}},{"pos":"ADV-GRADED 副词","cn":"（报酬）低；（钱）少","en":"If a person or their job is badly paid, they are not paid very much for what they do.","ex":{"en":"You may have to work part-time, in a badly paid job with unsociable hours","cn":"你或许只能做个薪水低、非正常工作时间上班的兼职。"}}]},"examples":[{"en":"The economic crisis reflects badly on the government's policies.","cn":"经济危机反映出政府政策不如人意的一面。"},{"en":"She's only trying to help, so don't think badly of her.","cn":"她只是想帮忙，所以别把她想得太坏。"}]},"balanced":{"media":{"uk":"media/uk/balanced__gb_1.mp3","us":"media/us/balanced__us_1.mp3"},"oxford":{"phon":"ˈbælənst","pos":"adjective","senses":[{"en":"keeping or showing a balance so that different things or different parts of something exist in equal or correct amounts","cn":"保持（或显示）平衡的","ex":{"en":"The programme presented a balanced view of the two sides of the conflict.","cn":"节目公平地反映了冲突双方的情况。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"公平的；均衡考虑的；兼顾各方的","en":"A balanced report, book, or other document takes into account all the different opinions on something and presents information in a fair and reasonable way.","ex":{"en":"...a fair, balanced, comprehensive report.","cn":"一份公正、公平、全面的报告"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"协调的；和谐的；均衡的","en":"Something that is balanced is pleasing or useful because its different parts or elements are in the correct proportions.","ex":{"en":"...a balanced diet.","cn":"均衡的饮食"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冷静理智的；临危不乱的","en":"Someone who is balanced remains calm and thinks clearly, even in a difficult situation.","ex":{"en":"I have to prove myself as a respectable, balanced, person.","cn":"我必须证明自己是个正派、稳重的人。"}}]},"examples":[{"en":"The programme presented a balanced view of the two sides of the conflict.","cn":"节目公平地反映了冲突双方的情况。"},{"en":"a balanced diet (= one with the quantity and variety of food needed for good health)","cn":"均衡饮食"}]},"bacon":{"media":{"uk":"media/uk/bacon__gb_1.mp3","us":"media/us/bacon__us_1.mp3"},"oxford":{"phon":"ˈbeɪkən","pos":"noun","senses":[{"en":"meat from the back or sides of a pig that has been cured (= preserved using salt or smoke), usually served in thin slices","cn":"培根；熏猪肉","ex":{"en":"a rasher of bacon","cn":"一片培根"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"咸猪肉；熏猪肉","en":"Bacon is salted or smoked meat which comes from the back or sides of a pig.","ex":{"en":"...bacon and eggs.","cn":"熏肉煎蛋"}},{"pos":"PHRASE 短语","cn":"成功；达到目的","en":"If you bring home the bacon ,you achieve what you needed to achieve.","ex":{"en":"Voters are interested in the representative's ability to bring home the bacon","cn":"选民感兴趣的是代表能否兑现承诺。"}},{"pos":"PHRASE 短语","cn":"养家糊口；赚钱养家","en":"The person in a family who brings home the bacon provides the family with the money they need to live.","ex":{"en":"Who brings up the baby and who brings home the bacon?","cn":"是谁抚养孩子的，是谁赚钱养家的？"}},{"pos":"PHRASE 短语","cn":"解救…于危难（或困境）","en":"If someone or something saves your bacon, they get you out of a dangerous or difficult situation.","ex":{"en":"Your mother once saved my bacon. She lent me money when I needed it.","cn":"你母亲帮过我一次大忙，在我需要的时候借过钱给我。"}}]},"examples":[{"en":"smoked/unsmoked bacon","cn":"熏制/未熏制的猪肉"},{"en":"a rasher of bacon","cn":"一片咸猪肉"}]},"bald":{"media":{"img":["media/pic/hair_comp.jpg","media/thumb/baldhead.jpg"],"uk":"media/uk/bald__gb_1.mp3","us":"media/us/bald__us_1.mp3"},"oxford":{"phon":"bɔːld","pos":"adjective","senses":[{"en":"having little or no hair on the head","cn":"秃顶的；秃头的","ex":{"en":"He started going bald in his twenties.","cn":"他二十几岁便开始谢顶。"}},{"en":"without any of the usual hair, marks, etc. covering the skin or surface of something","cn":"无毛的；平滑的；光秃的","ex":{"en":"Our dog has a bald patch on its leg.","cn":"我们的狗腿上有一片秃了。"}},{"en":"without any extra explanation or detail to help you understand or accept what is being said","cn":"不加赘述的；简单的；赤裸裸的","ex":{"en":"The bald fact is that we don't need you any longer.","cn":"事实很简单，我们不再需要你了。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"秃头的；秃顶的","en":"Someone who is bald has little or no hair on the top of their head.","ex":{"en":"The man's bald head was beaded with sweat","cn":"这个男人的光头上满是汗珠。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（轮胎表面）磨平了的，磨光了的","en":"If a tyre is bald, its surface has worn down and it is no longer safe to use."},{"pos":"ADJ 形容词","cn":"不加修饰的；直截了当的；赤裸裸的","en":"A bald statement is in plain language and contains no extra explanation or information.","ex":{"en":"The announcement came in a bald statement from the official news agency","cn":"官方通讯社发表了直截了当的声明。"}}]},"examples":[{"en":"The letter was a bald statement of our legal position.","cn":"那封信直截了当地说出我们的法律立场。"},{"en":"The bald fact is that we don't need you any longer.","cn":"事实很简单，我们不再需要你了。"}]},"bass":{"media":{"uk":"media/uk/bass__gb_1.mp3","us":"media/us/bass__us_1.mp3","img":["media/ldoce/img/bass.jpg"]},"oxford":{"phon":"beɪs","pos":"noun","senses":[{"en":"the lowest tone or part in music, for instruments or voices","cn":"（音乐、乐器、声乐等的）低音，低音部","g":"[uncountable]","ex":{"en":"He always plays his stereo with the bass turned right up.","cn":"他放立体声音响时总把低音调得很大。"}},{"en":"an electric guitar that plays very low notes","cn":"低音电吉他；电贝司","g":"[countable]","ex":{"en":"a bass player","cn":"低音电吉他手"}},{"en":"a man’s singing voice with a low range; a man with a bass voice","cn":"男低音；男低音歌手","g":"[countable]","ex":{"en":"He answered my question in a surprisingly deep bass.","cn":"他用一种低得出奇的声音回答我的问题。"}},{"en":"a musical part that is written for a bass voice","cn":"（乐曲的）低音部","g":"[singular]"},{"en":"the largest musical instrument in the violin family, which plays very low notes","cn":"低音提琴；低音大提琴","g":"[countable]"},{"en":"low in tone","cn":"低音的；低声调的","ex":{"en":"a bass voice","cn":"低音部"},"pos":"adjective"},{"en":"a sea or freshwater fish that is used for food","cn":"鲈（包括多种食用海鱼和淡水鱼）","ex":{"en":"Fresh sea bass is a great delicacy.","cn":"新鲜的鲈鱼是一道美味佳肴。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"男低音歌手","en":"A bass is a man with a very deep singing voice.","ex":{"en":"...the great Russian bass Chaliapin.","cn":"伟大的俄罗斯男低音歌唱家夏利亚宾"}},{"pos":"ADJ 形容词","cn":"（鼓、吉他等乐器）低音的","en":"A bass drum, guitar, or other musical instrument is one that produces a very deep sound.","ex":{"en":"...bass guitarist Dee Murray.","cn":"低音吉他手迪伊·默里"}},{"pos":"N-VAR 可变名词","cn":"低音吉他；低音提琴","en":"In popular music, a bass is a bass guitar or a double bass .","ex":{"en":"They had a bass and a piano and a sax and percussion.","cn":"他们有一把低音吉他、一架钢琴、一管萨克斯和打击乐器。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（立体声音响或收音机等的）低音部，低音部旋钮","en":"On a stereo system or radio, the bass is the ability to reproduce the lower musical notes. The bass is also the knob which controls this.","ex":{"en":"...larger models which will then give more bass and a higher fidelity sound.","cn":"能够听到更多低音和高保真音效的更大的型号"}},{"pos":"N-VAR 可变名词","cn":"鲈鱼","en":"Bass are edible fish that are found in rivers and the sea. There are several types of bass.","ex":{"en":"They unloaded their catch of cod and bass.","cn":"他们把捕到的鳕鱼和鲈鱼卸下来。"}}]},"examples":[{"en":"Eilís Phillips on (= playing) bass","cn":"由艾利斯 · 菲利普斯演奏低音电吉他"},{"en":"He always plays his stereo with the bass turned right up.","cn":"他放立体声音响时总把低音调得很大。"}]},"baroque":{"media":{"uk":"media/uk/baroque__gb_1.mp3","us":"media/us/baroque__us_1.mp3"},"oxford":{"phon":"bəˈrɒk","pos":"noun","senses":[{"en":"the grand and highly decorated style used in European architecture, art and music in the 17th and early 18th centuries","cn":"巴罗克风格的（17 至 18 世纪早期流行于欧洲，气势雄伟、装饰华丽的特色反映在建筑、绘画和音乐等艺术上）","ex":{"en":"paintings representative of the baroque","cn":"巴罗克风格的油画代表作"}},{"en":"used to describe European architecture, art and music of the 17th and early 18th centuries that has a grand and highly decorated style","cn":"巴罗克风格的（17 至 18 世纪早期流行于欧洲，气势雄伟、装饰华丽的特色反映在建筑、绘画和音乐等艺术上）","ex":{"en":"baroque churches/music","cn":"巴罗克风格教堂／音乐"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（17世纪和18世纪早期流行于欧洲的一种设计繁复的建筑和艺术风格）巴洛克式的，巴洛克风格的","en":"Baroque architecture and art is an elaborate style of architecture and art that was popular in Europe in the seventeenth and early eighteenth centuries.","ex":{"en":"The baroque church of San Leonardo is worth a quick look.","cn":"圣莱昂纳多的巴洛克式教堂值得一看。"}},{"pos":"ADJ 形容词","cn":"（18世纪欧洲音乐）巴洛克式的，巴洛克风格的","en":"Baroque music is a style of European music that was written in the 18th century.","ex":{"en":"...the German baroque composer Georg Philip Telemann","cn":"德国巴洛克风格的作曲家格奥尔格·菲利普·泰勒曼"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"复杂精美的；精雕细琢的","en":"Baroque things are complicated and elaborate.","ex":{"en":"He was a baroque figure dressed in theatrical, but elegant, clothes.","cn":"他是个巴罗克式的人物，衣着华丽但又不失优雅。"}}]},"examples":[{"en":"baroque churches/music","cn":"巴罗克风格教堂/音乐"},{"en":"paintings representative of the baroque","cn":"典型的巴罗克风格绘画"}]},"battalion":{"media":{"uk":"media/uk/battalion__gb_1.mp3","us":"media/us/battalion__us_1.mp3"},"oxford":{"phon":"bəˈtæliən","pos":"noun","senses":[{"en":"a large group of soldiers that form part of a brigade","cn":"（军队的）营"},{"en":"a large group of people, especially an organized group with a particular purpose","cn":"（有组织的）队伍","lab":"formal","ex":{"en":"a battalion of supporters","cn":"由支持者组成的队伍"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"营；军营","en":"A battalion is a large group of soldiers that consists of three or more companies.","ex":{"en":"Anthony was ordered to return to his battalion","cn":"安东尼受命返回自己的军营。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指有组织、有特定任务、高效的）一大群，一大批","en":"A battalion of people is a large group of them, especially a well-organized, efficient group that has a particular task to do.","ex":{"en":"There were battalions of highly paid publicists to see that such news didn't make the press.","cn":"有一大批拿高薪的公关人员可以确保这样的新闻不会见诸报端。"}}]},"examples":[{"en":"a battalion of supporters","cn":"由支持者组成的队伍"}]},"bad-tempered":{"oxford":{"phon":"ˌbæd ˈtempəd","pos":"adjective","senses":[{"en":"often angry; in an angry mood","cn":"易怒的；爱发脾气的","ex":{"en":"She gets very bad-tempered when she's tired.","cn":"她累的时候就很爱发脾气。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"脾气不好的；易怒的","en":"Someone who is bad-tempered is not very cheerful and gets angry easily. →see usage note at:","ex":{"en":"When his headaches developed Nick became bad-tempered and even violent","cn":"尼克出现头痛时脾气就变得很差，甚至还会动粗。"}}]},"media":{"uk":"media/uk/bad_tempered_1_gb_1.mp3","us":"media/us/bad_tempered_1_us_1.mp3"},"examples":[{"en":"She gets very bad-tempered when she's tired.","cn":"她累的时候就爱发脾气。"}]},"ball":{"media":{"uk":"media/uk/ball__gb_1.mp3","us":"media/us/ball__us_1.mp3"},"oxford":{"phon":"bɔːl","pos":"noun","senses":[{"en":"a round object used for throwing, hitting or kicking in games and sports","cn":"球","ex":{"en":"a golf/tennis/bowling/soccer ball","cn":"高尔夫球；网球；保龄球；足球"}},{"en":"a round object or a thing that has been formed into a round shape","cn":"球状物","ex":{"en":"The sun was a huge ball of fire low on the horizon.","cn":"地平线上的太阳像个大火球。"}},{"en":"a kick, hit or throw of the ball in some sports","cn":"踢出（或击出、投出）的一球","ex":{"en":"He sent over a high ball.","cn":"他投了一个高球。"}},{"en":"a throw by the pitcher that is outside the strike zone (= the area between the batter's upper arms and knees)","cn":"（投手投出的）坏球"},{"en":"the part below the big toe or the thumb","cn":"大脚趾球；拇指球"},{"en":"a testicle","cn":"睾丸","g":"[usually plural]","lab":"informal"},{"en":"a large formal party with dancing","cn":"（大型正式的）舞会","ex":{"en":"She met him at the ball.","cn":"她在那次舞会上遇到他。"}},{"en":"to form something or be formed into the shape of a ball","cn":"做成球状；使成团块","g":"[intransitive, transitive]","ex":{"en":"Her hands balled into fists.","cn":"她双手攥拳。"},"pos":"verb"},{"en":"to have sex with somebody","cn":"（和某人）性交","g":"[transitive]","lab":"North American English, taboo, slang，，，，","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"球","en":"A ball is a round object that is used in games such as tennis, baseball, football, basketball, and cricket.","ex":{"en":"...a golf ball.","cn":"高尔夫球"}},{"pos":"N-COUNT 可数名词","cn":"球状物","en":"A ball is something or an amount of something that has a round shape.","ex":{"en":"Thomas screwed the letter up into a ball","cn":"托马斯把信揉成一团。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）成球状（或团块）","en":"When you ball something or when it balls, it becomes round.","ex":{"en":"He picked up the sheets of paper, and balled them tightly in his fists","cn":"他抓起那几张纸，在手里紧紧攥成团。"}},{"pos":"N-COUNT 可数名词","cn":"（脚趾和脚相连或拇指和手相连的）球状部位；脚趾球；拇指球","en":"The ball of your foot or the ball of your thumb is the rounded part where your toes join your foot or where your thumb joins your hand."},{"pos":"N-COUNT 可数名词","cn":"舞会","en":"A ball is a large formal social event at which people dance."},{"pos":"N-COUNT 可数名词","cn":"睾丸","en":"A man's balls are his testicles."},{"pos":"PHRASE 短语","cn":"轮到…采取行动（或作出决断）","en":"If you say that the ball is in someone's court, you mean that it is his or her responsibility to take the next action or decision in a situation.","ex":{"en":"The ball's now in your court — you have to decide what you're going to do.","cn":"轮到你了——你必须决定自己要做什么。"}},{"pos":"PHRASE 短语","cn":"使某事发生；开始某种活动","en":"If you get the ball rolling ,set the ball rolling, or start the ball rolling, you start something happening.","ex":{"en":"He will go to the Middle East next week to get the ball rolling again on peace talks","cn":"他下周将前往中东，开始重启和谈。"}},{"pos":"PHRASE 短语","cn":"玩得很开心；尽情欢乐","en":"If you are having a ball, you are having a very enjoyable time.","ex":{"en":"Outside the boys were sitting on the ground and, going by the gales of laughter, they were having a ball.","cn":"男孩们在户外席地而坐，从阵阵笑声来看，他们玩得很开心。"}},{"pos":"PHRASE 短语","cn":"同时做数件事情","en":"If you keep several balls in the air, you try to do several different things at once.","ex":{"en":"The detective has to discover the motive, the means and the opportunity and has to keep these three balls in the air.","cn":"那名侦探必须查明动机、手段和时机，而且对这三项的调查必须同步展开。"}},{"pos":"PHRASE 短语","cn":"警觉；机警；留心","en":"If someone is on the ball, they are very alert and aware of what is happening.","ex":{"en":"She really is on the ball; she's bought houses at auctions so she knows what she's doing.","cn":"她很精明干练；她通过拍卖购过房，所以知道自己在做什么。"}},{"pos":"PHRASE 短语","cn":"愿意合作","en":"If someone refuses to play ball, they are unwilling to do what someone wants them to do.","ex":{"en":"The association has threatened to withdraw its support if the banks and building societies refuse to play ball.","cn":"该协会威胁说如果银行和建屋互助会不配合的话，它将不再提供支持。"}},{"pos":"","cn":"","en":"相关词组：ball up"}]},"examples":[{"en":"They've offered me the job, so the ball's in my court now.","cn":"他们已答应把那份工作给我，下一步就看我怎么办了。"},{"en":"I panicked, I cried — the whole ball of wax.","cn":"我惊慌失措，我大喊大叫，所有的反应都做齐了。"}]},"base":{"media":{"uk":"media/uk/base__gb_1.mp3","us":"media/us/base__us_1.mp3"},"oxford":{"phon":"beɪs","pos":"noun","senses":[{"en":"the lowest part of something, especially the part or surface on which it rests or stands","cn":"根基；基底；底座","g":"[countable, usually singular]","sc":"lowest part","ex":{"en":"The lamp has a heavy base.","cn":"这盏灯的底座很沉。"}},{"en":"the main place where you live or stay or where a business operates from","cn":"据点；总部；大本营","g":"[countable]","sc":"main place","ex":{"en":"I spend a lot of time in Britain but Paris is still my base.","cn":"我有很多时间在英国度过，但主要还是居住在巴黎。"}},{"en":"a place where an army, a navy, etc. operates from","cn":"基地","g":"[countable, uncountable]","sc":"of army, etc.","ex":{"en":"a military/naval base","cn":"军事／海军基地"}},{"en":"the people, activity, etc. from which somebody/something gets most of their support, income, power, etc.","cn":"（支持、收入、力量等的）来源，源泉，基础","g":"[countable, usually singular]","sc":"of support/income/power","ex":{"en":"These policies have a broad base of support.","cn":"这些政策得到广泛支持。"}},{"en":"the pay that you get before anything extra is added","cn":"基本工资","lab":"especially North American English","sc":"of support/income/power","ex":{"en":"All we got was base pay—we didn't reach profitability levels to award a bonus.","cn":"我们只拿到了基本工资，因为没有达到可发奖金的盈利水平。"}},{"en":"an idea, a fact, a situation, etc. from which something is developed","cn":"根据；出发点","g":"[countable]","sc":"original idea/situation","ex":{"en":"She used her family's history as a base for her novel.","cn":"她以她的家族史作为小说的素材。"}},{"en":"the first or main part of a substance to which other things are added","cn":"混合物的首要（或主要）成分","g":"[countable, usually singular]","sc":"first/main substance","ex":{"en":"a drink with a rum base","cn":"主要成分为朗姆酒的饮料"}},{"en":"a chemical substance, for example an alkali, that can combine with an acid to form a salt","cn":"碱","g":"[countable]","sc":"chemistry"},{"en":"a number on which a system of counting and expressing numbers is built up, for example 10 in the decimal system and 2 in the binary system","cn":"基数（如十进制的 10 和二进制的 2）","g":"[countable, usually singular]","sc":"mathematics"},{"en":"one of the four positions that a player must reach in order to score points","cn":"垒","g":"[countable]","sc":"in baseball/rounders"},{"en":"to use a particular city, town, etc. as the main place for a business, holiday, etc.","cn":"以…为据点（或大本营等）；把（总部等）设在","ex":{"en":"The organization is now based in Geneva.","cn":"这个组织的总部现在设在日内瓦。"},"pos":"verb"},{"en":"having no moral principles or rules","cn":"卑鄙的；不道德的","ex":{"en":"He acted from base motives.","cn":"他的行动动机卑鄙。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"基础；根基；底部","en":"The base of something is its lowest edge or part.","ex":{"en":"There was a cycle path running along this side of the wall, right at its base","cn":"在墙的这边，沿着墙根有一条自行车道。"}},{"pos":"N-COUNT 可数名词","cn":"基部；相连处；连接处","en":"The base of something is the lowest part of it, where it is attached to something else.","ex":{"en":"The surgeon placed catheters through the veins and arteries near the base of the head.","cn":"外科医生在脑根部的静脉和动脉中放置了导管。"}},{"pos":"N-COUNT 可数名词","cn":"底；底部；底面","en":"The base of an object such as a box or vase is the lower surface of it that touches the surface it rests on.","ex":{"en":"Remove from the heat and plunge the base of the pan into a bowl of very cold water.","cn":"先把锅从炉子上拿开，然后把锅底浸入一盆冷水中。"}},{"pos":"N-COUNT 可数名词","cn":"底部；基座","en":"The base of an object that has several sections and that rests on a surface is the lower section of it.","ex":{"en":"The mattress is best on a solid bed base","cn":"这种床垫最好放在结实的床板上。"}},{"pos":"N-COUNT 可数名词","cn":"基层；底层","en":"A base is a layer of something which will have another layer added to it.","ex":{"en":"Spoon the mixture on to the biscuit base and cook in a preheated oven","cn":"把混合好的糊糊舀到饼干坯上，然后放入已预热的烤箱烘烤。"}},{"pos":"N-COUNT 可数名词","cn":"出发点；起点；基础","en":"A position or thing that is a base for something is one from which that thing can be developed or achieved.","ex":{"en":"The post will give him a powerful political base from which to challenge the Kremlin","cn":"这个职位将给他提供一个强有力的政治基点来挑战克里姆林宫。"}},{"pos":"VERB 动词","cn":"以…为基础","en":"If you base one thing on another thing, the first thing develops from the second thing.","ex":{"en":"He based his conclusions on the evidence given by the captured prisoners.","cn":"他根据被俘囚犯提供的证据得出了这个结论。"}},{"pos":"N-COUNT 可数名词","cn":"（公司的）客户基础，主要（客户）群体","en":"A company's client base or customer base is the group of regular clients or customers that the company gets most of its income from.","ex":{"en":"The company has been expanding its customer base using trade magazine advertising.","cn":"公司一直通过在商业杂志上刊登广告扩展客户群。"}},{"pos":"N-COUNT 可数名词","cn":"（军事）基地","en":"A military base is a place which part of the armed forces works from.","ex":{"en":"Gunfire was heard at an army base close to the airport.","cn":"机场附近的军事基地传出了炮火声。"}},{"pos":"N-COUNT 可数名词","cn":"（工作或生活的）据点，基地","en":"Your base is the main place where you work, stay, or live.","ex":{"en":"For most of the spring and early summer her base was her home in Scotland.","cn":"春天和初夏的大部分时间，她都是在苏格兰的家里度过的。"}},{"pos":"N-COUNT 可数名词","cn":"（活动的）地点，中心，大本营","en":"If a place is a base for a certain activity, the activity can be carried out at that place or from that place.","ex":{"en":"The two hotel-restaurants are attractive bases from which to explore southeast Tuscany","cn":"对于去托斯卡纳东南部探险的人们来说，这两家酒店是很有吸引力的驻扎地。"}},{"pos":"N-COUNT 可数名词","cn":"基础成分；主要成分；主料","en":"The base of a substance such as paint or food is the main ingredient of it, to which other substances can be added.","ex":{"en":"Drain off any excess marinade and use it as a base for a pouring sauce","cn":"先滗出多余的卤汁，把它当作浇汁的主料。"}},{"pos":"N-COUNT 可数名词","cn":"（数字进位制中的）基数","en":"A base is a system of counting and expressing numbers. The decimal system uses base 10, and the binary system uses base 2."},{"pos":"N-COUNT 可数名词","cn":"（棒球、垒球、圆场棒球等的）垒","en":"A base in baseball, softball, or rounders is one of the places at each corner of the square on the pitch."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"卑鄙的；下流的；无耻的","en":"Base behaviour is behaviour that is immoral or dishonest.","ex":{"en":"Love has the power to overcome the baser emotions.","cn":"爱能够战胜邪念。"}},{"pos":"PHRASE 短语","cn":"完全错误；大错特错","en":"If you say that someone is off base, you mean that they are wrong.","ex":{"en":"Am I wrong? Am I way off base? Because I want you to set me straight if you think I'm wrong.","cn":"我错了吗？我大错特错了吗？因为如果我不对的话，我希望你能纠正我的错误。"}},{"pos":"PHRASE 短语","cn":"（尤指在近期没有联系的情况下与某人）取得联系","en":"If you communicate with someone, especially someone you have not communicated with recently, you can say that you touch base with them.","ex":{"en":"Being there gave me a chance to touch base with three friends whom I had not seen for a year.","cn":"在那里，让我有机会和一年没见面的三个朋友取得了联系。"}},{"pos":"PHRASE 短语","cn":"面面俱到；应付各种情况","en":"If someone touches all the bases or covers the bases, they deal with everyone or everything involved in a situation.","ex":{"en":"He has managed to touch all the bases necessary, and trade goes on","cn":"他想方设法把所有必要的事情都处理妥当，生意也维持了下来。"}}]},"examples":[{"en":"All we got was base pay — we didn't reach profitability levels to award a bonus.","cn":"我们只拿到了基本工资，因为没有达到可发奖金的盈利水平。"},{"en":"I spend a lot of time in Britain but Paris is still my base.","cn":"我有很多时间在英国度过，但主要还是居住在巴黎。"}]},"battlefield":{"media":{"uk":"media/uk/battlefield__gb_1.mp3","us":"media/us/battlefield__us_1.mp3"},"oxford":{"phon":"ˈbætlfiːld","pos":"noun","senses":[{"en":"a place where a battle is being fought or has been fought","cn":"战场","ex":{"en":"heavy casualties on the battlefield","cn":"战场上伤亡惨重"}},{"en":"a situation in which people are opposed to each other; a subject that people feel strongly about and argue about","cn":"对峙的场面；激烈争论的话题","ex":{"en":"Arkansas is among the key electoral battlefields.","cn":"阿肯色州是关键的选举战场之一。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"战场；沙场；战地","en":"A battlefield is a place where a battle is fought.","ex":{"en":"...the battlefields of the Somme.","cn":"索姆河战役的战场"}},{"pos":"N-COUNT 可数名词","cn":"争论的主题；斗争的领域","en":"You can refer to an issue or field of activity over which people disagree or compete as a battlefield .","ex":{"en":"...the domestic battlefield of family life.","cn":"家庭生活内部争论的主题"}}]},"examples":[{"en":"Education has become a political battleground.","cn":"教育问题已经变成了人们热烈争论的政治话题。"},{"en":"a battleground state during the election","cn":"选举期间竞争激烈的一个州"}]},"baskets":{"oxford":{"phon":"ˈbɑːskɪt","pos":"noun","senses":[{"en":"a container for holding or carrying things. Baskets are made of thin strips of material that bends and twists easily, for example plastic, wire or wicker.","cn":"篮；篓；筐"},{"en":"the amount contained in a basket","cn":"一篮，一筐，一篓（的量）"}]}},"band":{"media":{"uk":"media/uk/band__gb_1.mp3","us":"media/us/band__us_1.mp3"},"oxford":{"phon":"bænd","pos":"noun","senses":[{"en":"a small group of musicians who play popular music together, often with a singer or singers","cn":"流行音乐乐队","g":"[countable + singular or plural verb]","sc":"group of musicians","ex":{"en":"a rock/punk/jazz band","cn":"摇滚／朋克／爵士乐队"}},{"en":"a group of musicians who play brass and percussion instruments","cn":"管乐队；鼓号乐队","g":"[countable + singular or plural verb]","sc":"group of musicians","ex":{"en":"a military band","cn":"军乐队"}},{"en":"a group of people who do something together or who have the same ideas, interests or achievements","cn":"一伙人；一帮人","g":"[countable + singular or plural verb]","sc":"group of people","ex":{"en":"a band of outlaws/rebels","cn":"一帮歹徒／叛匪"}},{"en":"a thin flat piece or circle of any material that is put around things, for example to hold them together or to make them stronger","cn":"带；箍","g":"[countable]","sc":"thin piece of material/colour","ex":{"en":"She always ties her hair back in a band.","cn":"她总是用一条带子把头发扎在后面。"}},{"en":"a line of colour or material on something that is different from what is around it","cn":"条纹；条饰","g":"[countable]","sc":"thin piece of material/colour","ex":{"en":"a white plate with a blue band around the edge","cn":"带蓝边的白盘子"}},{"en":"a range of radio waves","cn":"波段","g":"[countable]","sc":"of radio waves","ex":{"en":"Short-wave radio uses the 20–50-metre band.","cn":"短波收音机用的波段是 20–50 米。"}},{"en":"a range of numbers, ages, prices, etc. within which people or things are counted or measured","cn":"（数目、年龄、价格等的）范围，段","g":"[countable]","sc":"range","ex":{"en":"the 25–35 age band","cn":"25–35 岁的年龄段"}},{"en":"to put a band of a different colour or material around something","cn":"加彩条（或嵌条等）","g":"[usually passive]","sc":"with colour/material","ex":{"en":"Many insects are banded black and yellow.","cn":"很多昆虫有黑色和黄色的条纹。"},"pos":"verb"},{"en":"to organize something into bands of price, income, etc.","cn":"（将价格、收入等）划分档次，分等级","g":"[usually passive]","lab":"British English","sc":"put into range","ex":{"en":"Tax is banded according to income.","cn":"赋税是按收入划分等级的。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"（流行音乐）乐队，乐团","en":"A band is a small group of musicians who play popular music such as jazz, rock, or pop.","ex":{"en":"He was a drummer in a rock band","cn":"他曾是一个摇滚乐团的鼓手。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"（演奏铜管和打击乐器的）乐队，乐团","en":"A band is a group of musicians who play brass and percussion instruments.","ex":{"en":"Bands played German marches.","cn":"乐队演奏了德军进行曲。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"（一）群；（一）帮；（一）伙","en":"A band of people is a group of people who have joined together because they share an interest or belief.","ex":{"en":"Bands of government soldiers, rebels and just plain criminals have been roaming some neighborhoods.","cn":"成群结队的政府军士兵、反叛分子和彻头彻尾的犯罪分子一直在一些街区游荡。"}},{"pos":"N-COUNT 可数名词","cn":"（佩戴用或衣物上的）带，箍","en":"band is a flat, narrow strip of cloth which you wear round your head or wrists, or which forms part of a piece of clothing.","ex":{"en":"Almost all hospitals use a wrist-band of some kind with your name and details on it.","cn":"几乎所有的医院都用某种腕带记录名字和详细信息。"}},{"pos":"N-COUNT 可数名词","cn":"条纹；带状物","en":"A band is a strip of something such as colour, light, land, or cloth which contrasts with the areas on either side of it.","ex":{"en":"...bands of natural vegetation between strips of crops","cn":"农作物狭地之间的野生植被带"}},{"pos":"N-COUNT 可数名词","cn":"（用以加固或捆绑的）圈，箍","en":"A band is a strip or loop of metal or other strong material which strengthens something, or which holds several things together.","ex":{"en":"Surgeons placed a metal band around the knee cap to help it knit back together.","cn":"外科医生在膝盖骨上套了个金属箍以帮助其愈合。"}},{"pos":"N-COUNT 可数名词","cn":"（数字、值等的）范围","en":"A band is a range of numbers or values within a system of measurement.","ex":{"en":"For an initial service, a 10 megahertz-wide band of frequencies will be needed.","cn":"初始服务需要10兆赫宽的频带。"}},{"pos":"VERB 动词","cn":"将…划分范围；把…分段","en":"If something such as a tax is banded, it is divided into bands according to the value of the thing being taxed.","ex":{"en":"They appear to rule out some of the ideas that have been mentioned — banding the tax so higher earners would pay more.","cn":"他们看来要剔除其中提到的一些想法——如把税率分档，使收入越高，缴得越多。"}},{"pos":"","cn":"","en":"相关词组：band together"}]},"examples":[{"en":"All babies in the hospital have name bands on their wrists.","cn":"医院里所有新生儿手腕上都套着写有名字的手箍。"},{"en":"Short-wave radio uses the 20-50 metre band.","cn":"短波收音机用的波段是 20–50 米。"}]},"banknote":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"钞票；纸币","en":"Banknotes are pieces of paper money."}]},"media":{"uk":"media/uk/banknote__gb_1.mp3","us":"media/us/banknote__us_1.mp3"},"examples":[{"en":"forged (= illegally copied) banknotes","cn":"伪钞"}],"oxford":{"phon":"ˈbæŋknəʊt","pos":"noun","senses":[{"en":"a piece of paper money","cn":"纸币；钞票","ex":{"en":"forged (= illegally copied) banknotes","cn":"伪钞"}}]}},"backbone":{"media":{"uk":"media/uk/backbone__gb_1.mp3","us":"media/us/backbone__us_1.mp3","img":["media/ldoce/img/skeleton.jpg"]},"oxford":{"phon":"ˈbækbəʊn","pos":"noun","senses":[{"en":"the row of small bones that are connected together down the middle of the back","cn":"脊柱；脊椎；脊梁骨","g":"[countable]"},{"en":"the most important part of a system, an organization, etc. that gives it support and strength","cn":"支柱；骨干；基础","g":"[singular]","ex":{"en":"Agriculture forms the backbone of the rural economy.","cn":"农业是农村经济的基础。"}},{"en":"the strength of character that you need to do something difficult","cn":"毅力；骨气","g":"[uncountable]","ex":{"en":"He doesn't have the backbone to face the truth.","cn":"他没有面对现实的勇气。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"脊柱","en":"Your backbone is the column of small linked bones down the middle of your back."},{"pos":"N-SING 单数名词","cn":"中坚力量；骨干；支柱","en":"The backbone of an organization or system is the part of it that gives it its main strength.","ex":{"en":"The small business people of Britain are the economic backbone of the nation.","cn":"英国的小商人是国家经济的支柱。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"骨气；勇气","en":"If you say that someone has no backbone, you think they do not have the courage to do things which need to be done.","ex":{"en":"You might be taking drastic measures and you've got to have the backbone to do that.","cn":"你也许要采取极端的措施，你必须有勇气那么做。"}}]},"examples":[{"en":"Agriculture forms the backbone of the rural economy.","cn":"农业是农村经济的基础。"},{"en":"He doesn't have the backbone to face the truth.","cn":"他没有面对现实的勇气。"}]},"ballad":{"media":{"uk":"media/uk/ballad__gb_1.mp3","us":"media/us/ballad__us_1.mp3"},"oxford":{"phon":"ˈbæləd","pos":"noun","senses":[{"en":"a song or poem that tells a story","cn":"叙事诗；民歌；民谣","ex":{"en":"a medieval ballad about a knight and a lady","cn":"一首关于骑士和贵族小姐的中世纪谣曲"}},{"en":"a slow song about love","cn":"（节奏缓慢的）情歌","ex":{"en":"Her latest single is a ballad.","cn":"她的最新单曲是一首情歌。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"民谣；叙事诗歌","en":"A ballad is a long song or poem which tells a story in simple language.","ex":{"en":"...an eighteenth century ballad about some lost children called the Babes in the Wood.","cn":"一首18世纪的关于几个迷路小孩的叙事诗，名为《树林中的宝贝》"}},{"pos":"N-COUNT 可数名词","cn":"（节奏舒缓的）流行抒情歌曲，情歌","en":"A ballad is a slow, romantic, popular song.","ex":{"en":"'You Don't Know Paris' is one of the most beautiful ballads that he ever wrote.","cn":"《猜不透的巴黎》是他创作的最为优美动听的情歌之一。"}}]},"examples":[{"en":"a medieval ballad about a knight and a lady","cn":"一首关于骑士和贵族小姐的中世纪谣曲"},{"en":"Her latest single is a ballad.","cn":"她的最新单曲唱片是一首情歌。"}]},"basis":{"media":{"uk":"media/uk/basis__gb_1.mp3","us":"media/us/basis__us_1.mp3"},"oxford":{"phon":"ˈbeɪsɪs","pos":"noun","senses":[{"en":"the way things are organized or arranged; how often something happens","cn":"方式；频率","g":"[singular]","ex":{"en":"We are in contact on a regular basis.","cn":"我们定期联系对方。"}},{"en":"the reason why people take a particular action","cn":"原因；缘由","g":"[singular]","ex":{"en":"She was chosen for the job on the basis of her qualifications.","cn":"她因资历适合而获选中担任这项工作。"}},{"en":"the important facts, ideas or events that support something and that it can develop from","cn":"基础；要素；基点","g":"[countable, usually singular, uncountable]","ex":{"en":"The basis of a good marriage is trust.","cn":"美满婚姻的基础是信赖。"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"基本原则；基本规律","en":"If something is done on a particular basis, it is done according to that method, system, or principle.","ex":{"en":"We're going to be meeting there on a regular basis","cn":"我们将定期在那里会面。"}},{"pos":"N-SING 单数名词","cn":"（行事的）理由，根据","en":"If you say that you are acting on the basis of something, you are giving that as the reason for your action.","ex":{"en":"McGregor must remain confined, on the basis of the medical reports we have received","cn":"根据我们收到的病历报告，麦格雷戈的行动仍然必须受到限制。"}},{"pos":"N-COUNT 可数名词","cn":"基础；起点","en":"The basis of something is its starting point or an important part of it from which it can be further developed.","ex":{"en":"Both factions have broadly agreed that the UN plan is a possible basis for negotiation.","cn":"双方大致同意联合国的计划可能成为谈判的基础。"}},{"pos":"N-COUNT 可数名词","cn":"依据；根据","en":"The basis for something is a fact or argument that you can use to prove or justify it.","ex":{"en":"...Japan's attempt to secure the legal basis to send troops overseas","cn":"日本试图找到向海外派兵的法律依据"}}]},"examples":[{"en":"She was chosen for the job on the basis of her qualifications.","cn":"她因资历适合而获选中担任这项工作。"},{"en":"These figures formed the basis of their pay claim.","cn":"这些数字是他们要求提高工资的根据。"}]},"back":{"media":{"uk":"media/uk/back__gb_1.mp3","us":"media/us/back__us_1.mp3"},"oxford":{"phon":"bæk","pos":"noun","senses":[{"en":"the part of the human body that is on the opposite side to the chest, between the neck and the tops of the legs; the part of an animal’s body that corresponds to this","cn":"（人体或动物的）背部，背；腰背","lab":"informal","sc":"part of body","ex":{"en":"He was lying on his back on the sofa.","cn":"他仰面躺在沙发上。"}},{"en":"the row of bones in the middle of the back","cn":"脊柱；脊梁骨","sc":"part of body","ex":{"en":"She broke her back in a riding accident.","cn":"她在一次骑马事故中摔断了脊梁骨。"}},{"en":"the part or area of something that is furthest from the front","cn":"后部；后面；末尾","g":"[usually singular]","lab":"British English","sc":"part furthest from front","ex":{"en":"She was hit on the back of the head.","cn":"她的后脑部被击中。"}},{"en":"the part of a piece of paper, etc. that is on the opposite side to the one that has information or the most important information on it","cn":"（文件等的）背面","g":"[usually singular]","sc":"of piece of paper","ex":{"en":"Take a card and write your name on the back.","cn":"拿一张卡片，在背面写上你的名字。"}},{"en":"the last few pages of a book, etc.","cn":"（书等的）最后几页，末尾","g":"[usually singular]","sc":"of book","ex":{"en":"The television guide is at the back of the paper.","cn":"电视节目指南在报纸的末尾。"}},{"en":"the part of a chair, etc. against which you lean your back","cn":"（椅子等的）靠背","sc":"of chair"},{"en":"used to describe furniture that has the type of back mentioned","cn":"（家具）…靠背的","sc":"-backed","ex":{"en":"a high-backed sofa","cn":"高靠背沙发"}},{"en":"a player whose main role is to defend their team’s goal","cn":"后卫","sc":"in sport"},{"en":"located behind or at the back of something","cn":"背后的；后面的；后部的","sc":"away from front","ex":{"en":"We were sitting in the back row","cn":"我们坐在后排。"},"pos":"adjective"},{"en":"of or from a past time","cn":"过去的；旧时的","sc":"from past","ex":{"en":"a back issue of the magazine","cn":"一份过期杂志"},"pos":"adjective"},{"en":"owed for a time in the past","cn":"到期未付的；拖欠的","sc":"owed","ex":{"en":"back pay/taxes/rent","cn":"欠薪；欠税；欠租金"},"pos":"adjective"},{"en":"produced with the back of the tongue in a higher position than the front, for example /ɑː/ in English","cn":"舌后的，后位性的（舌高点位于口腔后部发音）","lab":"phonetics","sc":"phonetics","pos":"adjective"},{"en":"to or into the place, condition, situation or activity where somebody/something was before","cn":"回原处；恢复原状","sc":"as before","ex":{"en":"When is he coming back to work?","cn":"他什么时候回来工作？"},"pos":"adverb"},{"en":"away from the front or centre; behind you","cn":"向后；在后；在背面","sc":"away from front","ex":{"en":"I moved back to let them pass.","cn":"我退后了，好让他们通过。"},"pos":"adverb"},{"en":"at a place previously left or mentioned","cn":"在曾去过（或提到过）的地方；在前面","sc":"at a previous place","ex":{"en":"We should have turned left five kilometres back.","cn":"我们在五公里之前就该左拐的。"},"pos":"adverb"},{"en":"in return or reply","cn":"回报；回答","sc":"in return","ex":{"en":"She's a tough kid, who, when attacked, fights back hard.","cn":"她是个坚强的孩子，一旦受到攻击就会奋力反击。"},"pos":"adverb"},{"en":"at a distance away from something","cn":"（与某物）有距离","sc":"at a distance","ex":{"en":"The barriers kept the crowd back.","cn":"障碍物拦住了人群。"},"pos":"adverb"},{"en":"in or into the past; ago","cn":"以前","sc":"in past","ex":{"en":"The cathedral dates back to 1123.","cn":"这座大教堂的历史可以追溯到 1123 年。"},"pos":"adverb"},{"en":"under control; prevented from being expressed or coming out","cn":"控制住；忍住","sc":"under control","ex":{"en":"He could no longer hold back his tears.","cn":"他再也无法控制住眼泪。"},"pos":"adverb"},{"en":"fashionable again","cn":"再流行","sc":"fashionable again","ex":{"en":"Beards are back.","cn":"络腮胡子又重新流行起来。"},"pos":"adverb"},{"en":"to encourage somebody or give them help; to give financial support to somebody/something","cn":"支持；帮助；资助","g":"[transitive]","sc":"support","ex":{"en":"Her parents backed her in her choice of career.","cn":"她父母支持她的职业选择。"},"pos":"verb"},{"en":"to support and agree with somebody/something","cn":"支持；赞同","g":"[transitive]","sc":"support","ex":{"en":"Local residents are enthusiastically backing the campaign to save the library.","cn":"当地居民热心地支持拯救图书馆的运动。"},"pos":"verb"},{"en":"to help prove that something is true","cn":"帮助证明","g":"[transitive, usually passive]","sc":"support","ex":{"en":"All complaints must be backed by evidence.","cn":"所有投诉必须有证据支持。"},"pos":"verb"},{"en":"to bet money on a horse in a race, a team in a competition, etc.","cn":"下赌注于（赛马、参赛队伍等）","g":"[transitive]","sc":"bet money","ex":{"en":"I backed the winner and won fifty pounds.","cn":"我押对了赌注，赢了五十英镑。"},"pos":"verb"},{"en":"to play or sing music that supports the main singer or instrument","cn":"为…伴奏；为…伴唱","g":"[transitive]","sc":"music","pos":"verb"},{"en":"to move or make something move backwards","cn":"（使）后退，倒退","g":"[intransitive, transitive]","sc":"move backwards","ex":{"en":"He backed against the wall, terrified.","cn":"他退到墙边，惊恐万分。"},"pos":"verb"},{"en":"to cover the back of something in order to support or protect it","cn":"（用某物）在…背后加固，给…加背衬","g":"[transitive]","sc":"cover back","ex":{"en":"Each piece is backed with clear vinyl.","cn":"每一片都加了透明乙烯基塑料背衬。"},"pos":"verb"},{"en":"to be located behind something","cn":"位于（某物）的后面；在…后面","g":"[transitive, usually passive]","sc":"be behind","ex":{"en":"The house is backed by fields.","cn":"房子的后面是田野。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"向后；往后；往回","en":"If you move back, you move in the opposite direction to the one in which you are facing or in which you were moving before.","ex":{"en":"The photographers drew back to let us view the body","cn":"摄影师往后退开，好让我们查看尸体。"}},{"pos":"ADV 副词","cn":"回到原处","en":"If you go back somewhere, you return to where you were before.","ex":{"en":"I went back to bed","cn":"我回到床上。"}},{"pos":"ADV 副词","cn":"恢复原状；回到原来的状态","en":"If someone or something is back in a particular state, they were in that state before and are now in it again.","ex":{"en":"The rail company said it expected services to get slowly back to normal","cn":"铁路公司表示，其运输服务将慢慢恢复正常。"}},{"pos":"ADV 副词","cn":"归还；交还；放回；收回","en":"If you give or put something back, you return it to the person who had it or to the place where it was before you took it. If you get or take something back, you then have it again after not having it for a while.","ex":{"en":"She handed the knife back","cn":"她递还刀子。"}},{"pos":"ADV 副词","cn":"（将钟表）拨回","en":"If you put a clock or watch back, you change the time shown on it so that it shows an earlier time, for example when the time changes to winter time or standard time."},{"pos":"ADV 副词","cn":"回应（来信、电话、目光等）","en":"If you write or call back, you write to or telephone someone after they have written to or telephoned you. If you look back at someone, you look at them after they have started looking at you.","ex":{"en":"They wrote back to me and they told me that I didn't have to do it","cn":"他们回信告诉我说不必那么做。"}},{"pos":"ADV 副词","cn":"回到（某个话题）","en":"You can say that you go or come back to a particular point in a conversation to show that you are mentioning or discussing it again.","ex":{"en":"Can I come back to the question of policing once again?","cn":"我能再回到维护治安的问题上来吗？"}},{"pos":"ADV 副词","cn":"再次流行；再度成为潮流","en":"If something is or comes back, it is fashionable again after it has been unfashionable for some time.","ex":{"en":"Short skirts are back","cn":"短裙又流行起来了。"}},{"pos":"ADV 副词","cn":"在一段距离之外","en":"If someone or something is kept or situated back from a place, they are at a distance away from it.","ex":{"en":"Keep back from the edge of the platform","cn":"请勿靠近站台边缘。"}},{"pos":"ADV 副词","cn":"收拢；拢起；束起","en":"If something is held or tied back, it is held or tied so that it does not hang loosely over something.","ex":{"en":"Her hair was tied back","cn":"她的头发扎了起来。"}},{"pos":"ADV 副词","cn":"（舒适地）向后仰","en":"If you lie or sit back, you move your body backwards into a relaxed sloping or flat position, with your head and body resting on something.","ex":{"en":"She lay back and stared at the ceiling","cn":"她躺下盯着天花板。"}},{"pos":"ADV 副词","cn":"回头，转身（看或喊）","en":"If you look or shout back at someone or something, you turn to look or shout at them when they are behind you.","ex":{"en":"Nick looked back over his shoulder and then stopped, frowning","cn":"尼克回头看了看，又皱着眉头停了下来。"}},{"pos":"ADV 副词","cn":"（表示描述场所的转换）在曾提到过的地方","en":"You use back in expressions like back in London or back at the house when you are giving an account, to show that you are going to start talking about what happened or was happening in the place you mention.","ex":{"en":"Meanwhile, back in London, Palace Pictures was collapsing","cn":"与此同时，伦敦的皇宫影业公司也正在分崩离析。"}},{"pos":"ADV 副词","cn":"以前；过去；追溯至","en":"If you talk about something that happened back in the past or several years back, you are emphasizing that it happened quite a long time ago.","ex":{"en":"The story starts back in 1950, when I was five","cn":"故事可以追溯到1950年，那时我才5岁。"}},{"pos":"ADV 副词","cn":"回想；回忆","en":"If you think back to something that happened in the past, you remember it or try to remember it.","ex":{"en":"I thought back to the time in 1975 when my son was desperately ill","cn":"我回想起1975年我儿子病得奄奄一息的那段时间。"}},{"pos":"PHRASE 短语","cn":"来回；往返","en":"If someone moves back and forth, they repeatedly move in one direction and then in the opposite direction.","ex":{"en":"He paced back and forth","cn":"他来回踱步。"}},{"pos":"","cn":"","en":"to cast your mind back→see: ;"},{"pos":"N-COUNT 可数名词","cn":"背（部）；后背；脊背","en":"A person's or animal's back is the part of their body between their head and their legs that is on the opposite side to their chest and stomach.","ex":{"en":"Her son was lying peacefully on his back","cn":"她儿子安静地仰面躺着。"}},{"pos":"N-COUNT 可数名词","cn":"后面；后部","en":"The back of something is the side or part of it that is towards the rear or farthest from the front. The back of something is normally not used or seen as much as the front.","ex":{"en":"...a room at the back of the shop","cn":"商店后部的一个房间"}},{"pos":"ADJ 形容词","cn":"后面的；后部的","en":"Back is used to refer to the side or part of something that is towards the rear or farthest from the front.","ex":{"en":"He opened the back door","cn":"他打开了后门。"}},{"pos":"N-COUNT 可数名词","cn":"（椅子或沙发的）靠背","en":"The back of a chair or sofa is the part that you lean against when you sit on it.","ex":{"en":"There was a neatly folded pink sweater on the back of the chair.","cn":"椅子的靠背上搭着一件叠得整整齐齐的粉色毛衫。"}},{"pos":"N-COUNT 可数名词","cn":"（纸、信封等的）反面，背面","en":"The back of something such as a piece of paper or an envelope is the side which is less important.","ex":{"en":"Send your answers on the back of a postcard.","cn":"将答案写在明信片背面寄出。"}},{"pos":"N-COUNT 可数名词","cn":"（书等的）末尾","en":"The back of a book is the part nearest the end, where you can find the index or the notes, for example.","ex":{"en":"...the index at the back of the book","cn":"书末索引"}},{"pos":"N-SING 单数名词","cn":"（用于round the back, out the back等表达方式中）房屋（或其他建筑物）后的区域","en":"You can use back in expressions such as round the back and out the back to refer generally to the area behind a house or other building.","ex":{"en":"He had chickens and things round the back","cn":"他在房子后面养了些鸡啊什么的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（用于out back等表达方式中）房屋（或其他建筑物）后的区域；（用于in back等表达方式中）汽车（或建筑物等）的后部","en":"You use back in expressions such as out back to refer to the area behind a house or other building. You also use in back to refer to the rear part of something, especially a car or building.","ex":{"en":"Dan informed her that he would be out back on the patio cleaning his shoes","cn":"丹告诉她说他要去房子后面的露台上擦鞋。"}},{"pos":"N-COUNT 可数名词","cn":"（足球、曲棍球等运动中的）后卫","en":"In team games such as football and hockey, a back is a player who is concerned mainly with preventing the other team from scoring goals, rather than scoring goals for their own team."},{"pos":"N-COUNT 可数名词","cn":"（美式橄榄球运动中的）进攻后卫","en":"In American football, a back is a player who stands behind the front line, runs with the ball and attacks rather than defends."},{"pos":"PHRASE 短语","cn":"背着（某人）","en":"If you say that something was done behind someone's back, you disapprove of it because it was done without them knowing about it, in an unfair or dishonest way.","ex":{"en":"You eat her food, enjoy her hospitality and then criticize her behind her back.","cn":"你吃着她的食物，享受着她的款待，然后还在背地里指责她。"}},{"pos":"PHRASE 短语","cn":"完成…最困难的部分","en":"If you break the back of a task or problem, you do the most difficult part of what is necessary to complete the task or solve the problem.","ex":{"en":"It seems at least that we've broken the back of inflation in this country","cn":"看起来至少我们已经解决了这个国家通货膨胀中最棘手的问题。"}},{"pos":"PHRASE 短语","cn":"接连地；连续地","en":"If two or more things are done back to back, one follows immediately after the other without any interruption.","ex":{"en":"...two half-hour shows, which will be screened back to back.","cn":"连续播放的两档半小时节目"}},{"pos":"PHRASE 短语","cn":"（衣服）前后穿反；（顺序）前后颠倒","en":"If you are wearing something back to front, you are wearing it with the back of it at the front of your body. If you do something back to front, you do it the wrong way around, starting with the part that should come last.","ex":{"en":"He wears his baseball cap back to front","cn":"他把棒球帽反戴着。"}},{"pos":"PHRASE 短语","cn":"不再（对某人）批评（或施压等）","en":"If you tell someone to get off your back you are telling them angrily to stop criticizing you or putting pressure on you.","ex":{"en":"He kept on at me to such an extent that occasionally I wished he would get off my back.","cn":"他一直对我唠叨个没完，有时我真希望他不要再烦我了。"}},{"pos":"PHRASE 短语","cn":"紧跟着；紧接着","en":"If you say that one thing happens on the back of another thing, you mean that it happens after that other thing and in addition to it.","ex":{"en":"The cuts, if approved, come on the back of a difficult eight years that have seen three London fire stations closed.","cn":"8年的艰难时期刚刚过去，在此期间，伦敦有3家消防站遭关闭。如获批准，裁减又会接踵而至。"}},{"pos":"PHRASE 短语","cn":"（使）受到威胁；（使）处于不利地位","en":"If someone is on the back foot, or if something puts them on the back foot, they feel threatened and act defensively.","ex":{"en":"From now on Labour will be on the back foot on the subject of welfare.","cn":"今后工党在福利问题上将处于下风。"}},{"pos":"PHRASE 短语","cn":"互相帮助；与人方便，与己方便","en":"People say 'You scratch my back and I'll scratch yours' to mean that one person helps another on condition that the second person helps them in return."},{"pos":"PHRASE 短语","cn":"希望（某人）离开","en":"If you say that you will be glad to see the back of someone, you mean that you want them to leave.","ex":{"en":"I was so badly behaved I was convinced she would be glad to see the back of me.","cn":"我的表现如此差劲，相信她会很高兴看到我离开。"}},{"pos":"PHRASE 短语","cn":"忽略；背弃；拒绝；对…不予理睬","en":"If you turn your back on someone or something, you ignore them, leave them, or reject them.","ex":{"en":"Stacey Lattisaw has turned her back on her singing career with Motown Records to become a gospel singer","cn":"斯泰茜·拉蒂索抛弃了自己在摩城唱片公司的演唱事业，成为了一名福音歌手。"}},{"pos":"PHRASE 短语","cn":"使生气；触怒；惹恼","en":"If someone or something puts your back up or gets your back up, they annoy you.","ex":{"en":"Some food labelling practices really get my back up.","cn":"有些食物标签的贴法实在让我生气。"}},{"pos":"","cn":"","en":"off the back of a lorry→see: ; to take a back seat→see: ; to have your back to the wall→see: ;"},{"pos":"VERB 动词","cn":"背对；背向；背朝","en":"If a building backs onto something, the back of it faces in the direction of that thing or touches the edge of that thing.","ex":{"en":"We live in a ground floor flat which backs onto a busy street","cn":"我们住在一楼的一套公寓房里，背对着一条繁忙的街道。"}},{"pos":"V-ERG 及物/不及物动词","cn":"倒（车）；倒退","en":"When you back a car or other vehicle somewhere or when it backs somewhere, it moves backwards.","ex":{"en":"He backed his car out of the drive","cn":"他把车倒出了私人车道。"}},{"pos":"VERB 动词","cn":"支持；资助","en":"If you back a person or a course of action, you support them, for example by voting for them or giving them money.","ex":{"en":"There is a new witness to back his claim that he is a victim of mistaken identity.","cn":"有新的目击证人证明他的说法，他是被错认了。"}},{"pos":"VERB 动词","cn":"预测…获胜；（通常指）下赌注于","en":"If you back a particular person, team, or horse in a competition, you predict that they will win, and usually you bet money that they will win.","ex":{"en":"Roland Nilsson last night backed Sheffield Wednesday to win the UEFA Cup","cn":"昨晚罗兰·尼尔森打赌谢菲尔德周三队会捧得欧洲联盟杯。"}},{"pos":"VERB 动词","cn":"为…伴奏（或伴唱）","en":"If a singer is backed by a band or by other singers, they provide the musical background for the singer.","ex":{"en":"She was backed by acoustic guitar, bass and congas.","cn":"原声吉他、贝斯和康茄鼓为她伴奏。"}},{"pos":"","cn":"","en":"相关词组：back away back down back off back out back up"}]},"examples":[{"en":"We were right back where we started , only this time without any money.","cn":"我们回到了起点，只是这次一点钱也没有。"},{"en":"The profits growth came on the back of a 26 per cent rise in sales.","cn":"利润增长来自 26% 的销售额增长。"}]},"barring":{"oxford":{"phon":"ˈbɑːrɪŋ","pos":"preposition","senses":[{"en":"except for; unless there is/are","cn":"除了；除非","ex":{"en":"Barring accidents, we should arrive on time.","cn":"除非有意外情况，我们应可按时到达。"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"不包括；除…以外","en":"You use barring to indicate that the person, thing, or event that you are mentioning is an exception to your statement.","ex":{"en":"Barring accidents, I believe they will succeed.","cn":"不出意外的话，我相信他们会成功的。"}}]},"media":{"uk":"media/uk/barring__gb_1.mp3","us":"media/us/barring__us_1.mp3"},"examples":[{"en":"Barring accidents, we should arrive on time.","cn":"除非有意外情况，我们应可按时到达。"},{"en":"Barring a miracle, he won’t walk again.","cn":"他走不了路了，除非出现奇迹。"}]},"batter":{"oxford":{"phon":"ˈbætə(r)","pos":"verb","senses":[{"en":"to hit somebody/something hard many times, especially in a way that causes serious damage","cn":"连续猛击；殴打","ex":{"en":"She battered at the door with her fists.","cn":"她用双拳不断地擂门。"}},{"en":"a mixture of eggs, milk and flour used in cooking to cover food such as fish or chicken before you fry it, or to make pancakes","cn":"面糊（煎料）","g":"[uncountable, countable]","ex":{"en":"fish in batter","cn":"蘸了面糊的鱼"},"pos":"noun"},{"en":"a mixture of eggs, milk, flour, etc. used for making cakes","cn":"面糊（用于做糕饼）","g":"[uncountable, countable]","lab":"North American English","ex":{"en":"Pour the batter into a prepared pan.","cn":"把面糊倒入准备好的平底锅内。"},"pos":"noun"},{"en":"the player who is hitting the ball","cn":"击球手；击球员","g":"[countable]","ex":{"en":"Rivera faced seven batters and retired six.","cn":"里韦拉对付 7 个击球手，让 6 个出局。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"殴打；痛打；毒打","en":"If someone is battered, they are regularly hit and badly hurt by a member of their family or by their partner.","ex":{"en":"...evidence that the child was being battered.","cn":"这个孩子被家人毒打的证据"}},{"pos":"VERB 动词","cn":"（用拳头或重物）多次重击，连续猛打（某人）","en":"To batter someone means to hit them many times, using fists or a heavy object.","ex":{"en":"He battered her around the head","cn":"他连续重击她的头部。"}},{"pos":"VERB 动词","cn":"（风、雨或暴风雪等）肆虐，严重破坏","en":"If a place is battered by wind, rain, or storms, it is seriously damaged or affected by very bad weather.","ex":{"en":"The country has been battered by winds of between fifty and seventy miles an hour.","cn":"该国遭受到时速高达50至70英里的大风袭击，破坏严重。"}},{"pos":"VERB 动词","cn":"（用拳头或重物）多次重击,连续猛打（某物）","en":"If you batter something, you hit it many times, using your fists or a heavy object.","ex":{"en":"They were battering the door, they were breaking in","cn":"他们正在使劲捶门，就要闯进来了。"}},{"pos":"N-VAR 可变名词","cn":"（面粉、鸡蛋和牛奶和成的）糊，面糊","en":"Batter is a mixture of flour, eggs, and milk that is used in cooking.","ex":{"en":"...pancake batter.","cn":"做煎饼的面糊"}},{"pos":"N-COUNT 可数名词","cn":"（棒球和垒球等运动中的）击球员，击球手","en":"In sports such as baseball and softball, a batter is a person who hits the ball with a wooden bat.","ex":{"en":"...batters and pitchers.","cn":"击球手和投球手们"}},{"pos":"","cn":"","en":"相关词组：batter down"}]},"media":{"uk":"media/uk/batter__gb_1.mp3","us":"media/us/batter__us_1.mp3"},"examples":[{"en":"Her killer had battered her to death.","cn":"杀害她的凶手把她殴打致死。"},{"en":"Severe winds have been battering the north coast.","cn":"狂风一直在北海岸肆虐。"}]},"bachelor":{"oxford":{"phon":"ˈbætʃələ(r)","pos":"noun","senses":[{"en":"a man who has never been married","cn":"未婚男子；单身汉","ex":{"en":"an eligible bachelor (= one that many people want to marry, especially because he is rich)","cn":"合意单身男子（尤因富有而为理想对象）"}},{"en":"a person who has a Bachelor’s degree (= a first university degree)","cn":"学士","ex":{"en":"a Bachelor of Arts/Engineering/Science","cn":"文学士；工程学士；理学士"}},{"en":"a small apartment suitable for a person living alone","cn":"单身套房；单身公寓房","lab":"Canadian English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"未婚男子；单身汉","en":"A bachelor is a man who has never married."}]},"media":{"uk":"media/uk/bachelor__gb_1.mp3","us":"media/us/bachelor__us_1.mp3"},"examples":[{"en":"a confirmed bachelor (= a person who does not intend to marry; often used in newspapers to refer to a homosexual man)","cn":"信守独身主义的单身汉（报章上常用来指同性恋男子）"},{"en":"an eligible bachelor (= one that many people want to marry, especially because he is rich)","cn":"合意单身男子（常因富有而为理想对象）"}]},"basement":{"media":{"uk":"media/uk/basement__gb_1.mp3","us":"media/us/basement__us_1.mp3"},"oxford":{"phon":"ˈbeɪsmənt","pos":"noun","senses":[{"en":"a room or rooms in a building, partly or completely below the level of the ground","cn":"地下室","ex":{"en":"Kitchen goods are sold in the basement.","cn":"厨房用具在地下室出售。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"地下室；地下层","en":"The basement of a building is a floor built partly or completely below ground level.","ex":{"en":"They bought an old schoolhouse to live in and built a workshop in the basement","cn":"他们买了一处老校舍当住房，然后在地下室里建了一个作坊。"}}]},"examples":[{"en":"Kitchen goods are sold in the basement.","cn":"厨房用具在地下室出售。"},{"en":"a basement flat/apartment","cn":"设在地下室的一套房间"}]},"balmy":{"media":{"uk":"media/uk/balmy__gb_1.mp3","us":"media/us/balmy__us_1.mp3"},"oxford":{"phon":"ˈbɑːmi","pos":"adjective","senses":[{"en":"warm and pleasant","cn":"温暖惬意的","ex":{"en":"a balmy summer evening","cn":"清爽宜人的夏夜"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（天气）温暖舒适的，温和宜人的","en":"Balmy weather is fairly warm and pleasant.","ex":{"en":"...a balmy summer's evening.","cn":"宜人的夏夜"}}]},"examples":[{"en":"a balmy summer evening","cn":"清爽宜人的夏夜"},{"en":"a balmy summer night","cn":"一个宜人的夏夜"}]},"backward":{"media":{"uk":"media/uk/backward__gb_1.mp3","us":"media/us/backward__us_1.mp3"},"oxford":{"phon":"ˈbækwəd","pos":"adjective","senses":[{"en":"directed or moving towards the back","cn":"向后的；朝后的","g":"[only before noun]","ex":{"en":"She strode past him without a backward glance.","cn":"她大步从他身边走过，都没有回头瞧他一眼。"}},{"en":"moving in a direction that means that no progress is being made","cn":"倒退的；反向的","ex":{"en":"She felt that going back to live in her home town would be a backward step.","cn":"她觉得回到家乡生活就是退步。"}},{"en":"having made less progress than normal; developing slowly","cn":"落后的；进步缓慢的","lab":"British English, informal，，","ex":{"en":"a backward part of the country, with no paved roads and no electricity","cn":"该国的一个落后地区，没有铺设马路也没有电力"}},{"en":"slow to learn; finding it difficult to make progress in learning","cn":"学习速度慢；发现学习上很难取得进步","lab":"old-fashioned, offensive，，"},{"en":"towards a place or position that is behind","cn":"向后","ex":{"en":"I lost my balance and fell backward.","cn":"我失去平衡，向后倒去。"},"pos":"adverb"},{"en":"in the opposite direction to the usual one","cn":"朝反方向；倒着","ex":{"en":"In the movie they take a journey backward through time.","cn":"在电影中，他们进行了一次穿越时空的旅行。"},"pos":"adverb"},{"en":"towards a worse state","cn":"每况愈下地","ex":{"en":"I felt that going to live with my parents would be a step backward.","cn":"我觉得和父母住在一起会是一种倒退。"},"pos":"adverb"},{"en":"if you put on a piece of clothing backward, you make a mistake and put the back where the front should be","cn":"（衣服）前后颠倒（或前后穿反）","lab":"North American English","pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"向后的，往后的（一些人亦使用backwards)","en":"A backward movement or look is in the direction that your back is facing. Some people use backwards for this meaning.","ex":{"en":"He unlocked the door of apartment two and disappeared inside after a backward glance at Larry","cn":"他打开2号公寓的门，回头瞥了拉里一眼，然后就进了房间。"}},{"pos":"ADJ 形容词","cn":"倒退的；不进反退的","en":"If someone takes a backward step, they do something that does not change or improve their situation, but causes them to go back a stage.","ex":{"en":"At a certain age, it's not viable for men to take a backward step into unskilled work","cn":"到了一定的年龄，就不可能再退回去干不需要技能的工作。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"落后的","en":"A backward country or society does not have modern industries and machines.","ex":{"en":"We need to accelerate the pace of change in our backward country.","cn":"我们应当为落后的祖国加快变革的脚步。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"迟钝的；学习吃力的","en":"A backward child has difficulty in learning.","ex":{"en":"...research into teaching techniques to help backward children","cn":"关于帮助落后孩子的教学方法研究"}}]},"examples":[{"en":"a backward part of the country, with no paved roads and no electricity","cn":"该国的一个落后地区，没有铺设马路也没有电力"},{"en":"She strode past him without a backward glance.","cn":"她大步从他身边走过，都没有回头瞧他一眼。"}]},"bazaar":{"media":{"uk":"media/uk/bazaar__gb_1.mp3","us":"media/us/bazaar__us_1.mp3"},"oxford":{"phon":"bəˈzɑː(r)","pos":"noun","senses":[{"en":"a street or an area of a town where there are many small shops","cn":"街市；集市","ex":{"en":"rugs on sale in the Turkish bazaars","cn":"土耳其集市上出售的地毯"}},{"en":"a sale of goods, often items made by hand, to raise money for a charity or for people who need help","cn":"义卖","ex":{"en":"She got it at the church bazaar.","cn":"她是在教堂集市上买的。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"集市；市场","en":"In areas such as the Middle East and India, a bazaar is a place where there are many small shops and stalls.","ex":{"en":"Kamal was a vendor in Egypt's open-air bazaar.","cn":"卡迈勒是埃及露天集市里的一个小贩。"}},{"pos":"N-COUNT 可数名词","cn":"义卖","en":"A bazaar is a sale to raise money for charity.","ex":{"en":"...a church bazaar.","cn":"教堂义卖"}}]},"examples":[{"en":"a church bazaar","cn":"教堂义卖"}]},"balls":{"media":{"uk":"media/uk/balls__gb_1.mp3","us":"media/us/balls__us_1.mp3"},"oxford":{"phon":"bɔːlz","pos":"noun","senses":[{"en":"an offensive word for ideas, statements or beliefs that you think are silly or not true","cn":"胡扯","g":"[uncountable]","lab":"British English, offensive, slang，，，，","ex":{"en":"That's a load of balls!","cn":"那是一派胡言！"}},{"en":"courage","cn":"勇气","g":"[plural]","ex":{"en":"She's got balls, I'll say that for her.","cn":"我敢说她有胆量。"}},{"en":"used as a swear word when you are disagreeing with something, or when you are angry about something","cn":"（粗俗话，表示不同意或恼怒）","lab":"British English, offensive, slang，，，，"},{"en":"testicles","cn":"睾丸","g":"[plural]","lab":"informal"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"勇气；胆识","en":"If you say that someone has balls, you mean that they have courage.","ex":{"en":"To work on this show you've got to have balls","cn":"要参与这个节目的制作，你得够大胆。"}},{"pos":"EXCLAM; N-UNCOUNT 感叹词；不可数名词","cn":"胡说八道；屁话","en":"You can say 'balls' or say that what someone says is balls when you think that it is stupid or wrong.","ex":{"en":"What complete and utter balls!","cn":"全是屁话！"}},{"pos":"","cn":"","en":"相关词组：balls up"}]},"examples":[{"en":"It took a lot of balls to do that.","cn":"那么做需要很大的勇气。"},{"en":"The team went balls out in the final.","cn":"决赛时这个队拼得很凶。"}]},"bad":{"media":{"uk":"media/uk/bad__gb_1.mp3","us":"media/us/bad__us_1.mp3"},"oxford":{"phon":"bæd","pos":"adjective","senses":[{"en":"unpleasant; full of problems","cn":"令人不快的；问题成堆的；坏的","sc":"unpleasant","ex":{"en":"I have some bad news for you, I'm afraid.","cn":"我恐怕有些坏消息告诉你。"}},{"en":"of poor quality; below an acceptable standard","cn":"质量差的；不合格的","sc":"poor quality","ex":{"en":"I thought it was a very bad article.","cn":"我以为那是一篇很低劣的文章。"}},{"en":"serious; severe","cn":"严重的；剧烈的","sc":"serious","ex":{"en":"You're heading for a bad case of sunburn.","cn":"你会被严重晒伤的。"}},{"en":"not appropriate in a particular situation","cn":"不适合的；不适当的","g":"[only before noun]","sc":"not appropriate","ex":{"en":"I know that this is a bad time to ask for help.","cn":"我知道在这时候要求帮助不合适。"}},{"en":"morally unacceptable","cn":"不道德的；邪恶的","sc":"wicked","ex":{"en":"The hero gets to shoot all the bad guys.","cn":"主人公结果射杀了所有的坏蛋。"}},{"en":"not behaving well","cn":"顽皮的；不乖的","g":"[usually before noun]","sc":"children","ex":{"en":"Have you been a bad boy?","cn":"你调皮了吗？"}},{"en":"not able to do something well or in an acceptable way","cn":"拙于；不擅；不善于","sc":"not good at something","ex":{"en":"a bad teacher","cn":"不称职的教师"}},{"en":"harmful; causing or likely to cause damage","cn":"有害；招致损害","g":"[not before noun]","sc":"harmful","ex":{"en":"Those shoes are bad for her feet.","cn":"那双鞋会伤她的脚。"}},{"en":"not healthy; painful","cn":"有病的；疼痛的","g":"[usually before noun]","sc":"painful","ex":{"en":"I've got a bad back.","cn":"我背部疼痛。"}},{"en":"not safe to eat because it has decayed (= started to be destroyed by natural processes)","cn":"变质的；腐坏的","sc":"food","ex":{"en":"Put the meat in the fridge so it doesn't go bad.","cn":"把肉放进冰箱里，免得坏了。"}},{"en":"the state of feeling annoyed or angry","cn":"发脾气；坏情绪；恼怒","sc":"temper/mood","ex":{"en":"It put me in a bad mood for the rest of the day.","cn":"那事让我整天再也没了好心情。"}},{"en":"to feel guilty or sorry about something","cn":"感到愧疚（或遗憾）","sc":"guilty/sorry","ex":{"en":"She felt pretty bad about leaving him.","cn":"她因离开他而感到相当歉疚。"}},{"en":"to feel or look ill","cn":"觉得不舒服；感到有病；面有病容；气色不好","sc":"ill/sick","ex":{"en":"I'm afraid I'm feeling pretty bad.","cn":"很抱歉，我觉得很不舒服。"}},{"en":"good; excellent","cn":"顶呱呱的","lab":"especially North American English, slang，，","sc":"excellent"},{"en":"bad people, things, or events","cn":"坏人；坏事（物）","ex":{"en":"You will always have the bad as well as the good in the world.","cn":"人生在世总是有苦有甜。"},"pos":"noun"},{"en":"badly","cn":"很；非常","lab":"North American English, informal，，","ex":{"en":"She wanted it real bad.","cn":"她确实很想得到它。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坏的；令人不快的；不合意的；有害的；糟糕的","en":"Something that is bad is unpleasant, harmful, or undesirable.","ex":{"en":"The bad weather conditions prevented the plane from landing","cn":"糟糕的天气使飞机无法降落。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"严重的；厉害的；剧烈的","en":"You use bad to indicate that something unpleasant or undesirable is severe or great in degree.","ex":{"en":"He had a bad accident two years ago and had to give up farming","cn":"他两年前遇到严重的车祸，不得不放弃务农。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不明智的；错误的；不对的","en":"A bad idea, decision, or method is not sensible or not correct.","ex":{"en":"Economist Jeffrey Faux says a tax cut is a bad idea","cn":"经济学家杰弗里·福克斯认为减税是不明智的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不利的；不幸的","en":"If you describe a piece of news, an action, or a sign as bad, you mean that it is unlikely to result in benefit or success.","ex":{"en":"The closure of the project is bad news for her staff","cn":"项目终止对她的雇员来说是一个不幸的消息。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不合标准的；劣质的；蹩脚的；不足的","en":"Something that is bad is of an unacceptably low standard, quality, or amount.","ex":{"en":"She was in rather a bad film about the Mau Mau","cn":"她出演了一部关于茅茅运动（20世纪50年代肯尼亚基库尤人反抗英国殖民者的民族主义运动）的烂片。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不擅长的；不善于的","en":"Someone who is bad at doing something is not skilful or successful at it.","ex":{"en":"He had increased Britain's reputation for being bad at languages","cn":"他加深了人们对英国人不擅长语言的印象。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难以接受的；令人遗憾的","en":"If you say that it is bad that something happens, you mean it is unacceptable, unfortunate, or wrong.","ex":{"en":"Not being able to hear doesn't seem as bad as not being able to see","cn":"看不见比听不到更让人难以忍受。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（尤表示惊讶）不错的，不坏的，挺好的","en":"You can say that something is not bad to mean that it is quite good or acceptable, especially when you are rather surprised about this.","ex":{"en":"'How much is he paying you?' — 'Oh, five thousand.' —'Not bad.'","cn":"“他给你多少钱？”——“哦，5,000。”——“挺不错嘛。”"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"邪恶的；不道德的","en":"A bad person has morally unacceptable attitudes and behaviour.","ex":{"en":"I was selling drugs, but I didn't think I was a bad person","cn":"我贩卖毒品，但我并不觉得自己是个坏人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不听话的；调皮的；捣蛋的","en":"A bad child disobeys rules and instructions or does not behave in a polite and correct way.","ex":{"en":"You are a bad boy for repeating what I told you","cn":"重复我对你说的话，你真是个捣蛋鬼。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易怒的；乖戾的；阴郁的","en":"If you are in a bad mood, you are angry and behave unpleasantly to people.","ex":{"en":"She is in a bit of a bad mood because she's just given up smoking.","cn":"因为她刚刚戒烟，所以脾气有点大。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"抱歉的；难过的；内疚的","en":"If you feel bad about something, you feel rather sorry or guilty about it.","ex":{"en":"You don't have to feel bad about relaxing","cn":"你不必为放松感到内疚。"}},{"pos":"ADJ 形容词","cn":"受伤的；有病的；虚弱的","en":"If you have a bad back, heart, leg, or eye, it is injured, diseased, or weak.","ex":{"en":"Alastair has a bad back so we have a hard bed.","cn":"阿拉斯泰尔背部有毛病，所以我们睡硬板床。"}},{"pos":"ADJ 形容词","cn":"变质的；腐烂的","en":"Food that has gone bad is not suitable to eat because it has started to decay.","ex":{"en":"They bought so much beef that some went bad.","cn":"他们买了太多牛肉，有些都变质了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"污秽的；咒骂的","en":"Bad language is language that contains offensive words such as swear words.","ex":{"en":"I don't like to hear bad language in the street","cn":"我不喜欢在街上听见一些污言秽语。"}},{"pos":"PHRASE 短语","cn":"…真可惜；…真遗憾","en":"If you say that it is too bad that something is the case, you mean you are sorry or sad that it is the case.","ex":{"en":"It is too bad that Eleanor had to leave so soon","cn":"埃莉诺不得不这么快就离开，真是太遗憾了。"}},{"pos":"CONVENTION 惯用语","cn":"（表示无法改变，亦不觉得抱歉或同情）算…倒霉","en":"If you say 'too bad', you are indicating that nothing can be done to change the situation, and that you do not feel sorry or sympathetic about this.","ex":{"en":"Too bad if you missed the bus.","cn":"你没有赶上公交车只能算自己倒霉。"}},{"pos":"PHRASE 短语","cn":"境况不佳；处于困境","en":"If someone or something is in a bad way, they are in a bad condition or situation.","ex":{"en":"The economy is in a bad way","cn":"经济陷入困境。"}},{"pos":"PHRASE 短语","cn":"对…有不好的评价；说…的坏话","en":"If nobody has a bad word to say about you, you are liked or admired by everyone.","ex":{"en":"She's got beauty, wealth, and fame, and we still can't find anyone with a bad word to say about her.","cn":"她美丽，富有，出名，而且我们还没有发现谁说她不好。"}},{"pos":"","cn":"","en":"to make the best of a bad job→see: ; bad blood→see: ; to be in someone's bad books→see: ; bad luck→see: ; to get a bad press→see: ; to go from bad to worse→see: ;"}]},"examples":[{"en":"You're not seeing him again tonight, are you? That's five times this week — you've got it bad!","cn":"你今天晚上不再和他见面了，是吧？这个星期都约会了五次，你们热恋了！"},{"en":"Things are bad enough without our own guns shelling us.","cn":"本来情况就够糟的了，偏偏我们自己的大炮又向我们开起火来。"}]},"basic":{"media":{"uk":"media/uk/basic__gb_1.mp3","us":"media/us/basic__us_1.mp3"},"oxford":{"phon":"ˈbeɪsɪk","pos":"adjective","senses":[{"en":"forming the part of something that is most necessary and from which other things develop","cn":"基本的；基础的","ex":{"en":"basic information/facts/ideas","cn":"基本信息／事实／思想"}},{"en":"of the simplest kind or at the simplest level","cn":"最简单的；初级的；初步的","ex":{"en":"The campsite has only basic amenities.","cn":"野营地只有一些基本设施。"}},{"en":"necessary and important to all people","cn":"必需的；基本需要的","g":"[only before noun]","ex":{"en":"basic human rights","cn":"基本人权"}},{"en":"before anything extra is added","cn":"基本的；没有附加成分的","lab":"especially British English","ex":{"en":"The basic pay of the average worker has risen by 3 per cent.","cn":"工人的平均基本工资上升了 3%。"}},{"en":"a simple language, using familiar English words, for writing computer programs","cn":"BASIC 语言，初学者通用符号指令码（一种使用一般英语词汇的简单计算机编程语言）","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"根本的；首要的；主要的","en":"You use basic to describe things, activities, and principles that are very important or necessary, and on which others depend.","ex":{"en":"One of the most basic requirements for any form of angling is a sharp hook.","cn":"不管以什么方式钓鱼，有一个锋利的鱼钩都是最基本的要求之一。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"基本的；起码的","en":"Basic goods and services are very simple ones which every human being needs. You can also refer to people's basic needs for such goods and services.","ex":{"en":"...shortages of even the most basic foodstuffs","cn":"最基本食物的短缺"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"基础的；必要的","en":"If one thing is basic to another, it is absolutely necessary to it, and the second thing cannot exist, succeed, or be imagined without it.","ex":{"en":"...an oily liquid, basic to the manufacture of a host of other chemical substances","cn":"制造许多其他化学物质所必需的油性液体"}},{"pos":"ADJ 形容词","cn":"根本的；最重要的","en":"You can use basic to emphasize that you are referring to what you consider to be the most important aspect of a situation, and that you are not concerned with less important details.","ex":{"en":"There are three basic types of tea","cn":"茶主要分为三种。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"最简单的；最基本的；最朴实的","en":"You can use basic to describe something that is very simple in style and has only the most necessary features, without any luxuries.","ex":{"en":"We provide 2-person tents and basic cooking and camping equipment.","cn":"我们提供双人帐篷和最基本的炊具以及露营装备。"}},{"pos":"ADJ 形容词","cn":"（价格、工资等）基本的","en":"Basic is used to describe a price or someone's income when this does not include any additional amounts.","ex":{"en":"...an increase of more than twenty per cent on the basic pay of a typical coalface worker","cn":"普通采煤工人的底薪上浮超过20％"}},{"pos":"ADJ 形容词","cn":"（所得税率）最低标准的，基本的","en":"The basic rate of income tax is the lowest or most common rate, which applies to people who earn average incomes.","ex":{"en":"All this is to be done without big rises in the basic level of taxation.","cn":"所有这些都必须在未大幅度提高税收起征点的前提下完成。"}}]},"examples":[{"en":"The basic pay of the average worker has risen by 3 per cent.","cn":"工人的平均基本工资上升了 3%。"},{"en":"The campsite provided only basic facilities.","cn":"野营地只提供最基本的设施。"}]},"bank":{"media":{"uk":"media/uk/bank__gb_1.mp3","us":"media/us/bank__us_1.mp3"},"oxford":{"phon":"bæŋk","pos":"noun","senses":[{"en":"an organization that provides various financial services, for example keeping or lending money","cn":"银行","sc":"for money","ex":{"en":"I don't have much money in the bank at the end of the month.","cn":"每到月底我在银行里都剩不下多少钱。"}},{"en":"a supply of money or things that are used as money in some games, especially those in which gambling is involved","cn":"（尤指赌博中的）筹码；赌本","sc":"in gambling"},{"en":"an amount of something that is collected; a place where something is stored ready for use","cn":"库存；库","sc":"something collected/stored","ex":{"en":"a bank of knowledge","cn":"知识宝库"}},{"en":"a place or container where something may be placed for recycling","cn":"废品回收站；回收桶","sc":"for recycling","ex":{"en":"Take old clothes and shoes to the local recycling bank.","cn":"将旧衣服和鞋子带到当地的回收银行。"}},{"en":"the side of a river, canal, etc. and the land near it","cn":"岸；河畔","sc":"of river/canal","ex":{"en":"We strolled along the river bank.","cn":"我们沿着河岸散步。"}},{"en":"a raised area of ground that slopes at the sides, often at the edge of something or dividing something","cn":"斜坡；垄；埂","sc":"slope","ex":{"en":"There were low banks of earth between the rice fields.","cn":"稻田之间有低矮的田埂。"}},{"en":"an artificial slope built at the side of a road, so that cars can drive fast around bends","cn":"（路面拐弯处为方便车辆快速行驶而筑起的）边坡","sc":"slope"},{"en":"a mass of cloud, snow, etc., especially one formed by the wind","cn":"（尤指风吹到一起的）积云，积雪","sc":"of cloud/snow, etc.","ex":{"en":"The sun disappeared behind a bank of clouds.","cn":"太阳消失在一大片云后面。"}},{"en":"a row or series of similar objects, especially machines","cn":"一排，一系列（同类物品，尤指机器）","sc":"of machines, etc.","ex":{"en":"a bank of lights/computers","cn":"一排灯/电脑"}},{"en":"to put money into a bank account","cn":"把（钱）存入银行","g":"[transitive]","sc":"money","ex":{"en":"She is believed to have banked (= been paid) £10 million in two years.","cn":"据信她两年内在银行存了 1 000 万英镑。"},"pos":"verb"},{"en":"to have an account with a particular bank","cn":"（在某银行）开账户，存款","g":"[intransitive]","sc":"money","ex":{"en":"The family had banked with Coutts for generations.","cn":"那家几代人都在库茨银行存钱。"},"pos":"verb"},{"en":"to travel with one side higher than the other when turning","cn":"（转弯时）倾斜飞行","g":"[intransitive]","sc":"of plane","ex":{"en":"The plane banked steeply to the left.","cn":"飞机向左作高度倾斜飞行。"},"pos":"verb"},{"en":"to form something into piles","cn":"堆积（某物）","g":"[transitive]","sc":"form piles","ex":{"en":"They banked the earth (up) into a mound.","cn":"他们把土堆成了一个土丘。"},"pos":"verb"},{"en":"to pile coal, etc. on a fire so that the fire burns slowly for a long time","cn":"（用煤等）封炉火","g":"[transitive]","sc":"a fire","ex":{"en":"The fire was banked up as high as if it were midwinter.","cn":"炉火被封得很厚实，好像是在隆冬。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"银行","en":"A bank is an institution where people or businesses can keep their money.","ex":{"en":"Which bank offers you the service that best suits your financial needs?","cn":"哪家银行提供的服务最适合您的理财需求？"}},{"pos":"N-COUNT 可数名词","cn":"银行营业厅；银行办事处","en":"A bank is a building where a bank offers its services."},{"pos":"VERB 动词","cn":"把（钱）存入银行","en":"If you bank money, you pay it into a bank.","ex":{"en":"Once you have registered your particulars with an agency and it has banked your cheque, the process begins.","cn":"一旦在某个代理行登记了详细信息并由它将支票存入银行，这一程序就开始了。"}},{"pos":"VERB 动词","cn":"与（银行）有业务来往；在（银行）有账户","en":"If you bank with a particular bank, you have an account with that bank.","ex":{"en":"My husband has banked with the Co-op since before the war.","cn":"我丈夫自战前以来就在合作银行有户头。"}},{"pos":"N-COUNT 可数名词","cn":"库（如血库等）","en":"You use bank to refer to a store of something. For example, a blood bank is a store of blood that is kept ready for use.","ex":{"en":"...Britain's National Police Computer, one of the largest data banks in the world.","cn":"英国国家警务计算机系统，世界上最大的数据库之一"}},{"pos":"PHRASE 短语","cn":"斥巨资；花费大笔的钱；倾家荡产","en":"If you say that the cost of something will not break the bank, you mean that it will not cost a large sum of money.","ex":{"en":"Prices starting at £6 a bottle won't break the bank.","cn":"每瓶6英镑的起价不算太贵。"}},{"pos":"N-COUNT 可数名词","cn":"（河、湖等的）岸，堤岸","en":"The banks of a river, canal, or lake are the raised areas of ground along its edge.","ex":{"en":"...30 miles of new developments along both banks of the Thames.","cn":"泰晤士河两岸30英里的新开发区"}},{"pos":"N-COUNT 可数名词","cn":"垄；埂","en":"A bank of ground is a raised area of it with a flat top and one or two sloping sides.","ex":{"en":"...resting indolently upon a grassy bank.","cn":"懒洋洋地躺在草埂上休息"}},{"pos":"N-COUNT 可数名词","cn":"（长条形的）堆，团","en":"A bank of something is a long high mass of it.","ex":{"en":"On their journey south they hit a bank of fog off the north-east coast of Scotland.","cn":"南行途中，他们在苏格兰东北海岸外遭遇了大雾。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指机器、开关、仪表的）（一）排，（一）组","en":"A bank of things, especially machines, switches, or dials, is a row of them, or a series of rows.","ex":{"en":"The typical laborer now sits in front of a bank of dials.","cn":"现如今，工人通常都是坐在一排仪表前。"}},{"pos":"VERB 动词","cn":"（通常指飞机在改变方向时）倾斜飞行","en":"When an aircraft banks, one of its wings rises higher than the other, usually when it is changing direction.","ex":{"en":"A plane took off and banked above the highway in front of him.","cn":"一架飞机起飞后在他前方的公路上空侧飞转向。"}},{"pos":"","cn":"","en":"相关词组：bank on"}]},"examples":[{"en":"She is believed to have banked (= been paid) £10 million in two years.","cn":"据信她两年内在银行存了 1 000 万英镑。"},{"en":"‘I'm sure he'll help.’ ‘ Don't bank on it (= it is not likely to happen). ’ “","cn":"我相信他会帮忙的。” “那可不见得。”"}]},"bay":{"media":{"img":["media/pic/herbs_comp.jpg","media/thumb/bay.jpg"],"uk":"media/uk/bay__gb_1.mp3","us":"media/us/bay__us_1.mp3"},"oxford":{"phon":"beɪ","pos":"noun","senses":[{"en":"a part of the sea, or of a large lake, partly surrounded by a wide curve of the land","cn":"（海或湖的）湾","g":"[countable]","ex":{"en":"the Bay of Bengal","cn":"孟加拉湾"}},{"en":"a marked section of ground either inside or outside a building, for example for a vehicle to park in, for storing things, etc.","cn":"分隔间（户外或室内的，用以停放车辆、存放货物等）","g":"[countable]","ex":{"en":"a parking/loading bay","cn":"停车位；装货区"}},{"en":"a curved area of a room or building that sticks out from the rest of the building","cn":"（建筑物的）突出结构","g":"[countable]"},{"en":"a horse of a dark brown colour","cn":"深棕色马；栗色马","g":"[countable]","ex":{"en":"He was riding a big bay.","cn":"他骑着一匹高大的栗色马。"}},{"en":"a deep noise, especially the noise made by dogs when hunting","cn":"（尤指猎犬捕猎时的）低沉吠声","g":"[countable]"},{"en":"a small tree with dark green leaves with a sweet smell that are used in cooking","cn":"月桂树，甜月桂（叶子可作香料）","g":"[countable]"},{"en":"the leaves of the bay tree, used in cooking as a herb","cn":"月桂叶（用作香料）","g":"[uncountable]"},{"en":"to make a long deep sound, especially while hunting","cn":"（尤指捕猎时）发出长嗥，低沉地吠叫","g":"[intransitive]","ex":{"en":"a pack of baying hounds","cn":"一群不断吠叫着的猎犬"},"pos":"verb"},{"en":"to demand something in a loud and angry way","cn":"厉声强要","g":"[intransitive]","ex":{"en":"The referee's decision left the crowd baying for blood (= threatening violence towards him).","cn":"裁判的裁决使得群众怒吼着要暴力相向。"},"pos":"verb"},{"en":"dark brown in colour","cn":"栗色的；深棕色的","ex":{"en":"a bay mare","cn":"一匹栗色的母马"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"湾；海湾","en":"A bay is a part of a coast where the land curves inwards.","ex":{"en":"...a short ferry ride across the bay.","cn":"乘渡船横渡海湾的短途旅行"}},{"pos":"N-COUNT 可数名词","cn":"（建筑物的）开间，隔间","en":"A bay is a partly enclosed area, inside or outside a building, that is used for a particular purpose.","ex":{"en":"The animals are herded into a bay, then butchered","cn":"动物们被赶到一个隔间里，然后进行宰杀。"}},{"pos":"N-COUNT 可数名词","cn":"（飞机或船只的）货舱，分隔舱","en":"On an aircraft or ship, a bay is a section that is used for carrying cargo or equipment.","ex":{"en":"...in the cargo bays of aircraft.","cn":"在飞机的货舱里"}},{"pos":"N-COUNT 可数名词","cn":"（建筑物的）凸出部分；（尤指）飘窗，凸窗","en":"A bay is an area of a room which extends beyond the main walls of a house, especially an area with a large window at the front of a house."},{"pos":"ADJ 形容词","cn":"（马）棕红色的","en":"A bay horse is reddish-brown in colour."},{"pos":"VERB 动词","cn":"大声疾呼；强烈要求","en":"If a number of people are baying for something, they are demanding something angrily, usually that someone should be punished.","ex":{"en":"The referee ignored voices baying for a penalty.","cn":"裁判对要求判罚点球的叫喊声不予理睬。"}},{"pos":"VERB 动词","cn":"（犬）连续吠；（狼）连续嚎叫","en":"If a dog or wolf bays, it makes loud, long cries.","ex":{"en":"A dog suddenly howled, baying at the moon.","cn":"一只狗突然对着月亮狂吠不止。"}},{"pos":"PHRASE 短语","cn":"使…不能靠近；防止…侵袭","en":"If you keep something or someone at bay, or hold them at bay, you prevent them from reaching, attacking, or affecting you.","ex":{"en":"Eating oranges keeps colds at bay","cn":"吃橘子可以预防感冒。"}}]},"examples":[{"en":"The referee's decision left the crowd baying for blood (= threatening violence towards him).","cn":"裁判的裁决引起群众怒吼着要暴力相向。"},{"en":"Charlotte bit her lip to hold the tears at bay.","cn":"夏洛特咬住嘴唇不让眼泪流出来。"}]},"bases":{"media":{"uk":"media/uk/bases__gb_1.mp3","us":"media/us/bases__us_1.mp3"},"collins":{"senses":[{"pos":"","cn":"（base的复数）","en":"Bases is the plural of base."},{"pos":"","cn":"（basis 的复数）","en":"Bases is the plural of basis."}]}},"bastion":{"media":{"uk":"media/uk/bastion__gb_1.mp3","us":"media/us/bastion__us_1.mp3"},"oxford":{"phon":"ˈbæstiən","pos":"noun","senses":[{"en":"a group of people or a system that protects a way of life or a belief when it seems that it may disappear","cn":"堡垒；捍卫者","lab":"formal","ex":{"en":"a bastion of male privilege","cn":"大男子主义的堡垒"}},{"en":"a place that military forces are defending","cn":"堡垒；防御工事","ex":{"en":"Singapore was the last bastion of British defences in South-East Asia.","cn":"新加坡是英国在东南亚防御的最后堡垒。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"堡垒（指固守一种生活方式等的体制或组织）","en":"If a system or organization is described as a bastion of a particular way of life, it is seen as being important and effective in defending that way of life. Bastion can be used both when you think that this way of life should be ended and when you think it should be defended.","ex":{"en":"...a town which had been a bastion of white prejudice","cn":"一度固守着白人偏见的城镇"}}]},"examples":[{"en":"a bastion of male privilege","cn":"大男子主义的堡垒"},{"en":"a bastion of freedom","cn":"捍卫自由的堡垒"}]},"bandage":{"oxford":{"phon":"ˈbændɪdʒ","pos":"noun","senses":[{"en":"a long narrow piece of cloth used for tying around a part of the body that has been hurt in order to protect or support it","cn":"绷带","ex":{"en":"She had a bandage on her arm.","cn":"她胳膊上扎着绷带。"}},{"en":"to wrap a bandage around a part of the body in order to protect it because it is injured","cn":"用绷带包扎","lab":"especially British English","ex":{"en":"Don't bandage the wound too tightly.","cn":"不要把伤口包扎得太紧。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"绷带","en":"A bandage is a long strip of cloth which is wrapped around a wounded part of someone's body to protect or support it.","ex":{"en":"We put some ointment and a bandage on his knee","cn":"我们在他的膝盖上涂了些药膏并打上了绷带。"}},{"pos":"VERB 动词","cn":"用绷带包扎","en":"If you bandage a wound or part of someone's body, you tie a bandage around it.","ex":{"en":"Apply a dressing to the wound and bandage it.","cn":"给伤口盖上敷料并用绷带包扎起来。"}}]},"media":{"uk":"media/uk/bandage__gb_1.mp3","us":"media/us/bandage__us_1.mp3","img":["media/ldoce/img/first_aid_kit.jpg"]},"examples":[{"en":"The nurse bandaged up his sprained ankle.","cn":"护士用绷带包扎他扭伤的脚踝。"}]},"battles":{"oxford":{"phon":"ˈbætl","pos":"noun","senses":[{"en":"a fight between armies, ships or planes, especially during a war; a violent fight between groups of people","cn":"战役；战斗；搏斗"},{"en":"a competition, an argument or a struggle between people or groups of people trying to win power or control","cn":"较量；争论；斗争"}]}},"bathtub":{"media":{"uk":"media/uk/bathtub__gb_1.mp3","us":"media/us/bathtub__us_1.mp3"},"oxford":{"phon":"ˈbɑːθtʌb","pos":"noun","senses":[{"en":"a large, long container that you put water in and then get into to wash your whole body","cn":"浴缸；浴盆"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"浴盆；浴缸","en":"A bathtub is a long, usually rectangular container which you fill with water and sit in to wash your body."}]}},"bankrupt":{"media":{"uk":"media/uk/bankrupt__gb_1.mp3","us":"media/us/bankrupt__us_1.mp3"},"oxford":{"phon":"ˈbæŋkrʌpt","pos":"adjective","senses":[{"en":"without enough money to pay what you owe","cn":"破产；倒闭","ex":{"en":"They went bankrupt in 2009.","cn":"他们于 2009 年破产。"}},{"en":"having absolutely nothing of any value","cn":"完全没有（有价值的东西）","lab":"formal, disapproving，，","ex":{"en":"a government bankrupt of new ideas","cn":"完全缺乏新观念的政府"}},{"en":"a person who has been judged by a court to be unable to pay his or her debts","cn":"（经法院判决的）破产者","ex":{"en":"He later became Britain’s biggest bankrupt.","cn":"后来他成为了英国最大的破产者。"},"pos":"noun"},{"en":"to make somebody bankrupt","cn":"使破产","ex":{"en":"The company was almost bankrupted by legal costs.","cn":"这家公司为律师费用所累几乎破产。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"破产的；倒闭的；资不抵债的","en":"People or organizations that go bankrupt do not have enough money to pay their debts.","ex":{"en":"If the firm cannot sell its products, it will go bankrupt","cn":"如果公司的产品卖不出去，它就会倒闭。"}},{"pos":"VERB 动词","cn":"使破产；使倒闭","en":"To bankrupt a person or organization means to make them go bankrupt.","ex":{"en":"The move to the market nearly bankrupted the firm and its director","cn":"入市几乎使公司及其董事破产。"}},{"pos":"N-COUNT 可数名词","cn":"（经法院宣告的）破产者","en":"A bankrupt is a person who has been declared bankrupt by a court of law."},{"pos":"ADJ 形容词","cn":"彻底缺乏的","en":"If you say that something is bankrupt, you are emphasizing that it lacks any value or worth.","ex":{"en":"He really thinks that European civilisation is morally bankrupt.","cn":"他确实认为欧洲文明道德沦丧。"}}]},"examples":[{"en":"The company was almost bankrupted by legal costs.","cn":"这家公司为律师费用所累几乎破产。"},{"en":"The company was declared bankrupt in the High Court.","cn":"那家公司经高等法院宣告破产了。"}]},"backpack":{"media":{"img":["media/ldoce/img/backpack.jpg","media/pic/bags_comp.jpg"],"uk":"media/uk/backpack__gb_1.mp3","us":"media/us/backpack__us_1.mp3"},"oxford":{"phon":"ˈbækpæk","pos":"noun","senses":[{"en":"a bag that you carry on your back, made of strong material and often used by people who go climbing or walking","cn":"（指登山者或徒步旅行者常用的）背包","lab":"British English also","ex":{"en":"She swung her backpack over her shoulder.","cn":"她把背包甩到背上。"}},{"en":"a piece of equipment that is carried on the back","cn":"背负式设备","ex":{"en":"a weed-sprayer backpack","cn":"背负式喷雾除草器"}},{"en":"to travel on holiday carrying your equipment and clothes in a backpack","cn":"背包旅行","ex":{"en":"They went backpacking in Spain last year.","cn":"他们去年在西班牙背包旅行。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"背包；背囊","en":"A backpack is a bag with straps that go over your shoulders, so that you can carry things on your back when you are walking or climbing."}]},"examples":[{"en":"They went backpacking in Spain last year.","cn":"他们去年背着背包在西班牙旅行。"}]},"bark":{"media":{"img":["media/pic/tree_bark_comp.jpg","media/thumb/log.jpg"],"uk":"media/uk/bark__gb_1.mp3","us":"media/us/bark__us_1.mp3"},"oxford":{"phon":"bɑːk","pos":"noun","senses":[{"en":"the outer layer of a tree","cn":"树皮","ex":{"en":"The bark peels off in summer.","cn":"树皮在夏季脱落。"}},{"en":"the short loud sound made by dogs and some other animals","cn":"（狗等的）吠声，嗥叫声","ex":{"en":"The dog gave a loud bark.","cn":"那条狗大声地吠叫。"}},{"en":"a short loud sound made by a gun or a voice","cn":"枪声；短促响亮的人声","ex":{"en":"a bark of laughter","cn":"一声大笑"}},{"en":"when a dog barks, it makes a short loud sound","cn":"（狗）吠叫","g":"[intransitive]","ex":{"en":"The dog suddenly started barking at us.","cn":"那条狗突然开始对我们汪汪叫。"},"pos":"verb"},{"en":"to give orders, ask questions, etc. in a loud, unfriendly way","cn":"厉声发令；厉声质问","g":"[transitive]","ex":{"en":"She barked out an order.","cn":"她厉声命令。"},"pos":"verb"},{"en":"to rub the skin off your knee, etc. by falling or by knocking against something","cn":"擦破（或蹭掉）…的皮","g":"[transitive]","lab":"British English","ex":{"en":"I barked my shins when I fell on the steps.","cn":"当我跌倒在台阶上时，我的小腿发出了叫声。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（犬）吠，狺狺","en":"When a dog barks, it makes a short, loud noise, once or several times.","ex":{"en":"Don't let the dogs bark","cn":"让那些狗别叫。"}},{"pos":"VERB 动词","cn":"大声嚷；吼叫；厉声叫喊","en":"If you bark at someone, you shout at them aggressively in a loud, rough voice.","ex":{"en":"I didn't mean to bark at you","cn":"我不是成心对你嚷嚷的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"树皮","en":"Bark is the tough material that covers the outside of a tree."},{"pos":"PHRASE 短语","cn":"刀子嘴，豆腐心；冷面孔，菩萨心","en":"If you say that someone's bark is worse than their bite, you mean that they seem much more unpleasant or hostile than they really are.","ex":{"en":"She can be a bit tetchy but her bark is worse than her bite.","cn":"她脾气可能有点暴躁，但她是刀子嘴，豆腐心。"}},{"pos":"","cn":"","en":"to be barking up the wrong tree→see: ;"}]},"examples":[{"en":"You're barking up the wrong tree if you're expecting us to lend you any money.","cn":"你要是指望我们借钱给你，你是走错庙门了。"},{"en":"The dog suddenly started barking at us.","cn":"那条狗突然开始对我们汪汪叫。"}]},"basics":{"media":{"uk":"media/uk/basics__gb_1.mp3","us":"media/us/basics__us_1.mp3"},"oxford":{"phon":"ˈbeɪsɪks","pos":"noun","senses":[{"en":"the most important and necessary facts, skills, ideas, etc. from which other things develop","cn":"基本因素（或原理、原则、规律等）","ex":{"en":"the basics of computer programming","cn":"计算机编程概要"}},{"en":"the simplest and most important things that people need in a particular situation","cn":"基本设施；基本需要","ex":{"en":"Some schools lack money for basics like books and pencils.","cn":"有些学校缺少资金购买书本、铅笔之类的基本用具。"}}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"基础；基本内容；基本原则","en":"The basics of something are its simplest, most important elements, ideas, or principles, in contrast to more complicated or detailed ones.","ex":{"en":"They will concentrate on teaching the basics of reading, writing and arithmetic","cn":"他们将集中教授阅读、写作和算术基础知识。"}},{"pos":"N-PLURAL 复数名词","cn":"必需品；基本需求","en":"Basics are things such as simple food, clothes, or equipment that people need in order to live or to deal with a particular situation.","ex":{"en":"...supplies of basics such as bread and milk.","cn":"面包和牛奶等必需品的供应"}},{"pos":"PHRASE 短语","cn":"注重基础；回到根本","en":"If you talk about getting back to basics, you are suggesting that people have become too concerned with complicated details or new theories, and that they should concentrate on simple, important ideas or activities.","ex":{"en":"Nurtured carefully, the business can once again get back to basics.","cn":"只要用心经营，公司可以重回正轨。"}}]},"examples":[{"en":"Some schools lack money for basics like books and pencils.","cn":"有些学校缺少资金购买书本、铅笔之类的基本工具。"},{"en":"the basics of computer programming","cn":"计算机编程概要"}]},"bars":{"oxford":{"phon":"bɑː(r)","pos":"noun","senses":[{"en":"a place where you can buy and drink alcoholic and other drinks","cn":"酒吧"},{"en":"a long wide wooden surface where drinks, etc. are served （","cn":"出售饮料等的）柜台；吧台"}]}},"battened":{"oxford":{"phon":"ˈbætn","pos":"noun","senses":[{"en":"( technical","cn":"术语 ) a long strip of wood that is used to keep other building materials in place on a wall or roof 板条，压条，挂瓦条（用于固定其他建筑材料）"},{"en":"to prepare yourself for a period of difficulty or trouble","cn":"做好迎接困难的准备"}]}},"batteries":{"oxford":{"phon":"ˈbætri","pos":"noun","senses":[{"en":"a device that is placed inside a car engine, clock, radio, etc. and that produces the electricity that makes it work","cn":"电池"},{"en":"a large number of things or people of the same type","cn":"一系列；一批；一群"}]},"media":{"img":["media/ldoce/img/batteries.jpg"]}},"barriers":{"oxford":{"phon":"ˈbæriə(r)","pos":"noun","senses":[{"en":"an object like a fence that prevents people from moving forward from one place to another","cn":"屏障；障碍物"},{"en":"a problem, rule or situation that prevents sb from doing sth, or that makes sth impossible","cn":"障碍；阻力；关卡"}]}},"banning":{"oxford":{"phon":"bæn","pos":"verb","senses":[{"en":"to decide or say officially that sth is not allowed","cn":"明令禁止；取缔"},{"en":"to order sb not to do sth, go somewhere, etc., especially officially","cn":"禁止（某人）做某事（或去某处等）"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ban_n0205.mp3","us":"media/ldoce/hwd/ame/5/ban1.mp3"}},"balancing":{"oxford":{"phon":"ˈbæləns","pos":"noun","senses":[{"en":"a situation in which different things exist in equal, correct or good amounts","cn":"均衡；平衡；均势"},{"en":"the ability to keep steady with an equal amount of weight on each side of the body","cn":"平衡能力"}]}},"barnacles":{"oxford":{"phon":"ˈbɑːnəkl","pos":"noun","senses":[{"en":"a small shellfish that attaches itself to objects underwater, for example to rocks and the bottoms of ships","cn":"藤壶（小甲壳动物，附着于水下岩石或船底等）"}]}},"banks":{"oxford":{"phon":"bæŋk","pos":"noun","senses":[{"en":"an organization that provides various financial services, for example keeping or lending money","cn":"银行"},{"en":"a supply of money or things that are used as money in some games, especially those in which gambling is involved （","cn":"尤指赌博中的）筹码；赌本"}]}},"bakeries":{"oxford":{"phon":"ˈbeɪkəri","pos":"noun","senses":[{"en":"a place where bread and cakes are made and/or sold","cn":"面包（糕饼）店；面包（糕饼）烘房；面包厂"}]}},"backed":{"oxford":{"phon":"bæk","pos":"noun","senses":[{"en":"the part of the human body that is on the opposite side to the chest, between the neck and the tops of the legs; the part of an animal's body that corresponds to this （","cn":"人体或动物的）背部，背；腰背"},{"en":"the row of bones in the middle of the back","cn":"脊柱；脊梁骨"}]}},"babies":{"oxford":{"phon":"ˈbeɪbi","pos":"noun","senses":[{"en":"a very young child or animal","cn":"婴儿；动物幼崽"},{"en":"( informal ) the youngest member of a family or group （","cn":"家庭或团体中）最年幼的成员"}]}},"bamboos":{"oxford":{"phon":"ˌbæmˈbuː","pos":"noun","senses":[{"en":"a tall tropical plant that is a member of the grass family and has hard hollow stems that are used for making furniture, poles, etc.","cn":"竹；竹子"}]}},"backwaters":{"oxford":{"phon":"ˈbækwɔːtə(r)","pos":"noun","senses":[{"en":"a part of a river away from the main part, where the water only moves slowly （","cn":"河流的）滞水，壅水，回水"},{"en":"( often disapproving ) a place that is away from the places where most things happen, and is therefore not affected by events, progress, new ideas, etc.","cn":"与世隔绝的地区；落后地区"}]}},"bags":{"oxford":{"phon":"bæɡ","pos":"noun","senses":[{"en":"( often in compounds","cn":"常构成复合词 ) a container made of paper or plastic, that opens at the top, used especially in shops/stores （尤指商店用的）纸袋，塑料袋"},{"en":"a strong container made from cloth, plastic, leather, etc., usually with one or two handles, used to carry things in when shopping or travelling","cn":"手提包；旅行袋"}]},"media":{"img":["media/pic/bags_comp.jpg"]}},"bands":{"oxford":{"phon":"bænd","pos":"noun","senses":[{"en":"a small group of musicians who play popular music together, often with a singer or singers","cn":"流行音乐乐队"},{"en":"a group of musicians who play brass and percussion instruments","cn":"管乐队；鼓号乐队"}]}},"baked":{"oxford":{"phon":"beɪk","pos":"verb","senses":[{"en":"to cook food in an oven without extra fat or liquid; to be cooked in this way （","cn":"在烤炉里）烘烤；焙"},{"en":"to become or to make sth become hard by heating （","cn":"将某物）烤硬"}]}},"barber's":{"oxford":{"phon":"ˈbɑːbəʃɒp","pos":"noun","senses":[{"en":"a place where a barber works","cn":"理发店"},{"en":"a type of light music for four parts sung by men, without instruments","cn":"理发店四重唱（一种无乐器伴奏的男声四重唱）"}]}},"bandits":{"oxford":{"phon":"ˈbændɪt","pos":"noun","senses":[{"en":"a member of an armed group of thieves who attack travellers","cn":"土匪"}]}},"barrister":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（英格兰和威尔士地区有资格在高等法院出庭的）大律师，讼务律师","en":"In England and Wales, a barrister is a lawyer who represents clients in the higher courts of law. →see usage note at:"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to advise people about laws, write formal agreements, or represent people in court","cn":""},{"en":"a lawyer. Attorney sounds more formal than lawyer","cn":""},{"en":"a type of lawyer in Britain who gives legal advice, prepares the documents when property is bought or sold, and defends people, especially in the lower courts of law","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The Brits and Canadians prefer to say barrister instead of \"lawyer,\" but they mean the same thing. A barrister is a person who goes to court on behalf of the defense or the prosecution."}]},"collocations":{"phrases":["ADJ. brilliant, good, leading, successful, top | practising, qualified | junior, trainee | defence/defending, prosecuting/prosecution","PREP. ~ for the barrister for the ferry company • Note at PROFESSIONAL (for verbs)"]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdebarrister.mp3","us":"media/ldoce/hwd/ame/b/barrister.mp3"},"oxford":{"phon":"ˈbærɪstə(r)","pos":"noun","senses":[{"en":"a lawyer in the UK who has the right to argue cases in the higher courts of law","cn":"出庭律师，大律师，辩护律师（在英国有资格出席高等法庭进行辩护）","lab":"North American English","ex":{"en":"the barrister for the ferry company","cn":"代表渡轮公司的辩护律师"}}]}},"battered":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"破旧的；陈旧的","en":"Something that is battered is old and in poor condition because it has been used a lot.","ex":{"en":"He drove up in a battered old car.","cn":"他开着一辆又老又破的旧车。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"furniture and other structures that are rickety are in such bad condition that they look as if they would break if you tried to use them","cn":""},{"en":"something that is battered is old and in bad condition because it has been used a lot and treated roughly","cn":""},{"en":"if something is falling apart , it is gradually breaking into pieces, because it is old or badly made","cn":""}]},"collocations":{"phrases":["VERBS be, feel, look | become, get","ADV. badly, very | a bit, a little, rather, slightly | emotionally She felt emotionally battered.","PHRASES battered old She wore a battered old robe."]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdebattered.mp3","us":"media/ldoce/hwd/ame/f/laadbattered.mp3"},"examples":[{"en":"The child had suffered what has become known as ‘battered baby syndrome’.","cn":"那孩子患的是后来人称“受虐儿童综合征”的疾病。"},{"en":"Rockets and shells continued to hit the battered port.","cn":"火箭和炮弹继续袭击已遭受重创的港口。"}],"oxford":{"phon":"ˈbætəd","pos":"adjective","senses":[{"en":"old, used a lot, and not in very good condition","cn":"破旧不堪的","ex":{"en":"a battered old car","cn":"一辆破旧的老爷车"}},{"en":"attacked violently or repeatedly and injured","cn":"受到暴力伤害的；遭到长期虐待的","ex":{"en":"a battered spouse/wife","cn":"受虐待的配偶/妻子"}},{"en":"attacked and badly damaged by weapons or by bad weather","cn":"受到（炮火或恶劣天气）重创的","g":"[usually before noun]","ex":{"en":"Rockets and shells continued to hit the battered port.","cn":"火箭和炮弹继续袭击已遭重创的港口。"}},{"en":"covered in batter and fried","cn":"裹面糊油炸的","g":"[usually before noun]","ex":{"en":"battered fish","cn":"裹面糊油炸鱼"}}]}},"banquet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"宴会；盛宴","en":"A banquet is a grand formal dinner.","ex":{"en":"Last night he attended a state banquet at Buckingham Palace.","cn":"昨晚他出席了在白金汉宫举行的国宴。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a formal meal in your home when you invite friends or guests","cn":""},{"en":"a formal evening meal for a large number of people, especially in a public place such as a hotel","cn":""},{"en":"a special formal meal with a lot of very good food and a large number of people, especially important people, which usually takes place on a special public occasion","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"It’s customary to celebrate Thanksgiving with a banquet , or elaborate feast — along with the requisite bickering between family members."}]},"collocations":{"phrases":["ADJ. grand, great, lavish, sumptuous | veritable (humorous) The meal that followed was a veritable banquet. | five-course, six-course, etc. ","VERB + BANQUET give, hold | arrange, prepare (for) The kitchens are preparing for a lavish banquet. | attend The Lord Mayor attended a state","PREP. at a/the ~ He was suddenly taken ill at a banquet given in his honour. | ~ for a banquet for the president"]},"media":{"uk":"media/ldoce/hwd/bre/2/banquet0205.mp3","us":"media/ldoce/hwd/ame/4/banquet1.mp3"},"examples":[{"en":"a state banquet in honour of the visiting President","cn":"为来访总统举办的国宴"},{"en":"a state banquet (= one attended by heads of government and other important people )","cn":"国宴"}],"oxford":{"phon":"ˈbæŋkwɪt","pos":"noun","senses":[{"en":"a formal meal for a large number of people, usually for a special occasion, at which speeches are often made","cn":"宴会；盛宴","ex":{"en":"A state banquet was held in honour of the visiting president.","cn":"为来访总统举办了国宴。"}},{"en":"a large impressive meal","cn":"筵席","ex":{"en":"The meal that followed was a veritable banquet.","cn":"随后摆上的饭菜俨然是一桌宴席。"}}]}},"baron":{"collins":{"senses":[{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"男爵（贵族爵位中最低的一级）","en":"A baron is a man who is a member of the lowest rank of the nobility.","ex":{"en":"...their stepfather, Baron Michael Distemple.","cn":"他们的继父，迈克尔·迪斯腾普尔男爵"}},{"pos":"N-COUNT 可数名词","cn":"巨头；大王；大亨","en":"You can use baron to refer to someone who controls a large amount of a particular industry or activity and who is therefore extremely powerful.","ex":{"en":"...the battle against the drug barons.","cn":"打击毒枭之战"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a man who is a member of a low rank of the British nobility or of a rank of European nobility","cn":"男爵〔英国爵位较低的贵族或欧洲贵族的一个等级〕"},{"en":"a businessman with a lot of power or influence 〔","cn":"工商业〕巨头﹐大王"}]},"vocab":{"pos":"n","senses":[{"en":"A baron is a nobleman — a member of the aristocracy. Barons are also important, powerful businessmen with huge influence over their industries. In Britain, a baron is called “Lord,” but in the States, we call them “rich.”"}]},"collocations":{"phrases":["ADJ. media, newspaper, press | cocaine, drug, oil the oil barons of Texas | robber"]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41baron.mp3","us":"media/ldoce/hwd/ame/9/barren.mp3"},"examples":[{"en":"a press baron","cn":"报业大王"},{"en":"drug barons","cn":"毒枭"}],"oxford":{"phon":"ˈbærən","pos":"noun","senses":[{"en":"a nobleman of the lowest rank. In the UK, barons use the title Lord; in other countries they use the title Baron.","cn":"男爵（贵族中的最末一等。英国男爵头衔为 Lord，其他国家为 Baron）"},{"en":"a person who owns or controls a large part of a particular industry","cn":"工商业巨头","ex":{"en":"a press baron","cn":"报业大王"}}]}},"bankruptcy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"破产；倒闭","en":"Bankruptcy is the state of being bankrupt.","ex":{"en":"It is the second airline in two months to file for bankruptcy","cn":"这是两个月内第二家申请破产的航空公司。"}},{"pos":"N-COUNT 可数名词","cn":"破产事件；倒闭事件","en":"A bankruptcy is an instance of an organization or person going bankrupt.","ex":{"en":"The number of corporate bankruptcies climbed in August.","cn":"8月份企业破产数字攀升。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"彻底；缺乏","en":"If you refer to something's bankruptcy, you are emphasizing that it is completely lacking in value or worth.","ex":{"en":"The massacre laid bare the moral bankruptcy of the regime.","cn":"大屠杀使该政权的道德沦丧暴露无遗。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the state of being unable to pay your debts","cn":"破产﹔倒闭"},{"en":"a total lack of a particular good quality 〔","cn":"某种美德的〕欠缺，沦丧"}]},"vocab":{"pos":"n","senses":[{"en":"Bankruptcy is a state of being bankrupt, or having no money to pay back debts that you owe."}]},"collocations":{"phrases":["ADJ. personal","VERB + BANKRUPTCY face Small travel operators are facing bankruptcy. | be close to, be on the brink/verge of | be driven/forced/thrown into,","BANKRUPTCY + NOUN order, proceedings The defendant has a bankruptcy order against him.","PHRASES the threat of bankruptcy"]},"media":{"uk":"media/ldoce/hwd/bre/1/bankruptcy0205.mp3","us":"media/ldoce/hwd/ame/0/bankruptcy.mp3"},"examples":[{"en":"The company filed for bankruptcy (= asked to be officially bankrupt ) in 2009.","cn":"这家公司于 2009 年提交了破产申请。"},{"en":"There could be further bankruptcies among small farmers.","cn":"小农场主中可能还会有人破产。"}],"oxford":{"phon":"ˈbæŋkrʌptsi","pos":"noun","senses":[{"en":"the state of being bankrupt","cn":"破产","lab":"North American English","ex":{"en":"The company filed for bankruptcy (= asked to be officially bankrupt) in 2009.","cn":"这家公司于 2009 年提交了破产申请。"}}]}},"ballet":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"芭蕾舞","en":"Ballet is a type of very skilled and artistic dancing with carefully planned movements.","ex":{"en":"I trained as a ballet dancer","cn":"我受过芭蕾舞训练。"}},{"pos":"N-COUNT 可数名词","cn":"芭蕾舞剧；芭蕾舞段","en":"A ballet is an artistic work that is performed by ballet dancers.","ex":{"en":"The performance will include the premiere of three new ballets.","cn":"三段新编芭蕾舞将在演出中首演。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a performance in which dancing and music tell a story without any speaking","cn":"芭蕾舞剧﹔芭蕾舞表演"},{"en":"this type of dancing","cn":"芭蕾舞"},{"en":"a group of ballet dancers who work together","cn":"芭蕾舞团"}]},"vocab":{"pos":"n","senses":[{"en":"Ballet is a form of dance that uses scenery, music, and the movements of the dancers to tell a story. Learning classical ballet takes years of training."}]},"collocations":{"phrases":["ADJ. classical, modern","VERB + BALLET study He's studying classical ballet.","BALLET + NOUN music | dancer | company | shoe | class, lesson, school | teacher 2 performance of a ballet","ADJ. classical, modern, romantic","VERB + BALLET compose, write | choreograph • Note at PERFORMANCE (for more verbs)"]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdeballet.mp3","us":"media/ldoce/hwd/ame/9/ballet.mp3","img":["media/ldoce/img/ballet.jpg"]},"examples":[{"en":"‘Swan Lake’ is one of the great classical ballets. 《","cn":"天鹅湖》是一部伟大的古典芭蕾舞剧。"},{"en":"She wants to be a ballet dancer.","cn":"她想当芭蕾舞演员。"}],"oxford":{"phon":"ˈbæleɪ","pos":"noun","senses":[{"en":"a style of dancing that tells a dramatic story with music but no talking or singing","cn":"芭蕾舞","g":"[uncountable]","ex":{"en":"She wants to be a ballet dancer.","cn":"她想当芭蕾舞演员。"}},{"en":"a story or work of art performed by a group of ballet dancers","cn":"芭蕾舞剧","g":"[countable]","ex":{"en":"‘Swan Lake’ is one of the great classical ballets.","cn":"《天鹅湖》是一部伟大的古典芭蕾舞剧。"}},{"en":"a group of dancers who work and perform ballet together","cn":"芭蕾舞团","g":"[countable + singular or plural verb]","ex":{"en":"members of the Royal Ballet","cn":"皇家芭蕾舞团成员"}}]}},"bathroom":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"浴室；盥洗室","en":"A bathroom is a room in a house that contains a bath or shower, a washbasin, and sometimes a toilet."},{"pos":"N-SING 单数名词","cn":"洗手间；厕所","en":"A bathroom is a room in a house or public building that contains a toilet.","ex":{"en":"She had gone in to use the bathroom.","cn":"她去洗手间了。"}},{"pos":"PHRASE 短语","cn":"去洗手间；上厕所","en":"People say that they are going to the bathroom when they want to say that they are going to use the toilet.","ex":{"en":"Although he had been treated with antibiotics, he went to the bathroom repeatedly.","cn":"虽然他已经服用了抗生素，但他还是不停地上厕所。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a room with a toilet in it, in someone’s house or in a public place","cn":""},{"en":"a room with a toilet in it, in someone’s house. In British English, bathroom is used especially when you want to be polite. In American English, it is the usual word to use","cn":""},{"en":"a room in a public place that has one or more toilets in it","cn":""}]},"collocations":{"phrases":["ADJ. steamy | large, spacious | tiny | luxurious, luxury | fitted | tiled | adjoining, en suite | communal, shared | private | downstairs, u","VERB + BATHROOM go to, use (= go to the toilet)","BATHROOM + NOUN cabinet, cupboard | accessories, equipment, fittings, suite | mirror | scales I weigh myself on the bathroom scales every da"]},"media":{"uk":"media/ldoce/hwd/bre/0/bathroom0205.mp3","us":"media/ldoce/hwd/ame/7/bathroom.mp3","img":["media/thumb/bathroom.jpg"]},"examples":[{"en":"Go and wash your hands in the bathroom.","cn":"到盥洗室洗手去。"},{"en":"I have to go to the bathroom (= use the toilet).","cn":"我得上洗手间。"}],"oxford":{"phon":"ˈbɑːθruːm","pos":"noun","senses":[{"en":"a room in which there is a bath, a washbasin and often a toilet","cn":"浴室","ex":{"en":"Go and wash your hands in the bathroom.","cn":"到盥洗室洗手去。"}},{"en":"a room in which there is a toilet, a sink and sometimes a bath or shower","cn":"洗手间；卫生间","lab":"North American English","ex":{"en":"I have to go to the bathroom (= use the toilet).","cn":"我得上洗手间。"}}]}},"bare":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"赤裸的；不穿衣服的","en":"If a part of your body is bare, it is not covered by any clothing.","ex":{"en":"She was wearing only a thin robe over a flimsy nightdress, and her feet were bare","cn":"她只在薄如蝉翼的睡衣外套了一件薄睡袍，而且光着脚。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无遮盖的；未加装饰的","en":"A bare surface is not covered or decorated with anything.","ex":{"en":"They would have liked bare wooden floors throughout the house.","cn":"他们本想在整个房间的木地板上都不铺地毯的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"没有叶子的；光秃秃的","en":"If a tree or a branch is bare, it has no leaves on it.","ex":{"en":"...an old, twisted tree, its bark shaggy, many of its limbs brittle and bare.","cn":"一棵虬枝盘绕的古树，树皮粗糙，很多枝杈光秃秃的，一折就断"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"空的","en":"If a room, cupboard, or shelf is bare, it is empty.","ex":{"en":"His fridge was bare apart from three very withered tomatoes","cn":"除了三个蔫巴巴的西红柿，他的冰箱里什么也没有。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"光秃秃的；寸草不生的","en":"An area of ground that is bare has no plants growing on it.","ex":{"en":"That's probably the most bare, bleak, barren and inhospitable island I've ever seen.","cn":"那可能是我见过的最荒凉的岛屿，荒无人烟，寸草不生。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（事实、细节等）最基本的，最重要的","en":"If someone gives you the bare facts or the barest details of something, they tell you only the most basic and important things.","ex":{"en":"Newspaper reporters were given nothing but the bare facts by the Superintendent in charge of the investigation.","cn":"报社的记者们从负责这起调查的督察那里得到的只是一些最基本的情况。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"最少的；最低限度的；勉强的","en":"If you talk about the bare minimum or the bare essentials, you mean the very least that is necessary.","ex":{"en":"The army would try to hold the western desert with a bare minimum of forces","cn":"军队会用尽可能少的兵力扼守西部的沙漠。"}},{"pos":"ADJ 形容词","cn":"仅有的（强调数量少）","en":"Bare is used in front of an amount to emphasize how small it is.","ex":{"en":"Sales are growing for premium wines, but at a bare 2 percent a year.","cn":"高档酒的销量正在增长，但年增长率只有2％。"}},{"pos":"VERB 动词","cn":"使暴露；露出","en":"If you bare something, you uncover it and show it.","ex":{"en":"Walsh bared his teeth in a grin","cn":"沃尔什露齿一笑。"}},{"pos":"","cn":"","en":"bare bones→see: ;"},{"pos":"PHRASE 短语","cn":"徒手；赤手空拳","en":"If someone does something with their bare hands, they do it without using any weapons or tools.","ex":{"en":"Police believe the killer punched her to death with his bare hands","cn":"警方认为她是被凶手活活用拳头打死的。"}},{"pos":"PHRASE 短语","cn":"使显露出来；使暴露","en":"If you lay something bare, you uncover it completely so that it can then be seen.","ex":{"en":"The clearing out of disused workshops laid bare thousands of Italianate glazed tiles.","cn":"清理废弃的车间时发现了成千上万块意大利风格的釉面砖。"}},{"pos":"PHRASE 短语","cn":"揭露；揭发；使暴露","en":"If you lay bare something or someone, you reveal or expose them.","ex":{"en":"No one wants to expose themselves, lay their feelings bare.","cn":"没有人想自我剖白，将自己的情感公之于众。"}},{"pos":"PHRASE 短语","cn":"敞开心扉；倾诉衷肠","en":"If you bare your soul, you tell someone your most secret thoughts and feelings.","ex":{"en":"Few men would have bared their soul to a woman as he had.","cn":"很少有男人能像他一样对一个女人敞开心扉。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not wearing any clothes or not covered by clothes – used especially when this seems rather shocking","cn":""},{"en":"to not be wearing any clothes. This phrase is very commonly used in everyday English instead of saying that someone is naked","cn":""},{"en":"used about feet, legs, arms etc that are not covered by clothes","cn":""}]},"vocab":{"pos":"1 adj v 2 adj 3 adj ","senses":[{"en":"When you kick off your shoes to walk on the beach, you are enjoying the feeling of your bare feet in the warm sand. The adjective bare describes something or someone that is naked or unclothed."}]},"collocations":{"phrases":["VERBS be He was standing there, completely bare!","ADV. completely 2 not containing/covered by anything","VERBS be, look | remain | leave sth You shouldn't have left the wires bare. | lay sth, strip sth The earth had been laid bare. The walls hav","ADV. very | completely, quite The room was completely bare. | almost, rather | strangely The room looked strangely bare without the furnitur","PREP. of The house was almost bare of furniture."]},"media":{"uk":"media/ldoce/hwd/bre/1/bare_v0205.mp3","us":"media/ldoce/hwd/ame/4/bare1.mp3"},"examples":[{"en":"He did the bare minimum of work but still passed the exam.","cn":"他只花了最少的工夫，却仍然通过了考试。"},{"en":"She gave me only the bare facts of the case.","cn":"她只给我介绍了这个案件的一些基本资料。"}],"oxford":{"phon":"beə(r)","pos":"adjective","senses":[{"en":"not covered by any clothes","cn":"裸体的；裸露的","ex":{"en":"She likes to walk around in bare feet.","cn":"她喜欢光着脚走来走去。"}},{"en":"not covered with leaves; without plants or trees","cn":"（树木）光秃秃的；（土地）荒芜的","ex":{"en":"The winter sun filtered through the bare branches of the trees.","cn":"冬日的阳光透过树木光秃秃的枝桠。"}},{"en":"not covered with or protected by anything","cn":"无遮盖的；没有保护的","ex":{"en":"bare wooden floorboards","cn":"未铺地毯的木地板"}},{"en":"empty","cn":"空的；空空如也的","ex":{"en":"The fridge was completely bare.","cn":"电冰箱里什么也没有。"}},{"en":"just enough; the most basic or simple","cn":"仅够的；最基本的；最简单的","g":"[only before noun]","ex":{"en":"The family was short of even the bare necessities of life.","cn":"那家人甚至没有最起码的生活所需。"}},{"en":"to remove something that covers something else, especially from part of the body","cn":"揭开（遮盖物）；脱掉（衣服）","ex":{"en":"She was paid several thousand dollars to bare all (= take all her clothes off) for the magazine.","cn":"她为那本杂志拍裸照获得数千美元报酬。"},"pos":"verb"},{"en":"very","cn":"很；非常","ex":{"en":"The party on Saturday was bare good!","cn":"星期六的聚会棒极了！"},"pos":"adverb"}]}},"baritone":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"男中音歌手；男中音歌唱家","en":"In music, a baritone is a man with a fairly deep singing voice that is lower than that of a tenor but higher than that of a bass.","ex":{"en":"...the young American baritone Monte Pederson.","cn":"年轻的美国男中音歌唱家蒙特·佩德森"}},{"pos":"N-SING 单数名词","cn":"低沉悦耳的声音","en":"If a man has a baritone speaking voice, his voice is low and pleasant to listen to.","ex":{"en":"...a baritone voice","cn":"低沉悦耳的嗓音"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a male singing voice that is lower than a tenor but higher than a bass , or a man with a voice like this","cn":"男中音（歌手）"},{"en":"the part of a musical work that is written for a baritone voice or instrument 〔","cn":"音乐作品中的〕男中音部"},{"en":"a baritone voice or instrument is lower than a tenor but higher than a bass 〔","cn":"声音〕男中音的；〔乐器〕上低音的"}]},"collocations":{"phrases":["ADJ. lusty, melodious, pleasant, rich","BARITONE + NOUN voice | solo","PREP. in a &hellip; ~ He sang in his rich baritone"]},"media":{"uk":"media/ldoce/hwd/bre/5/baritone_n0205.mp3","us":"media/ldoce/hwd/ame/8/baritone.mp3"},"examples":[{"en":"Can you sing the baritone?","cn":"你唱男中音好吗？"},{"en":"a famous baritone","cn":"著名男中音"}],"oxford":{"phon":"ˈbærɪtəʊn","pos":"adjective","senses":[{"en":"with a range between tenor and bass","cn":"男中音（歌手）的","ex":{"en":"a baritone voice","cn":"男中音 [上低音] 的声音"}},{"en":"second lowest in pitch in its family","cn":"上低音的","ex":{"en":"a baritone sax","cn":"上低音萨克斯"}},{"en":"a man’s singing voice with a range between tenor and bass; a man with a baritone voice","cn":"男中音；男中音歌手","ex":{"en":"He sang in his rich baritone","cn":"他以浑厚的男中音演唱。"},"pos":"noun"},{"en":"a musical instrument that is second lowest in pitch in its family","cn":"上低音号","pos":"noun"}]}},"bassoon":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"低音管；巴松管","en":"A bassoon is a large musical instrument that is shaped like a tube and played by blowing into a curved metal pipe."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a musical instrument like a very long wooden tube, that produces a low sound. You hold it upright and play it by blowing into a thin curved metal pipe.","cn":"巴松管﹐低音管﹐大管"}]},"media":{"uk":"media/ldoce/hwd/bre/7/bassoon0205.mp3","us":"media/ldoce/hwd/ame/9/bassoon.mp3","img":["media/thumb/bassoon.jpg"]},"oxford":{"phon":"bəˈsuːn","pos":"noun","senses":[{"en":"a musical instrument of the woodwind group. It is like a large wooden tube in shape with a double reed that you blow into, and produces notes with a low sound.","cn":"大管；巴松"}]}},"barren":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"荒芜的；缺少植被的；不毛的","en":"A barren landscape is dry and bare, and has very few plants and no trees.","ex":{"en":"...the country's landscape of high barren mountains.","cn":"该国草木稀少的高山地貌"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"贫瘠的","en":"Barren land consists of soil that is so poor that plants cannot grow in it.","ex":{"en":"He also wants to use the water to irrigate barren desert land.","cn":"他也想用这些水灌溉荒漠。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无用的；无益的；无效果的","en":"If you describe something such as an activity or a period of your life as barren, you mean that you achieve no success during it or that it has no useful results.","ex":{"en":"...politics that are banal and barren of purpose.","cn":"陈腐盲目的政见"}},{"pos":"ADJ 形容词","cn":"空的；没有东西的","en":"If you describe a room or a place as barren, you do not like it because it has almost no furniture or other objects in it.","ex":{"en":"The room was austere, nearly barren of furniture or decoration","cn":"房间非常简朴，几乎没有任何家具和装饰。"}},{"pos":"ADJ 形容词","cn":"不育的；不孕的","en":"A barren woman or female animal is unable to have babies.","ex":{"en":"He prayed that his barren wife would one day have a child.","cn":"他祈祷自己不孕的妻子有朝一日能怀上宝宝。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"soil or land that is poor does not contain many substances that help plants to grow","cn":""},{"en":"land that is barren is useless for growing crops on, and is usually dry and empty","cn":""},{"en":"land or soil that is barren has no plants growing on it","cn":"贫瘠的﹐荒芜的"}]},"vocab":{"pos":"1 adj n 2 adj","senses":[{"en":"Drive through a forest that's just been destroyed by a fire, and you'll get an idea of what barren means — stripped of vegetation and devoid of life."}]},"collocations":{"phrases":["VERBS appear, be | become | make sth The years of growing cotton had made the land completely barren.","ADV. completely, entirely, utterly | almost | largely"]},"media":{"uk":"media/ldoce/hwd/bre/7/barren0205.mp3","us":"media/ldoce/hwd/ame/9/barren.mp3"},"examples":[{"en":"The team will come through this barren patch and start to win again.","cn":"这个队将会在经历这段低潮时期之后再创佳绩。"},{"en":"a barren landscape (= one that is empty, with few plants)","cn":"寸草不生的荒凉景色"}],"oxford":{"phon":"ˈbærən","pos":"adjective","senses":[{"en":"not good enough for plants to grow on it","cn":"贫瘠的；不毛的","ex":{"en":"a barren desert","cn":"不毛的沙漠"}},{"en":"not producing fruit or seeds","cn":"不结果实的"},{"en":"not able to have babies","cn":"不能生育的","lab":"old use"},{"en":"not able to produce young animals","cn":"不育的；不孕的","lab":"formal"},{"en":"not producing anything useful or successful","cn":"无益的；无效果的","g":"[usually before noun]","ex":{"en":"The team will come through this barren patch and start to win again.","cn":"这个队将会在经历这段低潮时期之后再创佳绩。"}}]}},"barge":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指运河上载货用的）大型平底船，驳船","en":"A barge is a long, narrow boat with a flat bottom. Barges are used for carrying heavy loads, especially on canals.","ex":{"en":"Carrying goods by train costs nearly three times more than carrying them by barge.","cn":"通过铁路运货的成本比驳船运货成本高出近3倍。"}},{"pos":"VERB 动词","cn":"硬闯；闯入","en":"If you barge into a place or barge through it, you rush or push into it in a rough and rude way.","ex":{"en":"Students tried to barge into the secretariat buildings","cn":"学生们试图闯进秘书处的办公大楼。"}},{"pos":"VERB 动词","cn":"鲁莽地撞；大力冲撞","en":"If you barge into someone or barge past them, you bump against them roughly and rudely.","ex":{"en":"He would barge into them and kick them in the shins","cn":"他会向他们冲过去，踹他们的小腿肚子。"}},{"pos":"","cn":"","en":"相关词组：barge in"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large boat with a sail, used for pleasure or sport","cn":""},{"en":"a boat that uses one or more sails","cn":""},{"en":"a small boat that you move through the water with oars","cn":""}]},"collocations":{"phrases":["ADJ. brightly painted | canal, river | sailing | cargo, coal, etc.","VERB + BARGE tow | load (sth into), unload (sth from) | moor, tie up","BARGE + VERB be laden/loaded with sth, carry sth","PREP. by ~ I travelled by barge. | in/on a/the ~ cruising the canals of France in a barge"]},"media":{"uk":"media/ldoce/hwd/bre/2/barge_v0205.mp3","us":"media/ldoce/hwd/ame/1/barge1.mp3"},"examples":[{"en":"He barged past me to get to the bar.","cn":"他经过我的身边向卖酒的柜台硬挤过去。"},{"en":"I hope you don't mind me barging in like this.","cn":"希望你不介意我如此冒昧打岔。"}],"oxford":{"phon":"bɑːdʒ","pos":"noun","senses":[{"en":"a large boat with a flat bottom, used for carrying goods and people on canals and rivers","cn":"驳船（运河、河流上运载客货的大型平底船）","ex":{"en":"They travel by barge.","cn":"他们乘游船旅行。"}},{"en":"to move in a rough and careless way, pushing people out of the way or crashing into them","cn":"冲撞；乱闯","ex":{"en":"He barged past me to get to the bar.","cn":"他硬从我的身边向吧台挤过去。"},"pos":"verb"}]}},"balding":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"开始变秃的；正在谢顶的","en":"Someone who is balding is beginning to lose the hair on the top of their head.","ex":{"en":"He wore a straw hat to keep his balding head from getting sunburned.","cn":"他戴了顶草帽，以免正在谢顶的脑袋被太阳晒到。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a balding man is losing the hair on his head 〔","cn":"男子〕渐渐变秃的"}]},"vocab":{"pos":"adj","senses":[{"en":"If your dad is losing his hair, you can describe him as balding — although it may hurt his feelings if he's sensitive about his looks."}]},"collocations":{"phrases":["VERBS be He's in his twenties but already balding.","ADV. already, prematurely"]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdebalding.mp3","us":"media/ldoce/hwd/ame/7/balding.mp3"},"examples":[{"en":"a short balding man with glasses","cn":"一个戴眼镜的有些秃顶的小个子男人"},{"en":"a balding man in his mid-thirties","cn":"一个开始谢顶的三十五六岁的男人"}],"oxford":{"phon":"ˈbɔːldɪŋ","pos":"adjective","senses":[{"en":"starting to lose the hair on your head","cn":"开始脱发的；变秃的","ex":{"en":"a short balding man with glasses","cn":"一个戴眼镜的有些秃顶的小个子男人"}}]}},"barricade":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"路障；街垒","en":"A barricade is a line of vehicles or other objects placed across a road or open space to stop people getting past, for example during street fighting or as a protest.","ex":{"en":"Large areas of the city have been closed off by barricades set up by the demonstrators.","cn":"城市中大片地区被示威者设立的路障封锁了。"}},{"pos":"VERB 动词","cn":"在…设路障；阻碍；阻塞","en":"If you barricade something such as a road or an entrance, you place a barricade or barrier across it, usually to stop someone getting in.","ex":{"en":"The rioters barricaded streets with piles of blazing tyres","cn":"暴徒用一堆堆燃烧的轮胎在大街上筑起了路障。"}},{"pos":"VERB 动词","cn":"把…隔离；堵住","en":"If you barricade yourself inside a room or building, you place barriers across the door or entrance so that other people cannot get in.","ex":{"en":"The students have barricaded themselves into their dormitory building","cn":"学生们把自己关在了宿舍楼里。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an upright flat structure made of stone or brick, that divides one area from another or surrounds an area","cn":""},{"en":"a structure made of wood, metal etc that surrounds a piece of land","cn":""},{"en":"a metal fence that is made of a series of upright bars","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A barricade is anything that prevents people or vehicles from getting through. Construction workers often barricade a street to block traffic."}]},"collocations":{"phrases":["ADJ. human","VERB + BARRICADE build, construct, erect, put up, set up | form The protesters formed a human barricade. | dismantle, remove, take down | sm","PREP. behind a/the ~ fighting from behind their barricades | over a/the ~ The two sides watched each other over the barricades. | ~ across a"]},"media":{"uk":"media/ldoce/hwd/bre/9/barricade_v0205.mp3","us":"media/ldoce/hwd/ame/5/barricade1.mp3"},"examples":[{"en":"They barricaded all the doors and windows.","cn":"他们用障碍物堵住了所有的门窗。"},{"en":"The police stormed the barricades the demonstrators had put up.","cn":"警察冲破了示威者筑起的街垒。"}],"oxford":{"phon":"ˈbærɪkeɪd","pos":"noun","senses":[{"en":"a line of objects placed across a road, etc. to stop people from getting past","cn":"路障；街垒","ex":{"en":"The police stormed the barricades the demonstrators had put up.","cn":"警察冲破了示威者筑起的街垒。"}},{"en":"to defend or block something by building a barricade","cn":"设路障防护；阻挡","ex":{"en":"They barricaded all the doors and windows.","cn":"他们用障碍物堵住了所有的门窗。"},"pos":"verb"}]}},"backlog":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"积压的事情；未完成的工作","en":"A backlog is a number of things which have not yet been done but which need to be done.","ex":{"en":"There is a backlog of repairs and maintenance in schools.","cn":"对各学校的修缮和维护工作积压了一堆。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large amount of work that you need to complete, especially work that should already have been completed","cn":"积压未办之事﹐积压的工作"}]},"collocations":{"phrases":["ADJ. big, considerable, enormous, huge, large","VERB + BACKLOG be faced with, have We are faced with a backlog of orders we can't deal with. | catch up on, clear, deal with, reduce","BACKLOG + VERB accumulate, build up A huge backlog of work had built up."]},"media":{"uk":"media/ldoce/hwd/bre/c/backlog0205.mp3","us":"media/ldoce/hwd/ame/f/backlog.mp3"},"examples":[{"en":"It’s going to take us months to clear the backlog .","cn":"我们得花好几个月才能处理完积压未办的事情。"},{"en":"a backlog of requests","cn":"积压的请求"}],"oxford":{"phon":"ˈbæklɒɡ","pos":"noun","senses":[{"en":"a quantity of work that should have been done already, but has not yet been done","cn":"积压的工作","ex":{"en":"When she eventually returned to work, there was a tremendous backlog of paperwork to catch up on.","cn":"当她最终重返工作岗位时，有大量积压的文书工作需要处理。"}}]}},"barrage":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"连续的炮火；弹幕；火力网","en":"A barrage is continuous firing on an area with large guns and tanks.","ex":{"en":"The artillery barrage on the city centre was the heaviest since the ceasefire","cn":"针对市中心的炮火是停战以来最猛烈的。"}},{"pos":"N-COUNT 可数名词","cn":"接二连三，一连串（的批评、抱怨等）","en":"A barrage of something such as criticism or complaints is a large number of them directed at someone, often in an aggressive way.","ex":{"en":"He was faced with a barrage of angry questions from the floor.","cn":"他受到了与会者一连串愤怒的质询。"}},{"pos":"VERB 动词","cn":"（大批人或事物）包围；使穷于应付","en":"If you are barraged by people or things, you have to deal with a great number of people or things you would rather avoid.","ex":{"en":"Doctors are complaining about being barraged by drug-company salesmen","cn":"医生们抱怨他们疲于应付医药公司的销售人员。"}},{"pos":"N-COUNT 可数名词","cn":"堰；水坝；拦河坝","en":"A barrage is a structure that is built across a river to control the level of the water.","ex":{"en":"...a hydro-electric tidal barrage.","cn":"潮汐水电站"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the continuous firing of guns, dropping of bombs etc, especially to protect soldiers as they move towards an enemy","cn":"掩护炮火﹐弹幕﹐火力网"},{"en":"a lot of criticism, questions, complaints etc that are said at the same time, or very quickly one after another [","cn":"批评﹑问题﹑投诉等的]接二连三"},{"en":"a wall of earth, stones etc built across a river to provide water for farming or to prevent flooding","cn":"拦河坝﹐堰堤"}]},"vocab":{"pos":"n v","senses":[{"en":"A barrage is something that comes quickly and heavily — as an attack of bullets or artillery, or a fast spray of words."}]},"collocations":{"phrases":["ADJ. heavy, intense | artillery","VERB + BARRAGE launch, unleash","BARRAGE + NOUN balloon","PREP. ~ of Troops unleashed a barrage of grenades. 2 large number of questions, etc.","ADJ. constant, continuous, endless","VERB + BARRAGE be faced with, endure, face | keep up The reporters kept up a constant barrage of questions.","PHRASES a barrage of abuse/complaints/criticism/questions The president is facing a barrage of criticism over his handling of the crisis. 3 ","ADJ. tidal"]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdebarrage.mp3","us":"media/ldoce/hwd/ame/8/l3barrage.mp3"},"examples":[{"en":"a barrage of questions/criticisms/complaints","cn":"连珠炮似的问题/批评/抱怨"},{"en":"a barrage of anti-aircraft fire","cn":"高射炮火网"}],"oxford":{"phon":"ˈbærɑːʒ","pos":"noun","senses":[{"en":"the continuous firing of a large number of guns in a particular direction, especially to protect soldiers while they are attacking or moving towards the enemy","cn":"火力网；弹幕射击；（尤指）掩护炮火","g":"[countable, usually singular]","ex":{"en":"an artillery barrage from at least 1 000 guns","cn":"至少 1 000 门大炮的炮火攻击"}},{"en":"a large number of something, such as questions or comments, that are directed at somebody very quickly, one after the other, often in an aggressive way","cn":"接二连三的一大堆（质问或指责等）","g":"[singular]","ex":{"en":"a barrage of questions/criticisms/complaints","cn":"连珠炮似的问题／批评／抱怨"}},{"en":"a wall or barrier built across a river to store water, prevent a flood, etc.","cn":"堰；水坝；拦河坝","g":"[countable]","ex":{"en":"They built a barrage across the bay.","cn":"他们建造了一座横贯海湾的拦海堤坝。"}}]}},"bath":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"浴盆；浴缸","en":"A bath is a container, usually a long rectangular one, which you fill with water and sit in while you wash your body.","ex":{"en":"In those days, only quite wealthy families had baths of their own.","cn":"那时候，只有非常富有的家庭才有自己的浴缸。"}},{"pos":"N-COUNT 可数名词","cn":"（在浴缸中的）洗澡，沐浴","en":"When you have or take a bath, or when you are in the bath, you sit or lie in a bath filled with water in order to wash your body.","ex":{"en":"...if you have a bath every morning","cn":"如果你每天早上泡澡"}},{"pos":"VERB 动词","cn":"给（小孩）洗澡","en":"If you bath someone, especially a child, you wash them in a bath.","ex":{"en":"Don't feel you have to bath your child every day.","cn":"不用每天给孩子洗澡。"}},{"pos":"VERB 动词","cn":"洗澡；沐浴","en":"When you bath, you have a bath.","ex":{"en":"The three children all bath in the same bath water.","cn":"这三个小孩用同一盆水洗澡。"}},{"pos":"N-COUNT 可数名词","cn":"澡堂；（附带泳池的）公共浴室","en":"A bath or a baths is a public building containing a swimming pool, and sometimes other facilities that people can use to have a wash or a bath.","ex":{"en":"One of the most important buildings in this ruined city is a public bath","cn":"在这座被毁坏的城市里，最重要的建筑物之一就是公共澡堂。"}},{"pos":"N-COUNT 可数名词","cn":"（盛放溶液的）容器","en":"A bath is a container filled with a particular liquid, such as a dye or an acid, in which particular objects are placed, usually as part of a manufacturing or chemical process.","ex":{"en":"...a developing photograph placed in a bath of fixer.","cn":"放在定影液中冲洗的照片"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to wash your whole body while standing under a shower","cn":""},{"en":"to wash your whole body while sitting in a bath full of water","cn":""},{"en":"to be sitting in a bath washing your whole body","cn":""}]},"collocations":{"phrases":["ADJ. hot, warm | cold | long | quick | bubble lying in a hot bubble bath | baby, bird","VERB + BATH fill, run Could you run the bath for me? | have, take | lie in, soak in | need","BATH + NOUN tap, water (also bathwater ) | mat, towel | time It's the children's bath time.","PREP. in the ~ Please answer the phone. I'm in the bath!"]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdebath.mp3","us":"media/ldoce/hwd/ame/5/l3bath.mp3"},"examples":[{"en":"Let’s go for a quick swim in the pool.","cn":"咱们去游泳池游会儿泳吧。"},{"en":"I think I'll have a bath and go to bed.","cn":"我想洗个澡，然后睡觉。"}],"oxford":{"phon":"bɑːθ","pos":"noun","senses":[{"en":"a large, long container that you put water in and then get into to wash your whole body","cn":"浴缸；浴盆","g":"[countable]","lab":"British English","ex":{"en":"I'm in the bath!","cn":"我在泡澡呢！"}},{"en":"an act of washing your whole body by sitting or lying in water","cn":"洗澡；洗浴","g":"[countable]","lab":"British English","ex":{"en":"I think I'll have a bath and go to bed.","cn":"我想洗个澡，然后睡觉。"}},{"en":"the water in a bath ready to use","cn":"浴缸里的水","g":"[countable]","ex":{"en":"a long soak in a hot bath","cn":"一次长时间的热水浴"}},{"en":"a public building where you can go to swim","cn":"游泳池","g":"[plural]","lab":"British English, old-fashioned，，","ex":{"en":"My father took me to the baths every Sunday.","cn":"我父亲每周日都带我去洗澡。"}},{"en":"a public place where people went in the past to wash or have a bath","cn":"（旧时的）公共浴室，澡堂","g":"[countable, usually plural]","ex":{"en":"Roman villas and baths","cn":"罗马别墅和浴室"}},{"en":"a container with a liquid such as water or a dye in it, in which something is washed or placed for a period of time. Baths are used in industrial, chemical and medical processes.","cn":"浴器，浴锅，染缸（工业、化学以及医学加工处理用）","g":"[countable]","lab":"specialist"},{"en":"to give a bath to somebody","cn":"给…洗澡","g":"[transitive]","ex":{"en":"It's your turn to bath the baby.","cn":"轮到你给婴儿洗澡了。"},"pos":"verb"},{"en":"to have a bath","cn":"洗澡","g":"[intransitive]","lab":"old-fashioned","pos":"verb"},{"en":"a city in south-west England, famous for its healthy mineral water and hot springs, its ancient Roman baths and beautiful Georgian buildings. The Bath Festival is a festival of classical music held every year in May and June. In 1987 Bath was one of the first places in Britain to become a World Heritage Site.","cn":"巴斯（英格兰西南部城市，以其有益健康的矿泉水和温泉、古罗马时代的公共浴室和乔治王朝时期的美丽建筑而闻名）","pos":""}]}},"batch":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一批；一组；一群","en":"A batch of things or people is a group of things or people of the same kind, especially a group that is dealt with at the same time or is sent to a particular place at the same time.","ex":{"en":"...the current batch of trainee priests","cn":"目前的一批牧师学员"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a number of people who are similar in some way, or who have the same ideas and aims","cn":""},{"en":"a group of people - use this especially about people that you do not like or do not approve of","cn":""},{"en":"a group of people, especially people who you think are strange or unusual","cn":""}]},"collocations":{"phrases":["ADJ. large, small | whole A whole batch of original drawings will be on sale. | fresh, new He baked a fresh batch of rolls. Each summer a ne","PREP. in the ~ How many books are there in each batch? We deliver the goods in batches. | ~ of a batch of letters 2 in computing","BATCH + NOUN job to process a batch job | file, program | processing | mode to run in batch mode | queue"]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdebatch.mp3","us":"media/ldoce/hwd/ame/6/batch.mp3"},"examples":[{"en":"The service will be improved by batching and sorting enquiries.","cn":"分批及分类处理查询将会提高服务质量。"},{"en":"Each summer a new batch of students tries to find work.","cn":"每年夏天都有一批新的学生要找工作。"}],"oxford":{"phon":"bætʃ","pos":"noun","senses":[{"en":"a number of people or things that are dealt with as a group","cn":"一批","ex":{"en":"Each summer a new batch of students tries to find work.","cn":"每年夏天都有新的一批学生要找工作。"}},{"en":"an amount of food, medicine, etc. produced at one time","cn":"（食物、药物等的）一批生产的量","ex":{"en":"Shall I make another batch of cookies?","cn":"我是否要再做一批曲奇饼？"}},{"en":"a set of jobs that are processed together on a computer","cn":"批；批量","lab":"computing","ex":{"en":"to process a batch job","cn":"处理一批作业"}},{"en":"to put things into groups in order to deal with them","cn":"分批处理","ex":{"en":"The service will be improved by batching and sorting enquiries.","cn":"分批、分类处理查询将会提高服务质量。"},"pos":"verb"}]}},"bangkok":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the capital city and main port of Thailand. It is famous for its temple s and other beautiful buildings.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/p028-000002004.mp3","us":"media/ldoce/hwd/ame/7/p028-000002004.mp3"}},"bang":{"collins":{"senses":[{"pos":"N-COUNT; SOUND 可数名词；声音词","cn":"突然的巨响","en":"A bang is a sudden loud noise such as the noise of an explosion.","ex":{"en":"I heard four or five loud bangs","cn":"我听到四五声巨响。"}},{"pos":"VERB 动词","cn":"发出巨响；砰然作响","en":"If something bangs, it makes a sudden loud noise, once or several times.","ex":{"en":"The engine spat and banged.","cn":"发动机爆出火花，接着发出砰的巨响。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）砰的一声关上","en":"If you bang a door or if it bangs, it closes suddenly with a loud noise.","ex":{"en":"...the sound of doors banging","cn":"砰然作响的关门声"}},{"pos":"VERB 动词","cn":"猛击；砰然重击","en":"If you bang on something or if you bang it, you hit it hard, making a loud noise.","ex":{"en":"We could bang on the desks and shout till they let us out","cn":"我们可以拍着桌子大喊大叫，直到他们放我们出去。"}},{"pos":"VERB 动词","cn":"（因生气而）砰地放下，猛然放下","en":"If you bang something on something or if you bang it down, you quickly and violently put it on a surface, because you are angry.","ex":{"en":"She banged his dinner on the table","cn":"她把他的饭菜砰地摔在了桌子上。"}},{"pos":"VERB 动词","cn":"撞伤（身体某一部位）","en":"If you bang a part of your body, you accidentally knock it against something and hurt yourself.","ex":{"en":"She'd fainted and banged her head","cn":"她晕倒了，把脑袋给磕了。"}},{"pos":"VERB 动词","cn":"（通常指由于未能注意到眼前的人或物）撞上","en":"If you bang into something or someone, you bump or knock them hard, usually because you are not looking where you are going.","ex":{"en":"I didn't mean to bang into you","cn":"我不是故意撞你的。"}},{"pos":"N-PLURAL 复数名词","cn":"刘海；额前短垂发","en":"Bangs are hair which is cut so that it hangs over your forehead.","ex":{"en":"My bangs were cut short, but the rest of my hair was long.","cn":"我剪短了刘海，但其他地方的头发还是很长。"}},{"pos":"ADV 副词","cn":"恰好；正巧；准确地","en":"You can use bang to emphasize expressions that indicate an exact position or an exact time.","ex":{"en":"...bang in the middle of the track","cn":"在小径的正中央"}},{"pos":"PHRASE 短语","cn":"…告吹了；…完蛋了；…没戏了","en":"If you say bang goes something, you mean that it is now obvious that it cannot succeed or be achieved.","ex":{"en":"There will be more work to do, not less. Bang goes the fantasy of retirement at 35.","cn":"工作只会增加，不会减少。梦想着35岁退休是彻底没戏了。"}},{"pos":"PHRASE 短语","cn":"精力充沛地；热情高涨地；非常成功地","en":"If something begins or ends with a bang, it begins or ends with a lot of energy, enthusiasm, or success.","ex":{"en":"Her career began with a bang in 1986.","cn":"1986年，她的事业一炮打响。"}},{"pos":"","cn":"","en":"to bang your head against a brick wall→see: ; to bang two people's heads together→see: ;"},{"pos":"","cn":"","en":"相关词组：bang on about bang out bang up"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short sudden loud noise made by a gun, bomb etc","cn":""},{"en":"a very loud sound from an explosion, which you can hear for several seconds after it begins","cn":""},{"en":"a continuous very loud noise that gets louder and continues for a long time","cn":""}]},"collocations":{"phrases":["ADV. hard, loudly","PREP. against He kept banging his chair against the wall. | on She banged loudly on the table.","PHRASES bang sth about, bang (sth) down, bang (sth) open/shut The bedroom door banged shut. She banged the door shut. 2 part of the body/per","ADV. badly, hard I had banged my head badly.","PREP. into He banged into me in the corridor. | on I banged my leg on the table."]},"media":{"uk":"media/ldoce/hwd/bre/b/bang_adv0205.mp3","us":"media/ldoce/hwd/ame/d/bang1.mp3"},"examples":[{"en":"The team won their last four games, ending the season with a bang.","cn":"该队赢了最后四场比赛，给本赛季画了一个亮丽的句号。"},{"en":"We could hear the kids banging around upstairs.","cn":"我们能听到孩子们在楼上咚咚地跑来跑去。"}],"oxford":{"phon":"bæŋ","pos":"verb","senses":[{"en":"to hit something in a way that makes a loud noise","cn":"猛敲；砸","g":"[intransitive, transitive]","ex":{"en":"She banged on the door angrily.","cn":"她愤怒地砰砰捶门。"}},{"en":"to close something or to be closed with a loud noise","cn":"（把…）砰地关上","g":"[intransitive, transitive]","ex":{"en":"A window was banging somewhere (= opening and closing noisily).","cn":"什么地方有扇窗户在砰砰地开开关关。"}},{"en":"to put something somewhere suddenly and violently","cn":"猛摔；砰地一扔","g":"[transitive]","ex":{"en":"He banged the money down on the counter.","cn":"他把钱往柜台上砰地一掷。"}},{"en":"to hit something, especially a part of the body, against something by accident","cn":"碰撞；磕","g":"[transitive]","ex":{"en":"She tripped and banged her knee on the desk.","cn":"她绊了一跤，膝盖磕在桌子上。"}},{"en":"to have sex with somebody","cn":"（和某人）性交","g":"[transitive]","lab":"taboo, slang，，"},{"en":"a sudden loud noise","cn":"突然的巨响","g":"[countable]","ex":{"en":"The door swung shut with a bang.","cn":"门砰的一声关上了。"},"pos":"noun"},{"en":"a sudden painful hit on a part of the body","cn":"（对身体部位的）猛撞，猛敲，猛击","g":"[countable]","ex":{"en":"a bang on the head","cn":"头被撞击"},"pos":"noun"},{"en":"the front part of somebody’s hair that is cut so that it hangs over their forehead","cn":"额前短垂发；刘海儿","g":"[plural]","lab":"North American English","ex":{"en":"She blew her bangs out of her face.","cn":"她把刘海儿从脸上吹开。"},"pos":"noun"},{"en":"the leaves and flower tops of the cannabis plant, used as a drug","cn":"大麻的叶和花穗（用作麻醉品）","g":"[uncountable]","pos":"noun"},{"en":"the symbol ( ! )","cn":"叹号","g":"[countable]","lab":"informal, computing，，","pos":"noun"},{"en":"exactly; completely","cn":"正好；完全地","lab":"informal, especially British English，，","ex":{"en":"Our computers are bang up to date.","cn":"我们的电脑是最先进的。"},"pos":"adverb"},{"en":"used to show the sound of something loud, like a gun","cn":"（表示枪声等巨响）砰","ex":{"en":"‘Bang, bang, you're dead!’ shouted the little boy.","cn":"“砰！砰！你死了！”小男孩喊道。"},"pos":"exclamation"}]}},"banking":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"银行业","en":"Banking is the business activity of banks and similar institutions."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the business of a bank","cn":"银行业"}]},"collocations":{"phrases":["ADJ. business, commercial, corporate | investment, merchant | retail, wholesale | domestic, national | global, international | e-, electroni","BANKING + NOUN system | market | group | business, industry, sector | community the international banking community","PREP. in ~ This software is used in banking."]},"media":{"uk":"media/ldoce/hwd/bre/8/brelasdebanking.mp3","us":"media/ldoce/hwd/ame/5/banking.mp3"},"examples":[{"en":"She's thinking about a career in banking.","cn":"她正在考虑从事银行业。"},{"en":"the international banking system","cn":"国际银行体制"}],"oxford":{"phon":"ˈbæŋkɪŋ","pos":"noun","senses":[{"en":"the business activity of banks","cn":"银行业","ex":{"en":"She's thinking about a career in banking.","cn":"她正在考虑从事银行业。"}}]}},"bait":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"饵；诱饵","en":"Bait is food which you put on a hook or in a trap in order to catch fish or animals."},{"pos":"VERB 动词","cn":"装饵于；给（鱼钩或陷阱等）上诱饵","en":"If you bait a hook or trap, you put bait on it or in it.","ex":{"en":"He baited his hook with pie","cn":"他在鱼钩上装了点馅饼作钓饵。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"诱惑物；引诱物","en":"To use something as bait means to use it to trick or persuade someone to do something.","ex":{"en":"Service stations use petrol as a bait to lure motorists into the restaurants and other facilities","cn":"加油站以汽油为诱饵，吸引开车的人用餐以及使用其他设施。"}},{"pos":"VERB 动词","cn":"使上当发火；故意逗…生气","en":"If you bait someone, you deliberately try to make them angry by teasing them.","ex":{"en":"He delighted in baiting his mother.","cn":"他喜欢逗母亲生气。"}},{"pos":"PHRASE 短语","cn":"中圈套，上当，中计（亦作rise to the bait,主要用于英国英语中）","en":"If you take the bait, you react to something that someone has said or done exactly as they intended you to do. The expression rise to the bait is also used, mainly in British English.","ex":{"en":"When she attempts to make you feel guilty, don't take the bait","cn":"如果她试图让你觉得内疚，不要上当。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"food used to attract fish, animals, or birds so that you can catch them","cn":"饵﹐诱饵"},{"en":"something attractive that is offered to someone to make them do something or buy something, especially when this is done in a dishonest way that tricks people 〔","cn":"使别人上当的〕引诱物﹐诱饵"},{"en":"to become angry when someone is deliberately trying to make you angry","cn":"被故意激怒﹐上当发火"}]},"vocab":{"pos":"1 n v 2 v","senses":[{"en":"People who go fishing aren’t the only ones to use bait . When you hold a yard sale, place your best stuff closest to the sidewalk — to serve as bait . Bait can be anything from the worms that hide a hook to a stereo that tempts shoppers to stop and browse."}]},"collocations":{"phrases":["ADJ. fresh, live He used maggots as live bait.","VERB + BAIT put out, set out We'll put out the bait and see what happens. | use sth as | nibble (at), rise to, take (all often figurative) W"]},"media":{"uk":"media/ldoce/hwd/bre/3/bait_v0205.mp3","us":"media/ldoce/hwd/ame/4/bait1.mp3"},"examples":[{"en":"He baited the trap with a piece of meat.","cn":"他在陷阱中放了一片肉做诱饵。"},{"en":"The fish took the bait.","cn":"鱼咬了钓饵。"}],"oxford":{"phon":"beɪt","pos":"noun","senses":[{"en":"food put on a hook to catch fish or in nets, traps, etc. to catch animals or birds","cn":"鱼饵；诱饵","ex":{"en":"Live worms are used as bait.","cn":"使用活虫作为诱饵。"}},{"en":"a person or thing that is used to attract somebody in order to catch them or make them do what you want","cn":"用作诱饵的人（或物）","ex":{"en":"The police used him as bait to trap the killers.","cn":"警方用他作诱饵，设圈套捉拿凶手。"}},{"en":"to place food on a hook, in a trap, etc. in order to attract or catch a fish or an animal","cn":"下诱饵；在（鱼钩上、陷阱中等）放诱饵","ex":{"en":"He baited the trap with a piece of meat.","cn":"他在陷阱中放了一片肉做诱饵。"},"pos":"verb"},{"en":"to deliberately try to make somebody angry or to hurt them by making cruel remarks","cn":"（故意以侮辱性言语）激怒，伤害","ex":{"en":"The soldiers remained calm even though the crowd was baiting them.","cn":"尽管人群在引诱他们，士兵们仍然保持冷静。"},"pos":"verb"},{"en":"the activity of attacking a wild animal with dogs","cn":"纵犬袭击（野兽）","ex":{"en":"bear-baiting","cn":"纵犬斗熊"},"pos":"verb"}]}},"balloon":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"气球","en":"A balloon is a small, thin, rubber bag that you blow air into so that it becomes larger and rounder or longer. Balloons are used as toys or decorations.","ex":{"en":"She popped a balloon with her fork.","cn":"她用叉子戳破了一个气球。"}},{"pos":"N-COUNT 可数名词","cn":"热气球","en":"A balloon is a large, strong bag filled with gas or hot air, which can carry passengers in a container that hangs underneath it.","ex":{"en":"They are to attempt to be the first to circle the Earth non-stop by balloon.","cn":"他们试图完成乘热气球不间断环球飞行的创举。"}},{"pos":"VERB 动词","cn":"（数量）激增，猛涨，快速膨胀","en":"When something balloons, it increases rapidly in amount.","ex":{"en":"In London, the use of the Tube has ballooned","cn":"在伦敦，坐地铁的人激增。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an object made of brightly coloured thin rubber, that is filled with air and used as a toy or decoration for parties","cn":"气球"},{"en":"a large bag of strong light cloth filled with gas or heated air so that it can float in the air. It has a basket hanging below it for people to stand in","cn":"热气球"},{"en":"the circle drawn around the words spoken by the characters in a cartoon 〔","cn":"卡通漫画中表示人物对白的〕气球状对话框﹐对白圆圈"}]},"collocations":{"phrases":["ADJ. helium helium balloons for the children's party","VERB + BALLOON blow up, inflate | burst, pop","BALLOON + VERB burst, pop 2 in the sky","ADJ. barrage, hot-air","VERB + BALLOON go up in We went up in a balloon.","BALLOON + NOUN flight | race","PREP. by ~ She crossed the Atlantic by hot-air balloon."]},"media":{"img":["media/ldoce/img/balloon.jpg"],"uk":"media/ldoce/hwd/bre/3/balloon_n0205.mp3","us":"media/ldoce/hwd/ame/a/balloon1.mp3"},"examples":[{"en":"Her skirt ballooned out in the wind.","cn":"她的裙子让风吹得鼓起来了。"},{"en":"to blow up/burst/pop a balloon","cn":"吹起气球；使气球爆裂"}],"oxford":{"phon":"bəˈluːn","pos":"noun","senses":[{"en":"a small bag made of very thin rubber that becomes larger and rounder when you fill it with air or gas. Balloons are brightly coloured and used as decorations or toys.","cn":"气球","ex":{"en":"to blow up/burst/pop a balloon","cn":"吹起气球；使气球爆裂"}},{"en":"a large balloon made of strong material that is filled with hot air or gas to make it rise in the air, usually carrying a basket for passengers","cn":"热气球","ex":{"en":"We went up in a balloon.","cn":"我们乘着气球向上升。"}},{"en":"to form a round shape","cn":"成球形","g":"[intransitive]","ex":{"en":"Her skirt ballooned out in the wind.","cn":"她的裙子让风吹得鼓起来了。"},"pos":"verb"},{"en":"to increase rapidly","cn":"急剧增长","g":"[intransitive]","ex":{"en":"Unemployment ballooned to fourteen per cent.","cn":"失业率飙升至14%。"},"pos":"verb"},{"en":"to travel in a hot-air balloon as a sport or for entertainment","cn":"乘热气球飞行","g":"[intransitive]","pos":"verb"}]}},"bailiff":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（法庭的）执达吏","en":"A bailiff is a law officer who makes sure that the decisions of a court are obeyed. Bailiffs can take a person's furniture or possessions away if the person owes money."},{"pos":"N-COUNT 可数名词","cn":"法警；庭警","en":"A bailiff is an official in a court of law who deals with tasks such as keeping control in court."},{"pos":"N-COUNT 可数名词","cn":"（地主的）管家，看守人","en":"A bailiff is a person who is employed to look after land or property for the owner."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who looks after a farm or land that belongs to someone else","cn":"农场管理人﹔农场主[地主]的管家"},{"en":"an official of the legal system who watches prisoners and keeps order in a court of law","cn":"法警"},{"en":"an official of the legal system who can take people’s goods or property when they owe money 〔","cn":"查封欠债人财产的〕查封官﹐执达吏"}]},"vocab":{"pos":"n","senses":[{"en":"A bailiff is an officer of the court. A bailiff has duties such as making arrests and maintaining order in court."}]},"collocations":{"phrases":["ADJ. court | private","VERB + BAILIFF send in Their landlord has threatened to send in the bailiffs if they don't pay their rent.","BAILIFF + VERB seize sth The bailiffs seized the car and house."]},"media":{"uk":"media/ldoce/hwd/bre/4/bailiff0205.mp3","us":"media/ldoce/hwd/ame/0/bailiff.mp3"},"oxford":{"phon":"ˈbeɪlɪf","pos":"noun","senses":[{"en":"a law officer whose job is to take the possessions and property of people who cannot pay their debts","cn":"执达员；执达官","lab":"British English","ex":{"en":"The bailiffs seized the car and house.","cn":"法庭执达官扣押了车和房。"}},{"en":"a person employed to manage land or a large farm for somebody else","cn":"庄园主管家","lab":"British English"},{"en":"an official who keeps order in court, takes people to their seats, watches prisoners, etc.","cn":"法警","lab":"North American English"}]}},"backstroke":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"仰泳","en":"Backstroke is a swimming stroke that you do lying on your back."},{"pos":"N-SING 单数名词","cn":"仰泳比赛","en":"The backstroke is a swimming race in which the competitors swim backstroke.","ex":{"en":"...the 100 metres backstroke.","cn":"100米仰泳比赛"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a way of swimming on your back by moving first one arm then the other backwards while kicking your feet","cn":"仰泳"}]},"media":{"uk":"media/ldoce/hwd/bre/6/backstroke0205.mp3","us":"media/ldoce/hwd/ame/6/backstroke.mp3","img":["media/thumb/backstroke.jpg"]},"examples":[{"en":"He won the 100 metres backstroke (= the race).","cn":"他获得 100 米仰泳比赛冠军。"},{"en":"Can you do (the) backstroke?","cn":"你会仰泳吗？"}],"oxford":{"phon":"ˈbækstrəʊk","pos":"noun","senses":[{"en":"a style of swimming in which you lie on your back","cn":"仰泳","ex":{"en":"Can you do (the) backstroke?","cn":"你会仰泳吗？"}}]}},"barometer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"气压计；气压表；晴雨表","en":"A barometer is an instrument that measures air pressure and shows when the weather is changing."},{"pos":"N-COUNT 可数名词","cn":"变化的标志；晴雨表","en":"If something is a barometer of a particular situation, it indicates how things are changing or how things are likely to develop.","ex":{"en":"In past presidential elections, Missouri has been a barometer of the rest of the country","cn":"在过去的总统选举中，密苏里州一直是国内其他州的晴雨表。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an instrument that measures changes in the air pressure and the weather, or that calculates height above sea level","cn":"气压计﹐晴雨表"},{"en":"something that shows any changes that are happening in a particular situation 〔","cn":"反映事物变化的〕晴雨表﹐指标﹐标志"}]},"vocab":{"pos":"n","senses":[{"en":"A barometer is a device that measures atmospheric pressure. Barometers help meteorologists figure out what the weather is going to be like."}]},"collocations":{"phrases":["ADJ. aneroid, digital | high, low | steady The barometer has been steady for three days now.","VERB + BAROMETER check, read | tap He tapped the barometer and noted where the needle was pointing.","BAROMETER + VERB rise | drop, fall 2 sth that shows the state of sth","ADJ. accurate, good, reliable, sensitive, useful Infant mortality is a highly sensitive barometer of socio-economic conditions. | political","PREP. ~ of"]},"media":{"img":["media/ldoce/img/barometer.jpg"],"uk":"media/ldoce/hwd/bre/c/barometer0205.mp3","us":"media/ldoce/hwd/ame/5/barometer.mp3"},"examples":[{"en":"Infant mortality is a reliable barometer of socio-economic conditions.","cn":"婴儿死亡率是社会经济状况的可靠指标。"},{"en":"The barometer is falling (= showing that it will probably rain).","cn":"气压在下降（表示可能要下雨）。"}],"oxford":{"phon":"bəˈrɒmɪtə(r)","pos":"noun","senses":[{"en":"an instrument for measuring air pressure to show when the weather will change","cn":"气压计；气压表；晴雨表","ex":{"en":"The barometer is falling (= showing that it will probably rain).","cn":"气压在下降（表示可能要下雨）。"}},{"en":"something that shows the changes that are happening in an economic, social or political situation","cn":"（显示经济、社会、政治变化的）晴雨表，标志，指标","ex":{"en":"Infant mortality is a reliable barometer of socio-economic conditions.","cn":"婴儿死亡率是社会经济状况的可靠指标。"}}]}},"backdrop":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（挂在舞台后部的）彩画幕布，背景幕布","en":"A backdrop is a large piece of cloth, often with scenery painted on it, that is hung at the back of a stage while a play is being performed."},{"pos":"N-COUNT 可数名词","cn":"（实物或景象的）背景，衬托","en":"The backdrop to an object or a scene is what you see behind it.","ex":{"en":"Leeds Castle will provide a dramatic backdrop to a fireworks display next Saturday","cn":"利兹堡将为下周六的烟花燃放提供美妙的背景衬托。"}},{"pos":"N-COUNT 可数名词","cn":"（事件的）背景","en":"The backdrop to an event is the general situation in which it happens.","ex":{"en":"The election will take place against a backdrop of increasing instability.","cn":"选举将在愈加动荡不安的局势下举行。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the area behind someone or something in a picture, on a stage etc","cn":""},{"en":"if someone or something is in the background , it is behind the place where the main activity is happening","cn":""},{"en":"the things such as buildings, hills or mountains that are behind something that you are looking at","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A backdrop is the scenery that hangs behind the actors in a play. You might help to paint the backdrop for your school's production of \"The Sound of Music.\""}]},"collocations":{"phrases":["ADJ. dramatic, magnificent, perfect, picturesque, romantic | economic, historical, political","VERB + BACKDROP have | provide","PREP. against a/the ~ of The conference begins this week against a backdrop of unmitigated gloom. | ~ for The Alps provided the perfect back"]},"media":{"uk":"media/ldoce/hwd/bre/5/backdrop0205.mp3","us":"media/ldoce/hwd/ame/8/backdrop.mp3"},"examples":[{"en":"It was against this backdrop of racial tension that the civil war began.","cn":"这场内战肇端于种族之间的紧张状态。"},{"en":"The mountains provided a dramatic backdrop for our picnic.","cn":"群山如画，给我们的野餐平添景色。"}],"oxford":{"phon":"ˈbækdrɒp","pos":"noun","senses":[{"en":"everything that can be seen around an event or scene","cn":"（事件发生时）周围陪衬景物","ex":{"en":"The mountains provided a dramatic backdrop for our picnic.","cn":"群山如画，给我们的野餐平添景色。"}},{"en":"the general conditions in which an event takes place, which sometimes help to explain that event","cn":"（事态或活动的）背景","ex":{"en":"Her comments came against the backdrop of growing demand for vaccines.","cn":"她的评论是在疫苗需求不断增长的背景下发表的。"}},{"en":"a painted piece of cloth that is hung behind the stage in a theatre as part of the scenery","cn":"（舞台的）背景幕布","ex":{"en":"She was an artist who designed backdrops for movies and stage plays.","cn":"她是一位为电影和舞台剧设计背景的艺术家。"}}]}},"backing":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"支持；资助；帮助","en":"If someone has the backing of an organization or an important person, they receive support or money from that organization or person in order to do something.","ex":{"en":"He said the president had the full backing of his government to negotiate a deal","cn":"他说政府将全力支持总统通过谈判达成协议。"}},{"pos":"N-VAR 可变名词","cn":"背衬；底衬","en":"A backing is a layer of something such as cloth that is put onto the back of something in order to strengthen or protect it."},{"pos":"N-COUNT 可数名词","cn":"（流行歌曲的）伴奏，伴唱","en":"The backing of a popular song is the music which is sung or played to accompany the main tune.","ex":{"en":"Sharon also sang backing vocals for Barry Manilow","cn":"莎伦也为巴里·马尼洛伴唱。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the help and encouragement that you give to someone when you want them to succeed","cn":""},{"en":"money or practical help given to support a person or plan, especially by a government or other powerful group","cn":""},{"en":"support or help, especially with money","cn":"支持﹐帮助﹔资助"}]},"collocations":{"phrases":["ADJ. strong | full, unanimous, whole-hearted The teachers have the full backing of the school governors. | financial, legal | government, of","VERB + BACKING have | gain, get, receive, secure, win They have won financial backing from the EU. | need, seek | give sb, provide (sb with)","BACKING + VERB come from sb/sth The backing will come from the government.","PREP. with/without the ~ They brought the legal action with the backing of their MP. | ~ for They want backing for more research. | ~ from b"]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdebacking.mp3","us":"media/ldoce/hwd/ame/e/backing.mp3"},"examples":[{"en":"The police gave the proposals their full backing.","cn":"警方对这些提案给予全力支持。"},{"en":"a backing group/singer/track","cn":"伴奏乐团；伴唱歌手；伴奏歌曲"}],"oxford":{"phon":"ˈbækɪŋ","pos":"noun","senses":[{"en":"help and support from somebody to do something; financial support for something","cn":"支持；资助","g":"[uncountable]","ex":{"en":"The police gave the proposals their full backing.","cn":"警方对这些提案给予全力支持。"}},{"en":"material attached to the back of something in order to protect it or make it stronger","cn":"背衬","g":"[uncountable, countable]","ex":{"en":"Remove the backing paper from the adhesive tape.","cn":"从胶带上取下背纸。"}},{"en":"music that goes with the main singer or tune","cn":"伴奏","g":"[uncountable, countable, usually singular]","ex":{"en":"a backing group/singer/track","cn":"伴奏乐团；伴唱歌手；伴奏乐曲"}}]}},"ballot":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"无记名投票；无记名选举；无记名表决","en":"A ballot is a secret vote in which people select a candidate in an election, or express their opinion about something.","ex":{"en":"The result of the ballot will not be known for two weeks","cn":"无记名投票的结果将于两周后公布。"}},{"pos":"N-COUNT 可数名词","cn":"（无记名）选票","en":"A ballot is a piece of paper on which you indicate your choice or opinion in a secret vote.","ex":{"en":"Election boards will count the ballots by hand","cn":"选举委员会将人工计票。"}},{"pos":"VERB 动词","cn":"在…中间进行无记名投票（或表决）","en":"If you ballot a group of people, you find out what they think about a subject by organizing a secret vote.","ex":{"en":"The union said they will ballot members on whether to strike.","cn":"工会称他们将要求会员投票表决是否罢工。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an occasion when people choose a government or leader by voting","cn":""},{"en":"an occasion when the members of an organization vote by marking what they want on a piece of paper, especially to make sure that it is secret","cn":""},{"en":"an occasion when everyone in a country votes on an important political subject","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A ballot is document that lists the choices during an election. When you vote for a candidate, you are casting your ballot in favor of that candidate (and crossing your fingers)."}]},"collocations":{"phrases":["ADJ. secret | open | postal | national | first, second | leadership | strike","VERB + BALLOT carry out, hold | organize | cast Only 40% of eligible voters cast their ballots.","BALLOT + NOUN box | paper | rigging","PREP. at a/the ~ They voted against him at the second ballot. | by ~ The jury cast their vote by secret ballot. | in a/the ~ The club member"]},"media":{"uk":"media/ldoce/hwd/bre/d/ballot_las2_br.mp3","us":"media/ldoce/hwd/ame/f/ballot1.mp3"},"examples":[{"en":"The union balloted its members on the proposed changes.","cn":"工会要求会员对所提议的变革进行无记名投票。"},{"en":"The union cannot call a strike unless it holds a ballot of members.","cn":"工会未经会员投票表决不得发动罢工。"}],"oxford":{"phon":"ˈbælət","pos":"noun","senses":[{"en":"the system of voting in writing and usually in secret; an occasion on which a vote is held","cn":"（无记名）投票选举；投票表决","g":"[uncountable, countable]","lab":"especially North American English","ex":{"en":"The chairperson is chosen by secret ballot.","cn":"主席是通过无记名投票选举产生的。"}},{"en":"the piece of paper on which somebody marks who they are voting for","cn":"选票","g":"[countable]","lab":"British English also","ex":{"en":"What percentage of eligible voters cast their ballots?","cn":"合资格选民的投票率是多少？"}},{"en":"the total number of votes in an election","cn":"投票总数；选票总数","g":"[singular]","ex":{"en":"She won 58.8% of the ballot.","cn":"她赢得了投票总数的 58.8%。"}},{"en":"to ask somebody to vote in writing and secretly about something","cn":"要求某人（对某事）无记名投票","g":"[transitive]","ex":{"en":"The union balloted its members on the proposed changes.","cn":"工会要求会员对所提议的变革进行无记名投票。"},"pos":"verb"},{"en":"to vote secretly about something","cn":"进行无记名投票","g":"[intransitive]","ex":{"en":"The workers balloted for a strike.","cn":"工人对是否罢工进行无记名投票表决。"},"pos":"verb"}]}},"backlash":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"强烈反应；强烈抵制；激烈反对","en":"A backlash against a tendency or recent development in society or politics, is a sudden, strong reaction against it.","ex":{"en":"...the male backlash against feminism.","cn":"男性对女权运动的强烈抵制"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone’s feelings, and how they behave, because of something that has happened or been said","cn":""},{"en":"what you say or do when someone says or does something to you","cn":""},{"en":"a particular type of reaction to someone’s ideas, work etc – used especially in the following phrases","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"When many people react against something in the same way, you can call it a backlash . A backlash against government policies can result in mass protests."}]},"collocations":{"phrases":["ADJ. conservative a conservative backlash against the feminism of the 80s | political | public","VERB + BACKLASH cause, produce, provoke Such a decision may provoke a backlash from their supporters. | expect, fear | face","PREP. ~ against a backlash against any future reforms | ~ from They face a backlash from shareholders."]},"media":{"uk":"media/ldoce/hwd/bre/4/backlash0205.mp3","us":"media/ldoce/hwd/ame/3/backlash.mp3"},"examples":[{"en":"The government is facing an angry backlash from voters over the new tax.","cn":"政府正面临选民对新税项的强烈反对。"},{"en":"The 1970s saw the first backlash against the women’s movement. 20","cn":"世纪70年代首次出现对妇女运动的抵制。"}],"oxford":{"phon":"ˈbæklæʃ","pos":"noun","senses":[{"en":"a strong negative reaction by a large number of people, for example to something that has recently changed in society","cn":"（对社会变动等的）强烈抵制，集体反对","ex":{"en":"The government is facing an angry backlash from voters over the new tax.","cn":"政府正面临选民对新税项的强烈反对。"}}]}},"baton":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"警棍","en":"A baton is a short heavy stick which is sometimes used as a weapon by the police."},{"pos":"N-COUNT 可数名词","cn":"（乐队或合唱队指挥用的）指挥棒","en":"A baton is a light, thin stick used by a conductor to conduct an orchestra or a choir."},{"pos":"N-COUNT 可数名词","cn":"（田径比赛中的）接力棒","en":"In athletics or track events, a baton is a short stick that is passed from one runner to another in a relay race."},{"pos":"N-COUNT 可数名词","cn":"（游行队伍中游行者持有的）指挥杖","en":"A baton is a long stick with a knob on one end that is sometimes carried by a person marching in a parade. The baton is spun round, thrown into the air and caught."},{"pos":"PHRASE 短语","cn":"移交权力/接受责任","en":"If someone passes the baton to another person, they pass responsibility for something to that person. If someone picks up the baton, they take over responsibility for something.","ex":{"en":"Does this mean that the baton of leadership is going to be passed to other nations?","cn":"这是不是意味着要把领导权交给其他国家？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short thin stick used by a conductor (= the leader of a group of musicians ) to direct the music 〔","cn":"乐队指挥用的〕指挥棒"},{"en":"a short light stick that is passed from one person to another during a race","cn":"接力棒"},{"en":"a short thick stick used as a weapon by a police officer","cn":"警棍"}]},"collocations":{"phrases":["ADJ. electric | wooden | police","VERB + BATON carry, hold | draw, use The police were ordered to draw their batons and disperse the crowd.","BATON + NOUN charge Five people were injured in the baton charge. 2 used by a conductor","VERB + BATON raise, wave","PREP. under the ~ of The orchestra made the recording under the baton of a young German conductor. 3 used in a relay race","ADJ. hand, pass Each runner passes the baton to the next. | take (up) | drop 4 used by a drum majorette","VERB + BATON swing, twirl"]},"media":{"uk":"media/ldoce/hwd/bre/4/baton0205.mp3","us":"media/ldoce/hwd/ame/3/baton.mp3"},"examples":[{"en":"( figurative ) The President handed over the baton (= passed responsibility) to his successor.","cn":"总统把权杖传给了他的继任者。"},{"en":"a baton charge (= one made by police carrying batons , to force a crowd back)","cn":"持警棍驱击"}],"oxford":{"phon":"ˈbætɒn","pos":"noun","senses":[{"en":"a short thick stick that police officers carry as a weapon","cn":"警棍","lab":"both especially British English","ex":{"en":"a baton charge (= one made by police carrying batons, to force a crowd back)","cn":"持警棍驱击"}},{"en":"a thin light stick used by the person (called a conductor) who is in control of an orchestra, etc.","cn":"（乐队）指挥棒","ex":{"en":"The orchestra played brilliantly under Previn’s baton.","cn":"乐团在普雷文的指挥下演奏得非常精彩。"}},{"en":"a short light stick that one member of a team in a relay race passes to the next person to run","cn":"接力棒","lab":"figurative","ex":{"en":"to pass/hand over the baton","cn":"交接力棒"}},{"en":"a long stick that is held and thrown in the air by a person marching in front of a band, or by a majorette","cn":"（行进中军乐队领队的）指挥杖"}]}},"backfire":{"collins":{"senses":[{"pos":"VERB 动词","cn":"事与愿违；适得其反","en":"If a plan or project backfires, it has the opposite result to the one that was intended.","ex":{"en":"The President's tactics could backfire","cn":"总统的策略可能会适得其反。"}},{"pos":"VERB 动词","cn":"（车辆或其发动机）逆火，回火","en":"When a motor vehicle or its engine backfires, it produces an explosion in the exhaust pipe.","ex":{"en":"The car backfired.","cn":"车回火了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to not succeed – used about people, plans, methods etc","cn":""},{"en":"if something you do goes wrong, it fails after starting well","cn":""},{"en":"if something does not work, it does not do what you want it to do","cn":""}]},"vocab":{"pos":"1 n v 2 v n 3 n v","senses":[{"en":"Use the word backfire when you talk about the sound a car makes when a small explosion in its exhaust system pops — sometimes as loudly as a gunshot."}]},"collocations":{"phrases":["ADV. badly, disastrously","PREP. on The surprise I had planned backfired on me."]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdebackfire.mp3","us":"media/ldoce/hwd/ame/1/backfire.mp3"},"examples":[{"en":"Unfortunately the plan backfired.","cn":"不幸的是，计划产生了适得其反的结果。"},{"en":"The company’s new policy backfired when a number of employees threatened to quit.","cn":"公司的新政策事与愿违﹐有好几名员工威胁说要辞职。"}],"oxford":{"phon":"ˌbækˈfaɪə(r)","pos":"verb","senses":[{"en":"to have the opposite effect to the one intended, with bad or dangerous results","cn":"产生事与愿违的不良（或危险）后果","g":"[intransitive]","ex":{"en":"Unfortunately the plan backfired.","cn":"不幸的是，计划产生了适得其反的结果。"}},{"en":"to make a sudden noise like an explosion","cn":"逆火；回火","g":"[intransitive]"}]}},"barefoot":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"赤脚的；光着脚的","en":"Someone who is barefoot or barefooted is not wearing anything on their feet.","ex":{"en":"I wore a white dress and was barefoot","cn":"我穿着一件白色连衣裙，赤着脚。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"without shoes on your feet","cn":"赤脚的[地]"}]},"collocations":{"phrases":["VERBS be, go, pad, stand, walk The children had to go barefoot because there was no money for shoes. He padded barefoot across the carpet."]},"media":{"uk":"media/ldoce/hwd/bre/4/b59new3.mp3","us":"media/ldoce/hwd/ame/b/barefoot.mp3"},"examples":[{"en":"poor children going barefoot in the street","cn":"光着脚流落街头的穷孩子"},{"en":"He walked barefoot across the sand.","cn":"他赤脚走过沙地。"}],"oxford":{"phon":"ˈbeəfʊt","pos":"adjective, adverb","senses":[{"en":"not wearing anything on your feet","cn":"赤脚（的）","ex":{"en":"poor children going barefoot in the street","cn":"光着脚在街头行走的穷孩子"}}]}},"banter":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（善意的）取笑，戏谑，打趣","en":"Banter is teasing or joking talk that is amusing and friendly.","ex":{"en":"She heard Tom exchanging good-natured banter with Jane.","cn":"她听见汤姆和简互相打趣。"}},{"pos":"V-RECIP 相互动词","cn":"（善意地和某人）开玩笑，打趣","en":"If you banter with someone, you tease them or joke with them in an amusing, friendly way.","ex":{"en":"The soldiers bantered with him as though he was a kid brother","cn":"士兵们把他当作弟弟一样和他开着玩笑。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an informal talk in which people exchange news, feelings, and thoughts","cn":""},{"en":"a conversation about something important","cn":""},{"en":"a long conversation, especially about a problem or about what you plan to do","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Good friends usually banter back and forth easily, like they're trying to keep a step ahead of each other in witty responses. This type of banter is their special language of friendship."}]},"collocations":{"phrases":["ADJ. easy, friendly, good-natured, lively, pleasant | idle | bawdy, ribald","VERB + BANTER swap | be engaged in, engage in She engages in friendly banter with her customers."]},"media":{"uk":"media/ldoce/hwd/bre/2/banter0205.mp3","us":"media/ldoce/hwd/ame/7/banter1.mp3"},"examples":[{"en":"He bantered with reporters and posed for photographers.","cn":"他和记者们打趣，并摆姿势让他们拍照。"},{"en":"He enjoyed exchanging banter with the customers.","cn":"他喜欢和顾客开玩笑。"}],"oxford":{"phon":"ˈbæntə(r)","pos":"noun","senses":[{"en":"friendly remarks and jokes","cn":"（善意的）玩笑，打趣","ex":{"en":"He enjoyed exchanging banter with the customers.","cn":"他喜欢和顾客开玩笑。"}},{"en":"to joke with somebody","cn":"（和某人）开玩笑；逗乐","ex":{"en":"He bantered with reporters and posed for photographers.","cn":"他和记者们打趣，并摆姿势让摄影师拍照。"},"pos":"verb"}]}},"baggage":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"行李","en":"Your baggage consists of the bags that you take with you when you travel.","ex":{"en":"The passengers went through immigration control and collected their baggage.","cn":"旅客通过入境检查后领取了自己的行李。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（思想）包袱；成见；偏见","en":"You can use baggage to refer to someone's emotional problems, fixed ideas, or prejudices.","ex":{"en":"How much emotional baggage is he bringing with him into the relationship?","cn":"他背负着多重的感情包袱开始这段恋情？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the cases, bags etc that you carry when you are travelling","cn":""},{"en":"the cases, bags etc that you carry when you are travelling – used especially when the bags are being looked after by an airline , train company etc","cn":""},{"en":"bags that you carry when you are travelling","cn":""}]},"collocations":{"phrases":["ADJ. carry-on, hand | excess At the airport I found that I had 100kg of excess baggage. | emotional, spiritual (figurative) She's still carr","QUANT. item, piece","VERB + BAGGAGE carry | go through, search | check in Where do we check in our baggage? | claim, reclaim Let's claim our baggage first.","BAGGAGE + NOUN allowance | trolley | handler | claim, reclaim the baggage reclaim hall | train Extensive baggage trains followed the troops."]},"media":{"uk":"media/ldoce/hwd/bre/4/baggage0205.mp3","us":"media/ldoce/hwd/ame/6/baggage.mp3"},"examples":[{"en":"excess baggage (= weighing more than the limit allowed on a plane)","cn":"超重行李（超出乘飞机所允许的重量）"},{"en":"( NAmE ) We loaded our baggage into the car.","cn":"我们把行李装上了汽车。"}],"oxford":{"phon":"ˈbæɡɪdʒ","pos":"noun","senses":[{"en":"bags, cases, etc. that contain somebody's clothes and things when they are travelling","cn":"行李","lab":"North American English","ex":{"en":"excess baggage (= weighing more than the limit allowed on a plane)","cn":"超重行李（超出乘飞机所允许的重量）"}},{"en":"the equipment that an army carries with it","cn":"辎重","ex":{"en":"Extensive baggage trains followed the troops.","cn":"大量辎重列车跟随在部队后面。"}},{"en":"the beliefs and attitudes that somebody has as a result of their past experiences","cn":"（因阅历而形成的）信仰，看法","ex":{"en":"She was carrying a lot of emotional baggage.","cn":"她背负着很多感情包袱。"}}]}},"banana":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"香蕉","en":"Bananas are long curved fruit with yellow skins.","ex":{"en":"...a bunch of bananas.","cn":"一串香蕉"}},{"pos":"ADJ 形容词","cn":"愚蠢的；发狂的；疯狂的","en":"If someone is behaving in a silly or crazy way, or if they become extremely angry, you can say that they are going bananas .","ex":{"en":"People went bananas with boredom","cn":"人们闷得发狂。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long curved tropical fruit with a yellow skin","cn":"香蕉"}]},"vocab":{"pos":"n","senses":[{"en":"A banana is a curved, yellow fruit with a thick skin and soft sweet flesh. If you eat a banana every day for breakfast, your roommate might nickname you \"the monkey.\""}]},"collocations":{"phrases":["ADJ. ripe | green | mashed","QUANT. bunch I bought a small bunch of bananas.","VERB + BANANA eat, have | pick | peel","BANANA + NOUN skin (figurative) The company has acquired an unhappy knack of slipping on banana skins (= being led into making mistakes that"]},"media":{"img":["media/ldoce/img/bananas.jpg","media/thumb/banana.jpg"],"uk":"media/ldoce/hwd/bre/7/brelasdebanana.mp3","us":"media/ldoce/hwd/ame/0/banana.mp3"},"examples":[{"en":"a bunch of bananas","cn":"一串香蕉"}],"oxford":{"phon":"bəˈnɑːnə","pos":"noun","senses":[{"en":"a long curved fruit with a thick yellow skin and that is soft inside, which grows on trees in hot countries","cn":"香蕉","ex":{"en":"a bunch of bananas","cn":"一串香蕉"}}]}},"bayonet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"刺刀","en":"A bayonet is a long, sharp blade that can be fixed to the end of a rifle and used as a weapon."},{"pos":"VERB 动词","cn":"用刺刀刺","en":"To bayonet someone means to push a bayonet into them.","ex":{"en":"The soldiers were ordered by their inhuman officers to bayonet every man they could find.","cn":"毫无人性的军官们命令士兵见人就刺。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long knife that is fixed to the end of a rifle (= long gun ) 〔","cn":"步枪上的〕刺刀﹐枪刺"},{"en":"to push the point of a bayonet into someone","cn":"用刺刀刺"}]},"vocab":{"pos":"n v","senses":[{"en":"A bayonet is a knife attached to the end of a rifle. This makes the rifle capable of even more violence than before."}]},"collocations":{"phrases":["ADJ. fixed troops with fixed bayonets","VERB + BAYONET fix | thrust A bayonet had been thrust through his belly."]},"media":{"uk":"media/ldoce/hwd/bre/8/bayonet_v0205.mp3","us":"media/ldoce/hwd/ame/6/bayonet1.mp3"},"oxford":{"phon":"ˈbeɪənət","pos":"noun","senses":[{"en":"a long, sharp knife that is fastened onto the end of a rifle and used as a weapon in battle","cn":"枪刺；刺刀","ex":{"en":"troops with fixed bayonets","cn":"装备固定刺刀的部队"}},{"en":"to push a bayonet into somebody in order to kill them","cn":"用刺刀刺","ex":{"en":"Innocent civilians had been shot and bayoneted.","cn":"无辜平民遭到枪杀和刺刀刺伤。"},"pos":"verb"}]}},"bail":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"保释金","en":"Bail is a sum of money that an arrested person or someone else puts forward as a guarantee that the arrested person will attend their trial in a law court. If the arrested person does not attend it, the money will be lost.","ex":{"en":"He was freed on bail pending an appeal","cn":"他被取保候审。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"保释","en":"Bail is permission for an arrested person to be released after bail has been paid.","ex":{"en":"He was yesterday given bail by South Yorkshire magistrates.","cn":"昨天南约克郡法院准予他获得保释。"}},{"pos":"VERB 动词","cn":"保释","en":"If someone is bailed, they are released while they are waiting for their trial, after paying an amount of money to the court.","ex":{"en":"He was bailed for probation reports","cn":"他因等待鉴定报告而获得保释。"}},{"pos":"N-COUNT 可数名词","cn":"（板球运动中）三柱门上的横木","en":"In cricket, the bails are the two small pieces of wood that are laid across the top of the stumps to form the wicket."},{"pos":"VERB 动词","cn":"（往外）舀水","en":"If you bail, you use a container to remove water from a boat or from a place which is flooded.","ex":{"en":"We kept her afloat for a couple of hours by bailing frantically.","cn":"我们拼命往外舀水，使它继续漂浮了几个小时。"}},{"pos":"PHRASE 短语","cn":"（囚犯）在保释期间逃跑，弃保潜逃","en":"If a prisoner jumps bail, he or she does not come back for his or her trial after being released on bail.","ex":{"en":"He had jumped bail last year while being tried on drug charges.","cn":"去年他在因涉毒被控告期间弃保潜逃。"}},{"pos":"","cn":"","en":"相关词组：bail out"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"money left with a court of law to make sure that a prisoner will return when their trial starts","cn":"保释金"},{"en":"one of the two small pieces of wood laid on top of the stump s in a game of cricket 〔","cn":"板球〕桩门[三柱门]横木"},{"en":"to get away from a place, country etc where you are in danger, especially when it is difficult to do this because someone is trying to catch you or stop you leaving","cn":""}]},"vocab":{"pos":"1 n v 2 v","senses":[{"en":"Bail can be a verb or a noun. When you bail (verb) someone out of jail, you post money, also known as bail (noun), to assure the authorities that person won't try to run away before going to trial."}]},"collocations":{"phrases":["ADJ. conditional, unconditional | police","VERB + BAIL apply for | allow sb, give sb, grant (sb) She has been granted conditional bail. | set The judge set bail at &pound; 50,000. | g","BAIL + NOUN application | conditions | hostel He was sent to a bail hostel until the case came to court.","PREP. (out) on ~ He committed another robbery while out on bail. | without ~ The accused were held without bail.","PHRASES an application for bail"]},"media":{"uk":"media/ldoce/hwd/bre/9/bail_n0205.mp3","us":"media/ldoce/hwd/ame/1/bail1.mp3"},"examples":[{"en":"He was bailed to appear in court on 15 March.","cn":"他获得保释，定于 3 月 15 日到庭候审。"},{"en":"I'd understand if you wanted to bail out of this relationship.","cn":"如果你想从这种关系中摆脱出来，我可以理解。"}],"oxford":{"phon":"beɪl","pos":"noun","senses":[{"en":"money that somebody agrees to pay if a person accused of a crime does not appear at their trial. When bail has been arranged, the accused person is allowed to go free until the trial.","cn":"保释金；保释","g":"[uncountable]","lab":"especially North American English","ex":{"en":"Can anyone put up bail for you?","cn":"有人保释你吗？"}},{"en":"either of the two small pieces of wood on top of each set of three wooden posts (called stumps)","cn":"三柱门上的横木","g":"[countable, usually plural]"},{"en":"to release somebody on bail","cn":"允许保释（某人）","g":"[transitive, usually passive]","lab":"British English also","ex":{"en":"He was bailed to appear in court on 15 March.","cn":"他获得保释，定于 3 月 15 日到庭应诉。"},"pos":"verb"},{"en":"to leave a place, especially quickly","cn":"（尤指迅速地）离开","g":"[intransitive]","lab":"North American English, informal，，","ex":{"en":"Sorry, I really have to bail.","cn":"对不起，我真得赶紧走了。"},"pos":"verb"},{"en":"to approach somebody and talk to them, often when they do not want this","cn":"与…搭讪（尤指对方不愿意）","g":"[transitive]","lab":"Australian English, New Zealand English, informal，，，，","pos":"verb"}]}},"bake":{"collins":{"senses":[{"pos":"VERB 动词","cn":"烤，烘（面包、糕饼等）","en":"If you bake, you spend some time preparing and mixing together ingredients to make bread, cakes, pies, or other food which is cooked in the oven.","ex":{"en":"How did you learn to bake cakes?","cn":"你怎么学会烘蛋糕的？"}},{"pos":"V-ERG 及物/不及物动词","cn":"烤；烘；焙","en":"When a cake or bread bakes or when you bake it, it cooks in the oven without any extra liquid or fat. →see usage note at:","ex":{"en":"Bake the cake for 35 to 50 minutes","cn":"将蛋糕烘35到50分钟。"}},{"pos":"VERB 动词","cn":"受晒；受炙烤","en":"If places or people become extremely hot because the sun is shining very strongly, you can say that they bake .","ex":{"en":"If you closed the windows you baked","cn":"如果把窗户关上，你会热死的。"}},{"pos":"N-COUNT 可数名词","cn":"（蔬菜或鱼与其他配料切碎拌和后经烘烤的）烤菜","en":"A vegetable or fish bake is a dish that is made by chopping up and mixing together a number of ingredients and cooking them in the oven so that they form a fairly dry solid mass.","ex":{"en":"...an aubergine bake.","cn":"烤茄子"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to cook things such as bread or cakes in an oven","cn":""},{"en":"to cook meat or vegetables in an oven","cn":""},{"en":"to cook food in hot oil","cn":""}]},"collocations":{"phrases":["PHRASES freshly/newly baked The house was filled with the scent of freshly baked bread."]},"media":{"uk":"media/ldoce/hwd/bre/6/bake0205.mp3","us":"media/ldoce/hwd/ame/1/bake.mp3","img":["media/thumb/bake.jpg"]},"examples":[{"en":"We sat baking in the sun.","cn":"我们坐在太阳底下晒得热死了。"},{"en":"I'm baking a birthday cake for Alex.","cn":"我在给亚历克斯烤生日蛋糕。"}],"oxford":{"phon":"beɪk","pos":"verb","senses":[{"en":"to cook food in an oven without extra fat or liquid; to be cooked in this way","cn":"（在烤炉里）烘烤；焙","g":"[transitive, intransitive]","lab":"British English","ex":{"en":"to bake bread/biscuits/cookies","cn":"烤面包；烤饼干；烤曲奇饼"}},{"en":"to become hard when heated; to make something hard by heating it","cn":"（遇热）变硬；（将某物）烤硬","g":"[intransitive, transitive]","ex":{"en":"The bricks are left in the kiln to bake.","cn":"砖坯放在窑里烧。"}},{"en":"to be or become very hot","cn":"（变得）灼热，炎热","g":"[intransitive]","lab":"informal","ex":{"en":"We sat baking in the sun.","cn":"我们坐在太阳底下晒得热死了。"}},{"en":"a dish consisting of mixed ingredients that is cooked in the oven","cn":"烘烤食品","ex":{"en":"a pasta/vegetable bake","cn":"烤意大利面；烤蔬菜"},"pos":"noun"},{"en":"a social event at which a specific food is cooked and eaten","cn":"烧烤聚餐会","lab":"North American English","ex":{"en":"a clam bake","cn":"烤蛤蜊"},"pos":"noun"}]}},"bash":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"盛会；聚会；庆祝仪式","en":"A bash is a party or celebration, especially a large one held by an official organization or attended by famous people.","ex":{"en":"He threw one of the biggest showbiz bashes of the year as a 36th birthday party for Jerry Hall.","cn":"为了庆祝杰里·霍尔的36岁生日，他举办了当年演艺圈最盛大的庆祝宴会。"}},{"pos":"VERB 动词","cn":"痛打；猛揍","en":"If someone bashes you, they attack you by hitting or punching you hard.","ex":{"en":"If someone tried to bash my best mate they would have to bash me as well","cn":"如果谁想揍我最好的朋友，那我就跟他拼了。"}},{"pos":"VERB 动词","cn":"猛敲；猛撞；用力砸","en":"If you bash something, you hit it hard in a rough or careless way.","ex":{"en":"Too many golfers try to bash the ball out of sand. That spells disaster","cn":"太多高尔夫球手都想把球从沙子里敲出来，结果酿成了一场灾难。"}},{"pos":"N-COUNT 可数名词","cn":"重击；猛撞","en":"If you get a bash on a part of your body, someone or something hits you hard, or you bump into something."},{"pos":"VERB 动词","cn":"（通常指公开地）痛斥，抨击","en":"To bash someone means to criticize them severely, usually in a public way.","ex":{"en":"The President could continue to bash Democrats as being soft on crime.","cn":"总统可能会继续抨击民主党人对待犯罪活动心慈手软。"}},{"pos":"N-COUNT 可数名词","cn":"努力；尝试","en":"If you have a bash at something, you try to do it.","ex":{"en":"He's prepared to have a bash at discussing it intelligently.","cn":"他已经准备好尽量巧妙地讨论这个问题。"}},{"pos":"","cn":"","en":"相关词组：bash in bash out bash up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to hit a door or window with your closed hand in order to attract the attention of the people inside","cn":""},{"en":"to hit a surface. Strike is more formal than hit and is mainly used in written English","cn":""},{"en":"to hit something very hard","cn":""}]},"collocations":{"phrases":["ADV. hard She bashed him so hard she broke his nose.","PREP. on Someone bashed him on the nose. | with She bashed him with her book.","PHRASES bash sb about/up He had been attacked and bashed about a bit."]},"media":{"uk":"media/ldoce/hwd/bre/f/bash_v0205.mp3","us":"media/ldoce/hwd/ame/f/bash1.mp3"},"examples":[{"en":"We'll never get finished at this rate. We'd better bash on.","cn":"以这种速度我们永远也完成不了。我们最好加把劲。"},{"en":"I'm not sure I'll be any good but I'll have a bash.","cn":"我不敢保证我能帮上什么忙，但我会试试。"}],"oxford":{"phon":"bæʃ","pos":"verb","senses":[{"en":"to hit somebody/something very hard","cn":"猛击；猛撞","g":"[transitive, intransitive]","ex":{"en":"He stood up, bashing his head on the ceiling.","cn":"他站起来，把头撞在天花板上。"}},{"en":"to criticize somebody/something strongly","cn":"严厉批评","g":"[transitive]","ex":{"en":"Bashing politicians is normal practice in the press.","cn":"严厉批判政治人物乃是新闻界常事。"}},{"en":"a hard hit","cn":"猛击；重击","ex":{"en":"He gave Mike a bash on the nose.","cn":"他照着迈克的鼻子狠狠地给了一下。"},"pos":"noun"},{"en":"a large party or celebration","cn":"盛大的聚会；盛典","ex":{"en":"a birthday bash","cn":"生日庆典"},"pos":"noun"}]}},"barley":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"大麦","en":"Barley is a grain that is used to make food, beer, and whisky.","ex":{"en":"...fields of ripening wheat and barley.","cn":"一片片正在成熟的小麦和大麦"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a plant that produces a grain used for making food or alcohol","cn":"大麦"}]},"collocations":{"phrases":["ADJ. malted/malting Malt whisky is made from malted barley. | roast/roasted | pearl | spring, winter","QUANT. ear | field","VERB + BARLEY grow | sow | cut, harvest | thresh | grind","BARLEY + VERB grow | ripen","BARLEY + NOUN harvest | field"]},"media":{"uk":"media/ldoce/hwd/bre/8/brelasdebarley.mp3","us":"media/ldoce/hwd/ame/8/barley.mp3","img":["media/thumb/barley.jpg"]},"oxford":{"phon":"ˈbɑːli","pos":"noun","senses":[{"en":"a plant grown for its grain that is used for making food, beer and whisky; the grains of this plant","cn":"（皮）大麦；大麦粒","ex":{"en":"Feed barley prices are set to rise.","cn":"饲料用大麦的价格要上涨。"}}]}},"banned":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a banned political organization is one that is forbidden to meet or exist","cn":""},{"en":"a political organization that is outlawed is completely forbidden to operate because it is considered extremely bad or dangerous","cn":""},{"en":"an illegal political organization is forbidden to operate by law","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/banned0205.mp3","us":"media/ldoce/hwd/ame/9/laadbanned.mp3"},"examples":[{"en":"Leaders of the banned party were arrested last night.","cn":"被取缔党派的领导人昨晚被捕。"},{"en":"He was suspended for using a banned substance (= a drug that people competing in sport are not allowed to take ) .","cn":"他因为使用违禁药物而被禁赛。"}]}});
